(window.GIM_TS=window.GIM_TS||{})["Bekhorot.1"]={"from":24,"a":[["\u0003כל הקדשים שקדם מום קבוע להקדשן,\u0004 שהקדישם למזבח כשכבר היה בהם מום, ומתחילה לא נתקדשו כקרבן, אלא כדי למוכרם ולהביא בדמיהם קרבן כשר, \u0003ונפדו\u0004 מיד ההקדש — הרי הם \u0003חייבין בבכורה\u0004 אם ילדו, כדין בהמות חולין, \u0003ובמתנות\u0004 כהונה, כלומר, בנתינת זרוע לחיים וקיבה שנותנים לכהן מכל בהמת חולין שנשחטה, \u0003ו\u0004כשנפדים הריהם \u0003יוצאין לחולין ליגזז וליעבד,\u0004 שמותר לגוז את צמרם ולעבוד בהם. וכן \u0003ולדן וחלבן מותר לאחר פדיונן. ו\u0004אף קודם שנפדו, הואיל ואינם ראויים להקרבה —","\u0003השוחטן בחוץ\u0004 (מחוץ לעזרה שבמקדש) \u0003פטור,\u0004 ואינו בכלל שוחט קדשים בחוץ, וכן \u0003אין\u0004 הם \u0003עושין תמורה,\u0004 שאם אמר על בהמת חולין שתהא תמורתה — אין ההיא קדושה. \u0003ואם מתו\u0004 ברשות ההקדש — \u0003יפדו,\u0004 ואינם טעונים קבורה. וכל זה \u0003חוץ מן הבכור ומן המעשר,\u0004 שאפילו היו בעלי מום בשעה שנתקדשו — דינם כקדשים שקדם הקדשם את מומם.","\u0003וכל\u0004 הקדשים \u0003שקדם הקדשן את מומן,\u0004 שכשנתקדשו היו ראויים להקרבה על המזבח ורק אחר כך נעשו בעלי מום, \u0003או\u0004 שקדם \u0003מום עובר להקדשן ו\u0004רק \u0003לאחר מכן נולד להן מום קבוע, ונפדו\u0004 — לא ירדה קדושת הקרבן מהם לגמרי, גם לאחר פדיונם, ולכן הם \u0003פטורין מן הבכורה ומן המתנות, ואינן יוצאין\u0004 בפדיונם \u0003לחולין\u0004 כדי \u0003ליגזז וליעבד,\u0004 וכן","\u0003ולדן וחלבן אסור\u0004 גם \u0003לאחר פדיונן, והשוחטן בחוץ\u0004 קודם פדיונם — \u0003חייב, ועושין תמורה, ואם מתו\u0004 לפני שהספיק לפדותם — לא ניתן עוד לפדותם, אלא \u0003יקברו.\u0004","שנינו במשנה שקדשים שקדם מום להקדשם ונפדו — חייבים בבכורה ובמתנות. ומדייקים: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום ש\u0003נפדו,\u0004 ויצאו לגמרי לחולין הריהם חייבים בבכורה ובמתנות, \u0003הא\u0004 \u0005[אבל\u0006\u0005]\u0006 אם \u0003לא נפדו\u0004 — \u0003פטורין מן הבכורה ומן המתנות.\u0004 ומעירים, \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 התנא: \u0003קדושת דמים\u0004 שיש בבהמה, שהיא שייכת להקדש, גם אם אין גופה קדוש להקרבה, \u0003מדחה,\u0004 כלומר, פוטרת אותה \u0003מן הבכורה ומן המתנות.\u0004","שנינו במשנה: קדשים שקדם מום קבוע להקדשם ונפדו — \u0003יוצאין לחולין\u0004 ליגזז וליעבד. ומדייקים: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום ש\u0003נפדו, הא\u0004 \u0005[אבל]\u0006 אם \u0003לא נפדו\u0004 — \u0003אסירי\u0004 \u0005[אסורים]\u0006 \u0003בגיזה ועבודה,\u0004 וכדין קרבן, למרות שאין בהם קדושת קרבן (קדושת הגוף) אלא קדושת דמים. ושואלים: האם זה \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לר' אליעזר\u0004 ש\u0003אמר: קדשי בדק הבית,\u0004 בהמות שהוקדשו לצרכי המקדש, וקדושתם קדושת דמים היא — \u0003אסורין בגיזה ועבודה?\u0004","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003לא, קדושת דמים למזבח הוא דמיחלפא\u0004 \u0005[שמתחלפת]\u0006 \u0003בקדושת הגוף למזבח,\u0004 ולכן \u0003גזרו בהו רבנן\u0004 \u0005[בהם חכמים]\u0006 במשנתינו, בבהמות בעלות מום שהוקדשו למזבח, לאוסרן בגיזה ועבודה, שמא יבואו אנשים לגזוז ולעבוד בהמות שנפל בהם מום לאחר שהוקדשו, ודבר זה אסור מן התורה. \u0003אבל קדשי בדק הבית\u0004 — \u0003לא\u0004 גזרו בהם.","עוד שנינו במשנה בענין בעלי מום שהוקדשו למזבח: \u0003ולדן וחלבן מותר\u0004 בהנאה לאחר פדיונן. ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005מדובר]\u0006 שולדן מותר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 במקרה \u0003דאיעבר ואתיליד\u0004 \u0005[ש\u0006גם \u0005התעברו, ו\u0006גם \u0005נולדו]\u0006 הולדות \u0003לאחר\u0004 \u0003פדיונן\u0004 — \u0003פשיטא\u0004 \u0005[פשוט\u0006 שכך הוא\u0005],\u0006 הלוא \u0003חולין\u0004 גמורים \u0003נינהו\u0004 \u0005[הם]!\u0006 \u0003אלא\u0004 מדובר \u0003דאיעבר\u0004 \u0005[שהתעברו]\u0006 \u0003לפני פדיונן, ואתיליד\u0004 \u0005[ונולדו]\u0006 הולדות \u0003לאחר פדיונן.\u0004","ונדייק מכאן: \u0003הא\u0004 \u0005[אבל]\u0006 אם נולדו \u0003לפני פדיונן\u0004 — \u0003אסירי\u0004 \u0005[אסורים]\u0006 הולדות בהנאה עד שייפדו."],["ושואלים: האם הולדות הללו, שנולדו לפני פדיונם, \u0003נפדין\u0004 כשהם \u0003תמימים, או אין נפדין תמימין,\u0004 וצריך להמתין להם שייפול בהם מום, ואז ייפדו, כדין קדשי מזבח?","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר, ממה ששנינו בברייתא: \u0003המתפיס\u0004 (המקדיש) \u0003בעלי מומין קבועין לגבי\u0004 (לשם) ה\u0003מזבח וילדו\u0004 — \u0003ימכרו\u0004 הולדות, \u0003ואין צריכין\u0004 להמתין שיפול בהם \u0003מום\u0004 כדי להיפדות, מפני \u0003שאין קדושה\u0004 (קדושת הגוף) \u0003חלה עליהן.\u0004 וטעם הדבר — \u0003שלא\u0004 ייתכן ש\u0003יהא\u0004 ה\u0003טפל,\u0004 הולד, \u0003חמור מן העיקר,\u0004 האם, שאינה קדושה בקדושת הגוף.","ומעירים, מברייתא זו יש לדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום \u0003שלא יהא טפל חמור מן העיקר,\u0004 ולכן אין הולד קדוש בקדושת הגוף, למרות שהוא עצמו תמים וראוי להקרבה. \u0003אבל\u0004 במקום ששיקול זה אינו קיים, וכגון אם \u0003הקדיש זכר\u0004 תמים למזבח, אבל לא להקרבה, אלא \u0003לדמיו,\u0004 הואיל והוא ראוי להקרבה — \u0003קדוש\u0004 הוא עצמו ב\u0003קדושת הגוף,\u0004 וקרב כעולה (ואינו נפדה אלא אם נפל בו מום). ומוסיפים: הרי זה \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003ל\u0004דברי \u0003רבא,\u0004 ש\u0003אמר רבא: הקדיש זכר\u0004 תמים \u0003לדמים,\u0004 ולא כדי שיקרב בעצמו — \u0003קדוש קדושת הגוף\u0004 למזבח.","שנינו במשנה לגבי מקדיש בעלי מום למזבח: \u0003והשוחטן בחוץ פטור.\u0004 ומעירים: \u0003ר' אלעזר מתני\u0004 \u0005[\u0006היה \u0005שונה]\u0006 כאן \u0003\"חייב\", ומוקי לה\u0004 \u0005[מעמיד אותה]\u0006 במקדיש בעל מום ושוחטו \u0003בבמת יחיד,\u0004 כלומר, במזבח שבונה כל אדם לעצמו ומקריב עליו, בזמן שהיו הבמות מותרות, קודם שנבנה המקדש.","ש\u0003אמר ר' אלעזר: מנין לזובח\u0004 (שוחט) \u0003בהמה בעלת מום בבמת יחיד בשעת היתר הבמות, שהוא\u0004 עובר עליה \u0003ב\u0004איסור \u0003לא תעשה? שנאמר: \"לא תזבח לה' אלהיך שור ושה\u0004 אשר יהיה בו מום\" (דברים יז, א), \u0003אם אינו ענין ל\u0004איסור זביחת בעל מום ב\u0003במה גדולה,\u0004 בבמת הציבור, \u0003דכתיב\u0004 \u0005[ש\u0006הרי כבר \u0005נאמר]\u0006 הדבר לגבי הקרבה במשכן: \u0003\"עורת או שבור וגו'\u0004 לא תקריבו אלה לה' \" (ויקרא כב, כב) — \u0003תנהו ענין לבמת יחיד,\u0004 ללמד שאסור לזבוח בעלי מומים גם שם.","ושואלים: ומדוע אתה דורש כתוב זה לענין במת יחיד? יכול אתה לדורשו באופן כללי לגבי איסור זביחת בעל מום, \u0003אימא\u0004 \u0005[\u0006ו\u0005אמור\u0006 כך\u0005]:\u0006 \u0003אם אינו ענין לקדשים\u0004 — \u0003תנהו ענין לבכור.\u0004 ואף שבכור מכלל הקדשים הוא — הוצרך לכתוב מיוחד, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ו\u0004בכור \u0003קדוש\u0004 בבכורה גם \u0003כשהוא בעל מום\u0004 — \u0003ליקרב נמי\u0004 \u0005[שיקרב גם כן]\u0006 \u0003כשהוא בעל מום, קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 ש\u0003לא!\u0004","בתשובה לכך \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003בכור בהדיא כתיב ביה\u0004 \u0005[במפורש כתוב בו]: \"וכי יהי בו מום\u0006 \u0003פסח או עור\u0004 כל מום רע \u0003לא תזבחנו\"\u0004 (דברים טו, כא), ולא הוצרך לכתוב זה.","ועוד שואלים: \u0003ואימא\u0004 \u0005[ואמור\u0006 כך\u0005]:\u0006 \u0003אם\u0004 כתוב זה \u0003אינו ענין לקדשים\u0004 — \u0003תנהו ענין למעשר\u0004 בהמה. \u0003דסלקא דעתך אמינא\u0004 \u0005[ש\u0006כן \u0005יעלה על דעתך לומר]:\u0006 \u0003הואיל ו\u0004מעשר \u0003קדוש במומו, דכתיב\u0004 \u0005[שנאמר]\u0006 בו: \u0003\"לא יבקר בין טוב לרע\"\u0004 (ויקרא כז, לג), כלומר, בין הוא תמים (\"טוב\") ובין אם הוא בעל מום (\"רע\") הריהו קדוש — \u0003נקרב נמי במומיה\u0004 \u0005[שיקרב גם כן במומו],\u0006 \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 ש\u0003לא!\u0004","בתשובה לכך \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003מעשר נמי\u0004 \u0005[גם כן]\u0006 \u0003גמר\u0004 \u0005[למד\u0006\u0005]\u0006 דין זה בגזירה שווה \u0003העברה העברה מבכור,\u0004 שבבכור נאמר: \"והעברת\" (שמות יג, יב), ובמעשר נאמר: \"כל אשר יעבור\" (ויקרא כז, לב). ואף הוא לא הוצרך לכתוב זה.","ושואלים עוד, \u0003אימא\u0004 \u0005[אמור]:\u0006 אם כתוב זה אינו ענין לקדשים, \u0003תנהו ענין לתמורת קדשים\u0004 כשאומר על בהמת חולין שתהא תמורת בהמת קרבן, ללמד שאין מקריבים אותה כשהיא בעלת מום. \u0003דסלקא דעתך אמינא\u0004 \u0005[שיעלה על דעתך לומר]:\u0006 \u0003הואיל ו\u0004תמורה \u0003קדושה\u0004 גם \u0003כשהיא בעלת מום, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לא יחליפנו ולא ימיר אתו\u0004 טוב ברע או רע בטוב, ואם המר ימיר בהמה בבהמה והיה הוא ותמורתו יהיה קודש\" (ויקרא כו,לב) — \u0003קריבה נמי\u0004 \u0005[גם כן]\u0006 \u0003כשהיא בעלת מום,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 ש\u0003לא!\u0004","ומשיבים: גם לשם כך אין צורך בכתוב מיוחד, שהרי כבר \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"והיה הוא ותמורתו\u0004 יהיה קודש\" (ויקרא כו,לב), ובכך \u0003מקיש\u0004 (משווה) הכתוב \u0003תמורתו\u0004 של קרבן \u0003לו,\u0004 לקרבן עצמו: \u0003מה הוא\u0004 עצמו, כשהוא \u0003בעל מום לא\u0004 יקרב, \u0003אף תמורתו\u0004 — \u0003בעל מום לא.\u0004 ונמצא הכתוב \"לא תזבח לה' אלהיך שור ושה אשר יהיה בו מום\" מיותר איפוא, לדרוש ממנו איסור זביחת בעל מום בבמת יחיד, כפי שדרש ר' אלעזר.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' זירא, אימא\u0004 \u0005[אמור\u0006 כך\u0005]:\u0006 אם כתוב זה אינו ענין לקדשים — \u0003תנהו ענין לולדות קדשים,\u0004 שנולדו כשהם בעלי מומים, ללמד שאסור להקריבם. \u0003דסלקא דעתך אמינא\u0004 \u0005[ש\u0006כן \u0005יעלה על דעתך לומר]:\u0006 \u0003הואיל וקדושין כשהן\u0004 נולדים \u0003בעלי מומין אגב\u0004 קדושת \u0003אמן,\u0004 אם כן \u0003כשהן בעלי מומין נמי קרבי\u0004 \u0005[גם כן קרבים],\u0006 \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 ש","\u0003לא! אמר רבא:\u0004 גם לשם הלכה זו לא הוצרכנו לכתוב זה, שכן \u0003כבר פסקה\u0004 \u0005[פסק אותה]\u0006 ה\u0003תנא דבי\u0004 \u0005[מבית\u0006 מדרשו של\u0005]\u0006 \u0003ר' ישמעאל\u0004 מכתוב אחר. \u0003דתנא דבי\u0004 \u0005[ש\u0006כך שנה \u0005התנא מבית\u0006 מדרשו של\u0005]\u0006 \u0003ר' ישמעאל\u0004 על הפסוק: \u0003\"רק קדשיך אשר יהיו לך ונדריך\u0004 תשא ובאת אל המקום אשר יבחר ה' \"(דברים יב, כו), \u0003\"רק קדשיך\"\u0004 — \u0003אלו התמורות, \"אשר יהיו לך\"\u0004 — \u0003אלו הוולדות,\u0004 שגם אלו קרבים על המזבח, \u0003\"ונדריך\"\u0004 — \u0003הקישן\u0004 (השוה אותם) \u0003הכתוב\u0004 את התמורות והולדות \u0003לנדר, מה נדר בעל מום לא\u0004 יקריב, \u0003אף הני נמי\u0004 \u0005[אלה גם כן]\u0006 — \u0003בעל מום לא\u0004 יקרבו.","שנינו במשנה לגבי בהמות שהוקדשו כשהן בעלות מום: \u0003ואין עושין תמורה,\u0004 שאם אמר על בהמת חולין שתהא תמורתה — אין בהמת החולין קדושה. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מהו הטעם,\u0006 המקור] לדין זה? ש\u0003אמר קרא\u0004 \u0005[הכתוב] בדין התמורה:\u0006 \u0003\"לא יחליפנו ולא ימיר אתו\u0004 טוב ברע או רע בטוב\" (ויקרא כז, י), ויש לשאול: מדוע הוצרך להזכיר \"טוב ברע\"? \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003רע בטוב,\u0004 בהמת קדשים בעלת מום בבהמת חולין תמימה, \u0003אמרת\u0004 \u0005[אומר אתה]\u0006 ש\u0003לא\u0004 ימיר, ואם המיר — עושה תמורה, למרות שהיא עצמה אינה ראויה להקרבה; כשממיר \u0003טוב ברע,\u0004 בהמת קדשים תמימה, שראויה להקרבה, בבהמת חולין בעלת מום, \u0003מיבעיא\u0004 \u0005[צריך לומר]\u0006 שהוא עושה תמורה? \u0003אלא\u0004 \"טוב ברע\" בא ללמדנו דין אחר: דווקא בעל מום שהוא \u0003טוב מעיקרו,\u0004 בשעה שהוקדש — \u0003עושה תמורה,\u0004 אבל \u0003רע מעיקרו,\u0004 שהוקדש כשכבר היה בעל מום — \u0003אין עושה תמורה.\u0004","שנינו במשנה לגבי מקדיש בעלי מום למזבח: \u0003אם מתו\u0004 — \u0003יפדו. אמר רב יהודה אמר רב: זו,\u0004 ששנינו שייפדו — \u0003דברי ר' שמעון\u0004 היא, ש\u0003אמר:\u0004 דווקא \u0003קדשי מזבח היו בכלל העמדה והערכה,\u0004 שכשרוצים לפדותם צריך להעמידם לפני הכהן כדי שיעריך אותם. ולכן, כשמתו, ולא ניתן להעמידם — לא ניתן לפדותם, אלא ייקברו. אבל \u0003קדשי בדק הבית לא היו בכלל העמדה והערכה,\u0004 ולכן אם מתו ייפדו, וכפי","\u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005],\u0006 \u0003ר' שמעון אומר: קדשי בדק הבית, אם מתו\u0004 — \u0003יפדו. ומכל מקום,\u0004 למרות שלדעת ר' שמעון קדשי מזבח היו בכלל העמדה והערכה, \u0003מודה ר' שמעון בבעל מום מעיקרו,\u0004 שהקדישו למזבח כשהוא בעל מום, ומת — \u0003ש\u0004הוא \u0003נפדה. מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 מהו המקור לכך בכתוב? ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"והעמיד את הבהמה והעריך הכהן אותה\" (ויקרא כז, יא—יב), ולמדים: \u0003\"אותה\"\u0004 — \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003בעל מום מעיקרא\u0004 \u0005[מתחילתו],\u0006 שאינו בכלל העמדה והערכה.","\u0003אבל חכמים אומרים:\u0004 קדשי מזבח, גם אם הקדישם כשהם בעלי מום — צריכים העמדה והערכה, ולכן \u0003אם מתו\u0004 — \u0003יקברו.\u0004 ואומרים: \u0003מאן\u0004 \u0005[מי\u0006 הם\u0005]\u0006 \u0003חכמים\u0004 אלו — \u0003תנא דבי\u0004 \u0005[התנא של בית\u0006 מדרשו של\u0005]\u0006 \u0003לוי הוא,\u0004 ששנה כך בברייתות שבידו. \u0003דתנא דבי\u0004 \u0005[ש\u0006כך \u0005שנה\u0006 התנא \u0005של בית\u0006 מדרשו של\u0005]\u0006 \u0003לוי: הכל,\u0004 כל הבהמות שהוקדשו למזבח, \u0003היו בכלל העמדה והערכה\u0004 שהצריך הכתוב כדי לפדותם, \u0003ואפילו\u0004 היה \u0003בעל מום מעיקרו\u0004 כשהוקדש למזבח.","\u0003וכן תנא דבי\u0004 \u0005[\u0006שנה \u0005התנא של בית\u0006 מדרשו של\u0005]\u0006 \u0003לוי במתניתיה\u0004 \u0005[במשנתו]:\u0006 \u0003אפילו חיה אפילו עוף,\u0004 שאינם עומדים להקרבה, צריכים העמדה והערכה כדי לפדותם. ומקשים: כיצד הוא אומר שהכל היו בכלל העמדה והערכה? \u0003והכתיב\u0004 \u0005[והרי כתוב]\u0006 \"והעריך \u0003אתה\",\u0004 ומלה זו באה למעט! ומשיבים: אכן, \u0003\"אתה\" לתנא דבי\u0004 \u0005[לתנא של בית\u0006 מדרשו של\u0005]\u0006 \u0003לוי קשיא\u0004 \u0005[קשה].\u0006","ומתקשים: מתוך שהוצרכנו לומר, כי דעת \"חכמים\" הרי זו דעת תנא דבי לוי, משמע כי דווקא תנא דבי לוי חלוק על ר' שמעון, \u0003אבל רבנן דפליגי עליה\u0004 \u0005[חכמים שחולקים עליו]\u0006 על \u0003ר' שמעון\u0004 במשנה במסכת תמורה, וסבורים כי קדשי מזבח אינם טעונים העמדה והערכה, \u0003מאי\u0004 \u0005[מה\u0006 דעתם\u0005]?\u0006 \u0003הכי נמי\u0004 \u0005[כך גם כן],\u0006 סבורים הם כר' שמעון, שבעלי מום מעיקרם, \u0003אם מתו\u0004 — \u0003יפדו? אי הכי\u0004 \u0005[אם כן],\u0006"],["\u0003\"זו דברי ר' שמעון ומחלוקתו\u0004 (והחולקים עליו)\"\u0003מיבעיא ליה\u0004 \u0005[צריך היה לו]\u0006 לרב לומר ביחס למשנתנו, ולא רק \"זו דברי ר' שמעון\"!","בתשובה לכך \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003רב\u0004 לא היה יכול לומר כן, משום שהוא סבור \u0003כר' שמעון בן לקיש,\u0004 ש\u0003אמר\u0004 כי \u0003ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 אלו, רק \u0003קדשי בדק הבית היו בכלל העמדה והערכה,\u0004 אבל \u0003קדשי מזבח לא היו בכלל העמדה והערכה. ו\u0004לפיכך \u0003לא מיתוקמא מתניתין כרבנן\u0004 \u0005[לא ניתן להעמיד את משנתנו כ\u0006שיטת \u0005חכמים],\u0006 \u0003דקתני סיפא\u0004 \u0005[ש\u0006הרי התנא \u0005שונה בסוף\u0006 המשנה\u0005],\u0006 ביחס לקדשי מזבח: \u0003ואם מתו יקברו,\u0004 ומכאן שלדעתו הם צריכים העמדה והערכה כדי לפדותם, ולכן כשמתו ולא ניתן להעמידם — לא ייפדו, אלא ייקברו.","ודוחים: \u0003אמר\u0004 \u0005[אמור,\u0006 יכול אתה לומר\u0005]\u0006 ולהקשות: \u0003ממאי דהא\u0004 \u0005[מנין שזה]\u0006 שהתנא שונה שאם \u0003מתו יקברו, משום דבעי\u0004 \u0005[שצריך]\u0006 \u0003העמדה והערכה הוא? דלמא\u0004 \u0005[שמא]\u0006 \u0003משום שאין פודין את הקדשים\u0004 כדי \u0003להאכילן לכלבים הוא,\u0004 שהרי כשהוא פודה אותם לאחר מותם אינם ראויים למאכל אדם, אלא לכלבים, ויש בכך זלזול בקדשים! \u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: \u0003אם כן,\u0004 שזאת הסיבה שאין פודים אותם, ולא משום שצריכים העמדה והערכה, מדוע שנה התנא דין זה במקרה שמתו? \u0003ניתני\u0004 \u0005[שישנה]:\u0006 \u0003אם נעשו טריפה,\u0004 ועדיין ראויים הם להעמדה והערכה, שהרי חיים הם — לא יפדו, אלא \u0003יקברו\u0004 (לכשימותו), משום שאינם ראויים לאכילת אדם, ואין פודים את הקדשים להאכילם לכלבים.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם רב כר' יוחנן סבירא ליה\u0004 \u0005[סבור הוא],\u0006 שחכמים החולקים על ר' שמעון סבורים גם הם שקדשי מזבח היו בכלל העמדה והערכה, ואם מתו ייקברו. וניתן איפוא, להעמיד את המשנה כשיטתם. \u0003ו\u0004לפי זה \u0003תני\u0004 \u0005[שנה]\u0006 בדברי רב: \u0003זו,\u0004 משנתנו, ששנינו בה שבעלי מום מעיקרם, אם מתו ייפדו — \u0003דברי ר' שמעון ומחלוקתו\u0004 היא.","שנינו במשנה: \u0003אבל\u0004 קדשים בעלי מום ש\u0003קדם הקדשן\u0004 את מומם, פטורים גם לאחר שנפדו מן הבכורה ומן המתנות (ליתן לכהן זרוע לחיים וקיבה). ומבררים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 מהו המקור לכך בתורה? \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים],\u0006 נאמר בענין קדשים אלו: \"אך כאשר יאכל את הצבי ואת האיל כן תאכלנו\" (דברים יב,כב), ומהשוואה זו לצבי ואיל יש ללמוד: \u0003\"צבי\", מה צבי פטור מן הבכורה,\u0004 לפי שהוא מין חיה, ורק בהמה חייבת בבכורה — \u0003אף פסולי המוקדשין פטורין מן הבכורה.\u0004","ויש לשאול: שמא \u0003אוציא אני את הבכורה\u0004 בלבד, \u0003ש\u0004פסולי המוקדשים \u0003אינם חייבים בה, ולא אוציא את המתנות! תלמוד לומר: \"איל\", מה איל פטור מן הבכורה ומן המתנות,\u0004 שאינן נוהגות אלא בבהמה, ולא בחיה — \u0003אף פסולי המוקדשין פטורין מן הבכורה ומן המתנות.\u0004","ויש לשאול: לדרך זו, \u0003אי\u0004 (מה) \u0003צבי ואיל חלבן מותר,\u0004 שאין איסור חלב נוהג אלא בבהמה טהורה, ולא בחיה — \u0003אף פסולי המוקדשין יהא חלבן מותר! תלמוד לומר\u0004 בתחילת כתוב זה: \u0003\"אך\",\u0004 שהיא לשון מיעוט, ובכך \u0003חלק\u0004 הכתוב ולימד שאין ההשוואה מלאה. ודנים בפרטי הברייתא.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 שמא \u0003אוציא את הבכור,\u0004 שאינו נוהג בפסולי המוקדשים, \u0003ולא אוציא את המתנות.\u0004 ומסבירים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 זה שהוא אומר \u0003אוציא את הבכור\u0004 — \u0003משום שאין שוה בכל,\u0004 שאינו נוהג אלא בזכרים ולא בנקבות, \u0003ולא אוציא את המתנות\u0004 — \u0003ששוות בכל,\u0004 שגם השוחט נקבה חייב במתנותיה — \u0003תלמוד לומר: \"איל\",\u0004 ללמד שגם מתנות אינן נוהגות בהם. ועוד שנו בברייתא: אי מה צבי ואייל חלבו מותר אף פסולי המוקדשין יהא חלבן מותר — תלמוד לומר \"אך\" לחלק.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי:\u0004 מדוע לא הציעו בברייתא כך: \u0003אי מה צבי ואיל, אין\u0004 איסור שחיטת \u0003אותו ואת בנו\u0004 ביום אחד \u0003נוהג בהן,\u0004 שאינו נוהג אלא בבהמה — \u0003אף פסולי המוקדשין אין אותו ואת בנו נוהג בו!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003למאי מדמית להו\u0004 \u0005[למה אתה מדמה אותם]\u0006 את פסולי המוקדשים, שאתה בא לפוטרם מדין זה? \u0003אי\u0004 \u0005[אם]\u0006 \u0003לחולין\u0004 — \u0003\"אותו ואת בנו\" נוהג בו, ואי\u0004 \u0005[ואם]\u0006 \u0003לקדשים\u0004 — גם כן \u0003\"אותו ואת בנו\" נוהג בו!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב פפא: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 איסור \u0003חלבו נמי נימא הכי\u0004 \u0005[גם כן נאמר כך]:\u0006 \u0003למאי מדמית להו\u0004 \u0005[למה אתה מדמה אותם],\u0006 שאתה בא לפוטרם מדין זה? \u0003אי\u0004 \u0005[אם]\u0006 \u0003לחולין\u0004 — הרי \u0003חלבן אסור, ואי\u0004 \u0005[ואם]\u0006 \u0003לקדשים\u0004 — גם כן \u0003חלבן אסור!\u0004","\u0003אלא, לאו מי אמרת\u0004 \u0005[האם אין אתה אומר]\u0006 שהוצרכנו ל\u0003\"אך\"\u0004 למעט, וללמדנו: \u0003ולא חלבן,\u0004 שאין משווים פסולי המוקדשים בעניין זה לצבי ואיל? לפי זה, \u0003אימר נמי\u0004 \u0005[אמור גם כן]:\u0006 \u0003\"אך\"\u0004 — \u0003ולא אותו ואת בנו,\u0004 שלענין זה לא הושוו פסולי המוקדשים לצבי ואייל!","\u0003רבא אמר,\u0004 בתשובה לשאלת רב פפא: באמת \u0003\"אך\"\u0004 — \u0003ל\u0004איסור \u0003אותו ואת בנו\u0004 בפסולי המוקדשים \u0003הוא דאתא\u0004 \u0005[שבא],\u0006 \u0003ו\u0004איסור אכילת \u0003חלבו\u0004 — \u0003מ\"דמו\" נפקא\u0004 \u0005[יוצא,\u0006 נלמד]. \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בבכור בעל מום, שאף הוא מכלל פסולי המוקדשין: \"בשעריך תאכלנו וכו' כצבי וכאיל, \u0003רק את דמו לא תאכל\"\u0004 (דברים טו, כב—כג), ויש לשאול:","\u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"דמו\"? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003דמו ממש,\u0004 מדוע הוצרך לאוסרו? \u0003לא יהא אלא דמן\u0004 של \u0003צבי ואיל, אטו\u0004 \u0005[וכי]\u0006 \u0003דמן\u0004 של \u0003צבי ואיל מי שרי\u0004 \u0005[האם\u0006 הוא \u0005מותר]?\u0006 \u0003אלא: \"דמו\"\u0004 כוונתו — \u0003חלבו,\u0004 לומר שאף שחלב צבי ואיל מותר — חלב פסולי המוקדשין אסור.","ושואלים: \u0003וליכתוב רחמנא\u0004 \u0005[\u0006ו\u0005שתכתוב התורה\u0006 במפורש\u0005]\u0006 \u0003\"חלבו\"!\u0004 ומשיבים: \u0003אי כתב רחמנא\u0004 \u0005[אם היתה כותבת התורה]\u0006 \u0003חלב\u0004 (\"רק את חלבו לא תאכל\"), \u0003הוה אמינא\u0004 \u0005[הייתי\u0006 \u0005אומר]:\u0006 \u0003אהני היקישא ואהני קרא\u0004 \u0005[הואיל ההיקש והועיל המקרא],\u0006","\u0003אהני היקישא\u0004 \u0005[הועיל ההיקש]\u0006 לצבי ואייל \u0003למעוטי\u0004 \u0005[למעט]\u0006 את האוכל חלב פסולי המוקדשים \u0003מ\u0004חיוב \u0003כרת, דכי כתב\u0004 \u0005[ש\u0006הרי \u0005כאשר נאמר]\u0006 חיוב \u0003כרת\u0004 — על \u0003אוכל חלב בהמה הוא דכתיב\u0004 \u0005[שנאמר],\u0006 \u0003שנאמר: \"כי כל אוכל חלב מן הבהמה\u0004 וכו', ונכרתה הנפש ההיא מעמיה\" (ויקרא ז, כה), ופסולי המוקדשים הרי הוקשו בכתוב זה לחיה.","\u0003ואהני קרא\u0004 \u0005[הועיל המקרא]\u0006 \"רק את חלבו לא תאכל\" — \u0003למיקם עליה\u0004 \u0005[לעמוד עליו]\u0006 מכל מקום \u0003ב\u0004איסור \u0003לאו\u0004 (לא תעשה) \u0003בעלמא\u0004 \u0005[בלבד].\u0006 \u0003להכי\u0004 \u0005[ל\u0006שם \u0005כך]\u0006 \u0003אפקיה רחמנא\u0004 \u0005[הוציאה אותו התורה]\u0006 \u0003בלשון \"דמו\",\u0004 כדי \u0003לומר לך: מה דמו\u0004 של בכור בעל מום (ושאר פסולי המוקדשין) \u0003ב\u0004חיוב \u0003כרת,\u0004 כדין כל דם בהמה וחיה (ראה ויקרא פרק יז) — \u0003אף חלבו בכרת.\u0004 ומקשים על דברי רבא: וכיצד יכול אתה לפרש שלדעת ברייתא זו \"אך\" נאמר לענין אותו ואת בנו?","\u0003והא\u0004 \u0005[והרי]\u0006 ה\u0003תנא\u0004 שבברייתא \u0003\"אך\" ולא חלבו קאמר\u0004 \u0005[אומר]!\u0006","ומשיבים, \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003אילו לא נאמר\u0004 \"רק את \u0003דמו\u0004 לא תאכל\", \u0003הייתי אומר: \"אך\"\u0004 בא למעט — \u0003ולא חלבו,\u0004 לומר שהוא אסור באכילה. ואולם \u0003עכשיו שנאמר \"דמו\"\u0004 ומשם למדתי לאיסור חלבו, אם כן \"אך\" — \u0003ל\"אותו ואת בנו\" הוא דאתא\u0004 \u0005[שבא].\u0006","שנינו במשנה לגבי פסולי המוקדשים (קדשים שנפל בהם מום) שנפדו: \u0003ואינן יוצאין לחולין להיגזז ולהיעבד.\u0004 ומבררים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]\u0006 בברייתא, על הפסוק האמור בענין פסולי המוקדשים: \"רק בכל אות נפשך תזבח ואכלת בשר\" (דברים יב, טו): \u0003\"תזבח\"\u0004 — \u0003ולא גיזה,\u0004 שלא הותר אלא לשחוט אותם, אבל לא לגוזזם, \u0003\"בשר\"\u0004 — \u0003ולא חלב, \"ואכלת\"\u0004 — אתה \u0003ולא לכלביך, מכאן שאין פודין את הקדשים\u0004 שאינם ראויים לאכילה, כדי \u0003להאכילן לכלבים,\u0004 אלא כשמתו — ייקברו."],["\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 שלמדים איסור גיזה וחלב מכתוב זה באופן אחר: \u0003\"תזבח ואכלת\"\u0004 (דברים יב, טו) — \u0003אין לך בהן היתר אכילה אלא משעת זביחה\u0004 (שחיטה) \u0003ואילך,\u0004 ואילו גיזה וחלב, שהם הנאות שמחיים — אסורות. ומעירים: ולדרך זו, \u0003אבל פודין את הקדשים\u0004 שנפסלו על מנת \u0003להאכילן לכלבים\u0004 — \u0003הכי נמי דאמר\u0004 \u0005[כך גם כן אומר]\u0006 תנא זה, כלומר, מותר הדבר לשיטתו.","שנינו במשנה: \u0003וולדן וחלבן\u0004 של פסולי המוקדשים \u0003אסור\u0004 בהנאה \u0003לאחר פדיונן.\u0004 ומבררים: היכי דמי \u0005[כיצד בדיוק מדובר]\u0006 שולדם אסור? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 במקרה \u0003דאיעבר ואיתיליד\u0004 \u0005[ש\u0006גם התעבר, וגם \u0005נולד]\u0006 \u0003לאחר פדיונן\u0004 — \u0003אמאי\u0004 \u0005[מדוע]\u0006 הולדות אסורים? והרי כמו \u0003ולד\u0004 של צבי ואיל נינהו \u0005[הם],\u0006 כלומר, חולין גמורים! \u0003אלא\u0004 צריך לומר \u0003דאיעבר\u0004 \u0005[שהתעבר]\u0006 \u0003לפני פדיונן ואיתיליד\u0004 \u0005[ונולד]\u0006 \u0003לאחר פדיונן.\u0004 ויש לדייק מכאן: אלה אסורים, \u0003הא\u0004 \u0005[אבל]\u0006 אם גם נולדו \u0003לפני פדיונן\u0004 — \u0003מיקדש נמי קדשי\u0004 \u0005[הריהם קדושים גם כן].\u0006","ומבררים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שולדות בעלי מומים גם הם קדושים? \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 נאמר ביחס לקרבן שלמים: \"אם מן הבקר הוא מקריב אם זכר אם נקבה תמים יקריבנו\" (ויקרא ג, א), ומדוע נתפרשו זכר ונקבה? והלא בכלל \"בקר\" זכר ונקבה! אלא \u0003\"זכר\"\u0004 — \u0003לרבות את הולד, ו\"נקבה\"\u0004 — \u0003לרבות את התמורה,\u0004 שאם המיר (החליף) בהמת שלמים בבהמת חולין — אף היא נעשית בהמת שלמים.","\u0003ואין לי אלא ולד\u0004 קדשים \u0003תמימין ותמורת תמימים,\u0004 ואולם \u0003ולדי בעלי מומין ותמורת בעלי מומין, מנין\u0004 שחלה אף עליהם קדושה, למרות שבעלי המומים עצמם פסולים להקרבה? \u0003כשהוא אומר \"אם זכר\", הרי \"אם\" לשון ריבוי היא\u0004 — \u0003לרבות ולד בעלי מומין,\u0004 וכן \"אם נקבה\" —","\u0003לרבות תמורת בעלי מומין.\u0004 ושואלים: אותן ולדות שנולדו לאחר פדיונן של פסולי המוקדשים, ששנינו במשנה שהם אסורים בהנאה, מה תהא עליהן, מה יעשו בהם? ומסבירים: אם נולדו לפני פדיונן — מיפלג פליגי בהו \u0005[חלוקים בהם]\u0006 חכמים מה דינם, \u0003איכא למאן דאמר\u0004 \u0005[יש מי שאומר]:\u0006 \u0003קדשי\u0004 \u0005[קדושים הם]\u0006 אפילו ליקרב על גבי המזבח, שהרי הם עצמם תמימים. \u0003ואיכא למאן דאמר\u0004 \u0005[ויש מי שאומר]:\u0006 לא יהא הנולד קדוש יותר מאמו, ולפיכך אינם קדושים להקרבה, אלא \u0003קדשי\u0004 \u0005[\u0006\u0005קדושים\u0006 הם] \u0003לרעייה,\u0004 שירעו עד שייפול בהם מום, ויפדו אותם.","אבל אם נולדו \u0003לאחר פדיונן\u0004 של אמותיהם \u0003מה תהא עליהן? אמר רב הונא: כונסן לכיפה\u0004 (מכניסם לחדר סגור) והן מתין שם ברעב. וטעם הדבר, דהיכי ליעביד \u0005[ש\u0006הרי \u0005איך נעשה]?\u0006 \u0003ליקרבינהו\u0004 \u0005[נקריב אותם]\u0006 — אי אפשר, שהרי \u0003מכח קדושה דחויה קאתו\u0004 \u0005[הם באים],\u0006 שנולדו לבהמה שכבר נפדתה ויצאה לחולין. \u0003ליפרקינהו\u0004 \u0005[שנפדה אותם] —\u0006 \u0003לא אלימי למיתפס\u0004 \u0005[אין הם חזקים,\u0006 אין קדושתם חזקה דיה, כדי \u0005לתפוס\u0006\u0005] את\u0006 \u0003פדיונן\u0004 בקדושה תחתם, ולכן הם עצמם אינם יוצאים לחולין.","ומעירים: \u0003אמרי במערבא משמיה\u0004 \u0005[אמרו בארץ ישראל משמו]\u0006 של \u0003רבי חנינא:\u0004 ולדות אלו, \u0003סמוך לפדיונן מתפיסן\u0004 (מקדישם) לשם אותו מין זבח של אמם. ותמהים: \u0003סמוך לפדיונן? למימרא\u0004 \u0005[\u0006האם לומר] ש\u0003בני פדייה נינהו\u0004 \u0005[הם]?\u0006 והרי אמרנו שלא ניתן לפדותם! \u0003אלא אימא\u0004 \u0005[אמור]: סמוך לפדיון אמן,\u0006 כשהם במעי אמם, \u0003מתפיסן\u0004 (מקדישם) \u0003לשם אותו זבח\u0004 של אמם, שאם היתה אם הולד בהמת שלמים — יתפיסו לשלמים. וכשאמו נפדית — הולד אינו נפדה ונדחה עמה, שהרי הוא קדוש בפני עצמו. ושואלים: \u0003טעמא מאי\u0004 \u0005[טעם\u0006 הדבר \u0005מהו]?\u0006 מדוע לא להשאיר את ולדות הקדשים כפי שהם? \u0003אמר ר' לוי: גזירה שמא יגדל מהן עדרים עדרים,\u0004 ויבוא לידי תקלה של הנאה מקדשים.","בעקבות דברי ר' חנינא, \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבינא מרב ששת: מהו שמתפיסן\u0004 את ולדות בעלי המומים כשהם במעי אמם \u0003לכל זבח שירצה,\u0004 ולאו דווקא למין זבח של אמם? אמר ליה \u0005[לו]:\u0006 \u0003אין מתפיסן.\u0004 שאל אותו: מאי טעמא \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003גמר\u0004 \u0005[\u0006הריהו למד] גזירה שווה \u0003\"בשעריך\" \"בשעריך\" מבכור,\u0004 שבבכור נאמר: \"בשעריך תאכלנו\" (דברים טו, כב), ובפסולי המוקדשים נאמר: \"בכל שעריך\" (דברים יב, טו), ללמדנו: \u0003מה בכור\u0004 — \u0003אין מתפיסן לכל זבח שירצה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אך בכור אשר יבכר לה' בבהמה (וגו') לא יקדיש איש אתו\"\u0004 (ויקרא כז, כו), אלא הריהו נשאר בקדושת בכור, \u0003אף הני\u0004 \u0005[אלה],\u0006 ולדי פסולי המוקדשים — \u0003אין מתפיסן לכל זבח שירצה,\u0004 אלא למין זבח של אמם, שהרי קדושה שיש בהם — קדושת אמם היא.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב ששת: קדשים שקדם מום קבוע להקדישן\u0004 — מתחילתם אין גופם קדוש להקרבה, ולכן, לאחר ש\u0003נפדו\u0004 \u0003חייבין בבכורה ובמתנות.\u0004 והואיל ואין להם דין קרבן, על כן \u0003בין לפני פדיונן בין לאחר פדיונן\u0004 — \u0003הגוזז והעובד בהן אינו סופג את הארבעים.\u0004 וכן \u0003בין לפני פדיונן בין לאחר פדיונן\u0004 — \u0003אין עושין תמורה,\u0004 שאם אמר על בהמת חולין שתהא תחתיה — אין היא קדושה.","\u0003ולפני פדיונן\u0004 — \u0003מועלין בהן,\u0004 יש בהם דין מעילה כשאר נכסי הקדש, \u0003ולאחר פדיונן\u0004— \u0003אין מועלין בהן. וולדותיהן\u0004 שנולדו לאחר פדיונם — הריהם \u0003חול, ו\u0004אם נולדו קודם הפדיון — \u0003נפדין\u0004 הולדות למרות שהם \u0003תמימים, ו\u0004אם רוצה להקדיש את הולדות — \u0003מתפיסן לכל זבח שירצה. כללו של דבר: הרי הן כחולין לכל דבריהם,\u0004 לכל דיניהם, ו\u0003אין לך בהם\u0004 שינוי מכל בהמת חולין, \u0003אלא מצות עלוי\u0004 (הערכה) ופדייה \u0003בלבד\u0004.","\u0003 אבל\u0004 קדשים בעלי מום ש\u0003קדם הקדישן את מומן, או\u0004 שקדם \u0003מום עובר להקדישן ו\u0004רק \u0003לאחר מכאן נולד מום קבוע\u0004 — כבר נתקדש גופם למזבח, \u0003ו\u0004לכן כש\u0003נפדו\u0004 הרי הם \u0003פטורין מן הבכורה ומן המתנות. בין לפני פדיונן בין לאחר פדיונן\u0004 — \u0003הגוזז והעובד בהן סופג את הארבעים. ובין לפני פדיונן בין לאחר פדיונן\u0004 — \u0003עושין תמורה.\u0004","\u0003לפני פדיונן\u0004 — \u0003מועלין בהן,\u0004 יש בהם דין מעילה, \u0003ולאחר פדיונן\u0004 — \u0003אין מועלין בהן,\u0004 שכבר אינם רכוש ההקדש או המזבח. \u0003וולדותיהן\u0004 שנתעברו בהם קודם פדיונן, גם אם נולדו לאחר פדיונם — \u0003קודש,\u0004 שכבר נתקדשו בקדושת אמם למזבח, \u0003ואין\u0004 ולדות אלה \u0003ניפדין\u0004 כל עוד הם \u0003תמימין. ו\u0004אם ברצונו להקדישם \u0003אין מתפיסן\u0004 את הולדות \u0003לכל זבח שירצה,\u0004 אלא למין זבח של אמם (וכדברי רב ששת). \u0003כללו של דבר:\u0004 קדשים שנפל בהם מום ונפדו \u0003הרי הן כהקדש לכל דבריהם, ואין לך בהן\u0004 \u0003אלא היתר אכילה בלבד.\u0004","ומבארים: \u0003\"כללו של דבר\" דרישא\u0004 \u0005[ש\u0006נאמר \u0005בהתחלה],\u0006 באלו שקדם מומם להקדשם — \u0003לאתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 דין \u0003שוחטן בחוץ\u0004 שהוא \u0003פטור, \"כללו של דבר\" דסיפא\u0004 \u0005[\u0006שנאמר בסוף], באלו שקדם הקדשם את מומם"],["\u0003לאתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 את \u0003חלבו,\u0004 שהחלב של פסולי המוקדשים אסור גם לאחר פדיון. ודנים בברייתא זו.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: קדשים שנפל בהם מום, ונפדו, ולאחר מכן ילדו — \u0003אין\u0004 הולדות \u0003נפדין תמימין, ואין מתפיסן\u0004 (מקדישם) \u0003לכל זבח שירצה.\u0004 ונדייק: כשהם \u0003תמימים הוא דלא מיפרקי\u0004 \u0005[שאינם נפדים],\u0006 \u0003הא\u0004 \u0005[אבל]\u0006 אם נעשו הולדות \u0003בעלי מומין — מיפרקי\u0004 \u0005[נפדים].\u0006 ועוד יש לדייק: \u0003לכל\u0004 זבח שירצה הוא ש\u0003אין מתפיסן, הא\u0004 \u0005[אבל]\u0006 \u0003לאותו\u0004 מין \u0003זבח\u0004 של אמם — \u0003מתפיסן.\u0004","\u0003היכי משכחת לה\u0004 \u0005[כיצד מוצא אתה]\u0006 מציאות כזו, שיחולו בה שני דינים אלה — במקרה ש\u0003מתפיסן\u0004 במעי אמם \u0003ל\u0004שם \u0003אותו זבח\u0004 של אמם, \u0003ו\u0004מתוך שיש בהם קדושה גמורה לעצמם, לכשייולדו ויפול בהם מום — הריהם \u0003נפדין במומן,\u0004 וכפי שאמר ר' חנינא בעמוד הקודם. ושואלים: \u0003נימא תיהוי תיובתא\u0004 \u0005[\u0006האם \u0005לומר שתהיה\u0006 זו \u0005קושיה]\u0006 על דברי \u0003רב הונא,\u0004 שאמר שלא ניתן לפדות ולדות אלה, אלא ימותו?","ומשיבים, \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך רב הונא:\u0004 כשם שאינם נפדים כשהם תמימים — \u0003הוא הדין\u0004 ש\u0003אפילו בעלי מומין אין נפדין, ואיידי דתנא רישא\u0004 \u0005[ומתוך ששנה בתחילה],\u0006 לגבי ולדות קדשים שקדם מומם להקדשם, שהם \u0003נפדין תמימים — תנא נמי סיפא\u0004 \u0005[שנה גם כן בסוף],\u0006 לגבי קדשים שקדם הקדשם למומם באותה לשון: \u0003אין נפדין תמימים. ו\u0004כן \u0003איידי דתנא רישא\u0004 \u0005[מתוך ששנה בתחילה]\u0006 שמקדיש ולדותיהם \u0003לכל זבח שירצה\u0004 — \u0003תנא נמי סיפא\u0004 \u0005[שנה גם כן בסוף]\u0006 שאין מקדישם \u0003לכל זבח שירצה,\u0004 ואין לדייק מן הלשון שיכול להקדישם לשם אותו זבח.","ועוד שנינו בענין בעלי מום שקדם הקדשם למומם: \u0003והשוחטן בחוץ פטור,\u0004 לפי שאין חייבים משום שחיטת חוץ אלא על קדשים הראויים להקרבה, ואלו פסולים להקרבה. ומעירים: \u0003רב הונא מתני\u0004 \u0005[היה שונה]:\u0006 \u0003חייב, ומוקים לה\u0004 \u0005[מעמיד אותה\u0006\u0005]\u0006 במומים שאינם ניכרים, כגון \u0003בדוקין\u0004 (קרומים, כתמים) \u0003שבעין, ואליבא\u0004 \u0005[ועל פי שיטתו]\u0006 של \u0003ר' עקיבא\u0004 ש\u0003אמר:\u0004 בעלי מומים קלים אלה, אף שהם פסולים לכתחילה להקרבה, \u0003אם עלו\u0004 על המזבח — \u0003לא ירדו\u0004 ממנו, ולפיכך חייבים גם על שחיטתם בחוץ.","עוד שנינו בברייתא: קדשים שנפל בהם מום לאחר שהוקדשו, \u0003בין לפני פדיונו בין לאחר פדיונו עושה תמורה,\u0004 שאם אמר על בהמת חולין שתהא תחתיו — אף היא קדושה. \u0003אמר רב נחמן אמר רבה בר אבוה: ותמורתו\u0004 שנעשתה \u0003לאחר פדיונו\u0004 — \u0003מתה,\u0004 שמכניסים אותה לחדר, והיא מתה מאליה מרעב, \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 שכן \u0003היכי ליעביד\u0004 \u0005[כיצד יעשה]?\u0006 \u0003ליקרביה\u0004 \u0005[יקריב אותה]\u0006 — הרי \u0003מכח קדושה דחויה קאתיא\u0004 \u0005[היא באה],\u0006 שבעל מום זה כבר נפדה, ואינו קדוש בקדושת המזבח, ומכוחו היא קדושה. \u0003ליפרקה\u0004 \u0005[שיפדה אותה]\u0006 לאחר שיפול בה מום — \u0003לא אלימא\u0004 \u0005[אין\u0006 קדושתה \u0005חזקה דיה]\u0006 כדי \u0003למיתפס\u0004 \u0005[לתפוס]\u0006 את דמי \u0003פדיונה\u0004 בקדושתה. \u0003הלכך מתה,\u0004 כדי שלא ייכשלו בה אנשים בהנאה מן הקדשים.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב עמרם:\u0004 וימתין עד שיפול בתמורה זו מום, \u0003ותיתכיל\u0004 \u0005[ותיאכל]\u0006 \u0003במומה לבעלים,\u0004 בלא שיפדו אותה! \u0003וכי מה בין זו,\u0004 תמורת קדשים בעלי מום, \u0003לתמורת בכור ומעשר,\u0004 שלא ניתן להקריבה, והיא נאכלת במומה? \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה] במסכת תמורה: \u0003תמורת בכור ומעשר, הן וולדן וולד ולדן עד סוף כל העולם\u0004 — \u0003הרי הן\u0004 קדושים \u0003כבכור ומעשר, ו\u0004כשיפול בהם מום — אין פודים אותם, אלא יאכלו במומן לבעלים! אמר ליה \u0005[לו]\u0006 \u0003אביי: זה\u0004","\u0003שם אמו עליו וזה שם אמו עליו,\u0004 כלומר, בכל תמורה נוהגים כדין הקרבן שמכוחו היא באה; \u0003זה כולו תמורת בכור ומעשר מיקריא\u0004 \u0005[נקרא],\u0006 ולפיכך, \u0003מה בכור ומעשר\u0004 עצמם \u0003במומן מיתאכלן\u0004 \u0005[נאכלים]\u0006 \u0003לבעלים\u0004 — אף תמורתן מיתאכלא \u0005[נאכלת]\u0006 במומה לבעלים.","\u0003וזה\u0004 תמורת קדשים בעלי מום, \u0003שם אמו עליו, תמורת קדשים מיקריא\u0004 \u0005[נקראת],\u0006 ולפיכך, \u0003מה קדשים\u0004 שנפל בהם מום \u0003לא מיתכלי\u0004 \u0005[אינם נאכלים]\u0006 \u0003אלא בפדיון\u0004 — \u0003אף תמורתן\u0004 \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 \u0003מיתכלי\u0004 \u0005[אינה נאכלת]\u0006 \u0003אלא בפדיון, והא לא אלימא למיתפס\u0004 \u0005[וזו\u0006 התמורה שנעשתה לאחר פדיון \u0005לא חזקה\u0006 קדושתה כדי \u0005לתפוס]\u0006 את \u0003פדיונה\u0004 בקדושה, ומשום כך אינה יכולה להיפדות, ולכן תמות.","ומעירים, \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב נחמן: מנין לתמורת פסולי המוקדשין\u0004 (שנפדו) שמתה, ולא ניתן לפדותה ולאוכלה? \u0003תלמוד לומר: \"ממעלי הגרה... טמא\u0004 הוא לכם\" (ויקרא יא, ד). וכך דורשים את הפסוק: גם מבעלי החיים הטהורים מעלי הגרה, יש כאלה הטמאים לכם ואסורים באכילה. והם תמורות פסולי המוקדשים שנפדו, שלא ניתן לפדותן ולאוכלן, אלא הן מתות. ושואלים: והרי \u0003האי מיבעי ליה\u0004 \u0005[\u0006פסוק \u0005זה נצרך]\u0006 לענין \u0003חמש חטאות\u0004 (ולד חטאת, ותמורת חטאת, וחטאת שמתו בעליה, ושנתכפרו בעליה, ושעברה שנתה הראשונה), ללמדנו שהן אסורות בהקרבה, ולכן \u0003מתות!\u0004 ומשיבים: \u0003ההוא,\u0004 אותו דין, ממה שנאמר שם \u0003\"ממפריסי הפרסה... טמא\" נפקא\u0004 \u0005[יוצא,\u0006 נלמד].","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא גם כן כך]: \u0003מנין לחמש חטאות\u0004 שהן \u0003מתות? תלמוד לומר: \"ממפריסי הפרסה... טמא\".\u0004 ותוהים: \u0003חמש חטאות\u0004 שהן \u0003מתות,\u0004 הלוא \u0003הילכתא גמירי לה\u0004 \u0005[\u0006מ\u0005הלכה\u0006 למשה מסיני, למדו אותה], במסורת שבעל פה, ולא מן הכתוב! \u0003אלא, כי אתא קרא\u0004 \u0005[כאשר בא המקרא]\u0006 \"ממפריסי הפרסה... טמא\" הרי זה \u0003לתמורת אשם,\u0004 ללמדנו שהיא אסורה בהקרבה, ותרעה עד שיפול בה מום ותיפדה.","ומקשים: \u0003תמורת אשם נמי\u0004 \u0005[גם כן]\u0006 \u0003הילכתא\u0004 \u0005[הלכה\u0006 למשה מסיני] \u0003היא,\u0004 ששנינו: \u0003כל שבחטאת מתה\u0004 (ובכלל זה תמורת חטאת) — \u0003באשם רועה\u0004 עד שיפול בו מום!","\u0003אלא, לעולם\u0004 הלימוד מ\"מפריסי הפרסה\" הוא ל\u0003חמש חטאות מתות. ו\u0004למרות שהלכה למשה מסיני היא, \u0003אצטריך קרא ואצטריך הילכתא\u0004 \u0005[הוצרך המקרא והוצרכה ההלכה],\u0006 \u0003דאי מקרא הוה אמינא\u0004 \u0005[שאם מן המקרא\u0006 לבד, \u0005הייתי אומר]\u0006 שאסורות בהקרבה, אבל יצאו \u0003לרעייה\u0004 עד שיפול בהם מום וייפדו, על כן \u0003קא משמע לן הילכתא\u0004 \u0005[משמיע לנו הלכה]\u0006 שדינן \u0003למיתה. ואי מהילכתא הוה אמינא\u0004 \u0005[ואם מן ההלכה\u0006 לבד, \u0005הייתי אומר]:\u0006 \u0003היכא דעבד איקרי\u0004 \u0005[היכן שעשה\u0006 כן \u0005במקרה]\u0006 \u0003ואכל מהני\u0004 \u0005[מאותן]\u0006 \u0003חמש חטאות\u0004 — \u0003איסורא איכא\u0004 \u0005[איסור יש בזה],\u0006 אבל איסור \u0003לאו\u0004 (לא תעשה) המפורש בתורה, שעונשו מלקות, \u0003ליכא\u0004 \u0005[אין בזה],\u0006 על כן \u0003קמשמע לן\u0004 \u0005[משמיע לנו הכתוב\u0006\u0005]\u0006 \u0003דאיכא\u0004 \u0005[שיש בזה]\u0006 \u0003לאו.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 לא בא הכתוב \"ממפריסי הפרסה\" ללמד את דין חטאות המתות עצמו, שהוא הלכה למשה מסיני, אלא הוזכר בפסוק זה כדי \u0003לאקושי\u0004 \u0005[להקיש,\u0006 להשוות\u0005]\u0006 \u0003דבר הבא\u0004 (הנלמד) \u0003ממעלי גרה,\u0004 כלומר, תמורת פסולי המוקדשים, \u0003לדבר הבא\u0004 (הנלמד) \u0003ממפריסי הפרסה,\u0004 כלומר, חטאות המתות, \u0003מה להלן\u0004 חטאות המתות — דינן \u0003במיתה, אף כאן\u0004 דינה \u0003במיתה.\u0004","\u0003המקבל צאן ברזל מן הגוי,\u0004 שהגוי נותן לישראל בהמות לגדלן והישראל מתחייב לשלם לו תמורתן בסכום קצוב לאחר זמן, גם אם ימותו או יוזלו דמיהן, והולדות שייוולדו להן עד זמן התשלום יחולקו ביניהם —"],["\u0003ולדותיהן פטורין\u0004 מן הבכורה, שאם ולדות אלו ילדו זכר — אינו קדוש בבכורה, משום שיש לגוי חלק בהם. אבל \u0003ולדי ולדותיהן\u0004 כשילדו זכר — \u0003חייבין.\u0004 ואם \u0003העמיד\u0004 ישראל ולדותיהן של צאן ברזל \u0003תחת אמותיהן\u0004 לשם גביה, אם ימותו האמהות — גם \u0003ולדי ולדות פטורין\u0004 מן הבכורה, \u0003וולדי וולדי וולדות\u0004 — \u0003חייבים. רבן שמעון בן גמליאל אומר: אפילו עד עשרה\u0004 דורות \u0003פטורים,\u0004 מפני \u0003שאחריותן לגוי,\u0004 שאם לא יקבל את הדמים שנקצבו מתחילה עבור הצאן שנתן — הריהו גובה מכל מה שנולד מהן.","\u0003רחל שילדה\u0004 זכר הנראה כ\u0003מין עז, ועז שילדה מין רחל\u0004 — \u0003פטורה מן הבכורה, ו\u0004מכל מקום, \u0003אם יש בו מקצת סימנין\u0004 של אמו, שדומה לה במקצת — \u0003חייב.\u0004","שנינו במשנה שהמקבל צאן ברזל מן הגוי, ולדותיהם פטורים מן הבכורה. ומעירים: מכאן \u0003למימרא\u0004 \u0005[\u0006יש לומר, להסיק\u0005]\u0006 ש\u0003כיון\u0004 שעדיין \u0003לא נקט מרא זוזי\u0004 \u0005[מחזיק הבעלים\u0006 הגוי \u0005מעות]\u0006 מישראל תמורת הבהמה שנתן — \u0003ברשותא דמרא קיימא\u0004 \u0005[ברשות הבעלים,\u0006 הגוי, הבהמה \u0005עומדת],\u0006 ומשום כך ולדותיה פטורים מן הבכורה.","\u0003ורמינהו\u0004 \u0005[ומטילים,\u0006 מראים סתירה\u0005]\u0006 ממשנה אחרת, ששנינו בה: \u0003אין מקבלין צאן ברזל מישראל, מפני שהוא רבית,\u0004 שתמורת המתנת התשלום עבור הבהמה — נוטל הנותן מחצית מן הולדות שנולדו למקבל. \u0003אלמא ברשותא דמקבל קיימא\u0004 \u0005[מכאן שברשות המקבל עומדת]\u0006 הבהמה. שהרי אם ברשות הנותן היא — אין זו ריבית, שהרי הולדות שלו הם!","\u0003אמר אביי: לא קשיא\u0004 \u0005[אין זה קשה],\u0006 \u0003הא\u0004 \u0005[זה],\u0006 במשנתינו, מדובר במקרה \u0003דקביל עליה אונסא וזולא\u0004 \u0005[שקיבל עליו\u0006 הגוי \u0005אונס וזול],\u0006 שאם יארע אונס, כגון שוד, או שירד מחיר הבהמות — לא יצטרך הישראל לשלם את המחיר הקצוב. ולכן נחשבת הבהמה של הגוי, ומשום כך ולדותיה פטורים מן הבכורה. \u0003והא\u0004 \u0005[וזה],\u0006 בענין ריבית, מדובר במקרה \u0003דלא קביל עליה אונסא וזולא\u0004 \u0005[שלא קיבל עליו\u0006 הנותן \u0005אונס וזול],\u0006 והואיל וכל האחריות על המקבל — הריהי נחשבת כשלו, ולכן הולדות שהוא נותן הריהם ריבית.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא\u0004 בתמיהה: \u0003דקביל עליה אונסא וזולא\u0004 \u0005[\u0006במקרה \u0005שקיבל עליו\u0006 הנותן \u0005אונס וזול],\u0006 \u0003\"צאן ברזל\" קרית ליה\u0004 \u0005[אתה קורא לו]?\u0006 והרי אין הם קרויים כך אלא משום שכל אחריותם על המקבל, כאילו היו ברזל, שאינו יכול למות או להיחסר! \u0003ועוד, מאי פסקא\u0004 \u0005[מהו חיתוך\u0006 זה\u0005],\u0006 שאתה מחלק בין שתי משניות שלשונן אחת?","\u0003ועוד, אדתני סיפא\u0004 \u0005[עד ש\u0006הוא שונה בסופה] של המשנה בענין ריבית: \u0003אבל מקבלין צאן ברזל מן הגוי\u0004 (מפני שאין איסור ריבית בהלוואה מן הגוי) — \u0003ליפלוג וליתני בדידה\u0004 \u0005[שיחלק וישנה ב\u0006הלכה זו \u0005עצמה]\u0006 של המקבל צאן ברזל מישראל, חלוקה זו שאביי מחלק בה, וכך יאמר: \u0003במה דברים אמורים\u0004 שאין מקבלים צאן ברזל — במקרה \u0003דלא קביל עליה אונסא וזולא\u0004 \u0005[שלא קיבל עליו\u0006 הנותן אונס וזול], \u0003אבל\u0004 אם \u0003קביל עליה אונסא וזולא\u0004 \u0005[קיבל עליו\u0006 הנותן \u0005אונס וזול]\u0006 והבהמה נחשבת כשלו — \u0003שפיר דמי\u0004 \u0005[ראוי,\u0006 מותר, הדבר], שאין זו ריבית!","\u0003אלא אמר רבא: אידי ואידי\u0004 \u0005[זה וזה],\u0006 בין לענין ריבית ובין במשנתנו, מדובר במקרה \u0003דלא קביל עליה אונסא וזולא\u0004 \u0005[שלא קיבל עליו\u0006 הנותן \u0005אונס וזול],\u0006 והבהמה נחשבת איפוא של המקבל. \u0003והכא גבי\u0004 \u0005[וכאן אצל]\u0006 \u0003בכורה היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 שהולדות פטורים מן הבכורה, משום ש\u0003אילו אתי\u0004 \u0005[בא]\u0006 ה\u0003גוי בעי זוזי\u0004 \u0005[\u0006ו\u0005רוצה את המעות]\u0006 בסוף הזמן הקצוב, \u0003ולא יהיב ליה\u0004 \u0005[ואין\u0006 הישראל \u0005נותן לו],\u0006 הריהו \u0003תפיס לה\u0004 \u0005[תופס אותה]\u0006 את ה\u0003בהמה\u0004 תמורתם, \u0003ואי לא משכח לה\u0004 \u0005[ואם איננו מוצא אותה]\u0006 את הבהמה עצמה, כגון שמתה, הריהו \u0003תפיס\u0004 \u0005[תופס]\u0006 את ה\u0003ולדות דידה\u0004 \u0005[שלה],\u0006 \u0003ו\u0004אם כן \u0003הרי יד גוי באמצע,\u0004 כלומר, יש לו שייכות בולדות, \u0003וכל\u0004 אופן ש\u0003יד גוי באמצע\u0004 — \u0003פטורה מן הבכורה.\u0004","שנינו במשנה: המקבל צאן ברזל מן הגוי — ולדות פטורים מן הבכורה, ולדי ולדות חייבים. ואם \u0003העמיד ולדותיהן תחת אמותיהן\u0004 — גם \u0003ולדי ולדות פטורים. אמר רב הונא:\u0004 מה ששנינו בתחילת המשנה, שולדות פטורים — הרי זה כפשוטו, \u0003ולדות\u0004 של צאן ברזל \u0003פטורין\u0004 לכשיבכירו, \u0003ו\u0004רק \u0003ולדי ולדותיהן\u0004 — \u0003חייבין\u0004 לכשיבכירו הם, ונמצא דור רביעי לצאן ברזל קדוש בבכורה. \u0003ורב יהודה אמר: ולדי ולדות\u0004 של צאן ברזל \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003פטורין, ו\u0004רק \u0003ולדי ולדי ולדות — חייבין\u0004 לכשיבכירו, ונמצא דור חמישי לצאן ברזל קדוש בבכורה.","ומציעים ראיה לענין זה, \u0003תנן\u0004 [שנינו במשנה\u0005]:\u0006 \u0003העמיד ולדות תחת אמותיהן\u0004 — \u0003ולדי ולדות פטורין.\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דוקא\u0005]\u0006 משום ש\u0003העמיד\u0004 ולדות תחת אמותיהם, פטורים ולדי ולדות לכשיבכירו, \u0003הא\u0004 \u0005[אבל]\u0006 אם \u0003לא העמיד\u0004 — \u0003לא,\u0004 אלא רק ולדות פטורים, והרי זו \u0003תיובתא\u0004 \u0005[\u0006\u0005קושיה\u0006 חמורה\u0005]\u0006 על דברי \u0003רב יהודה!\u0004","ומשיבים, \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך רב יהודה: הוא הדין\u0004 שולדי ולדות גם כן פטורים, \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא העמיד. ו\u0004אם תאמר: אם כן, מה נתחדש במקרה שהעמיד? \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר זה משמיע לנו]: \u0003אפילו העמיד נמי\u0004 \u0005[גם כן],\u0006 רק ולדי ולדות פטורים, ולא מעבר לכך.","והוצרך לכך משום \u0003דאורחיה\u0004 \u0005[שדרכו]\u0006 של ה\u0003גוי למיתפס\u0004 \u0005[לתפוס]\u0006 במקרה זה לא רק את הולד שהעמיד תחת האם, אלא גם את \u0003בנה\u0004 (ולדי ולדות), ואם כן יש לומר שגם ולדי ולדי הולדות יהיו פטורים. לכן משמיע לנו שאין זה כך, \u0003ו\u0004דינו \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003כמי\u0004 ש\u0003לא העמיד,\u0004 ולפיכך דוקא \u0003ולדי ולדות פטורין, ו\u0004אולם \u0003ולדי ולדי ולדות חייבין.\u0004","ועוד מציעים ראיה: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה], \u0003רבן שמעון בן גמליאל אומר: אפילו עד עשרה דורות פטורין, שאחריותן לנכרי. בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003רב יהודה\u0004 ש\u0003אמר: נחית תנא קמא לדרי\u0004 \u0005[ירד התנא הראשון לדורות],\u0006 שדייק בפרטי דבריו לפטור מהבכורה דור של ולדות, ועוד דור נוסף (ולדי ולדות), ולאחר מכן חייב —"],["\u0003היינו דאמר ליה\u0004 \u0005[זהו שאומר לו]\u0006 \u0003רבן שמעון בן גמליאל:\u0004 לא רק שני דורות פטורים, אלא \u0003אפילו עד עשרה דורות פטורין. אלא ל\u0004שיטת \u0003רב הונא, דאמר\u0004 \u0005[שאומר]: לא נחית תנא קמא לדרי\u0006 \u0005[יורד התנא הראשון ל\u0006מספר דורות] שפטורים, אלא מבחין הבחנה עקרונית בין ולדות צאן ברזל עצמם, שפטורים, לבין כל הנולדים מהם, שהם חייבים בבכורה, \u0003מאי\u0004 \u0005[מה,\u0006 מדוע השתמש בלשון\u0005]\u0006 \u0003\"אפילו עד עשרה דורות\"?\u0004 יאמר: ולדי ולדות פטורים, וממילא מובן כי הוא הדין לכל הדורות, שאינם ולדות צאן ברזל עצמם! ומשיבים: אמר \u0005[יכול לומר]\u0006 \u0003לך רב הונא: רבן שמעון בן גמליאל\u0004 על המקרה ש\u0003העמיד\u0004 ולדות תחת אמותיהם \u0003קאי\u0004 \u0005[\u0006הוא \u0005עומד,\u0006 מתייחס\u0005],\u0006 \u0003דנחית לדרי\u0004 \u0005[ש\u0006שם התנא הראשון \u0005יורד לדורות],\u0006 ואומר שולדות וגם ולדי ולדות פטורים, ולכך מוסיף רבן שמעון — לא רק אלו, אלא אפילו עד עשרה דורות.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו בתחילת המשנה: \u0003המקבל צאן ברזל מן הגוי\u0004 — \u0003ולדות פטורין, וולדי ולדות לא.\u0004 והרי זו \u0003תיובתא\u0004 \u0005[קושיה\u0006 חמורה] על \u0003רב יהודה,\u0004 שאמר שגם ולדי ולדות פטורים! ומשיבים: \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך רב יהודה: אימא\u0004 \u0005[אמור]\u0006 ותקן את הלשון: \u0003הן\u0004 (הוולדות) \u0003וולדותיהן\u0004 פטורים.","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 שהביאו ראיה ממה ששנינו: \u0003הן וולדותיהן פטורין,\u0004 והרי זו \u0003תיובתא\u0004 \u0005[קושיה]\u0006 על \u0003רב הונא,\u0004 שאמר כי רק הולדות פטורים! ודוחים, \u0003אמר\u0004 \u0005[יכול היה לומר]\u0006 \u0003לך רב הונא, אימא\u0004 \u0005[אמור]:\u0006 \u0003הן,\u0004 כלומר, ה\u0003וולדות\u0004 — \u0003פטור, וולדי ולדות\u0004 — \u0003חייב.\u0004","שנינו במשנה: \u0003רחל שילדה\u0004 בכור זכר כ\u0003מין עז,\u0004 ועז שילדה כמין רחל — אינו קדוש בבכורה. ובענין זה מסופר, \u0003אתא\u0004 \u0005[בא]\u0006 \u0003רב אושעיא מנהרדעא\u0004 לסורא \u0003ואייתי מתניתא בידיה\u0004 \u0005[והביא ברייתא בידו]:\u0006 \u0003רחל בת עז, ועז בת רחל\u0004 — \u0003ר' מאיר מחייב, וחכמים פוטרין.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הושעיא לרבה: כי עיילת לקמיה\u0004 \u0005[כאשר אתה נכנס לפני]\u0006 \u0003רב הונא\u0004 (שעמד בראשות הישיבה בסורא), \u0003בעי מיניה\u0004 \u0005[שאל אותו]:\u0006 מה שנאמר בברייתא שהבאתי, ש\u0003ר' מאיר מיחייב\u0004 ברחל בת עז, או בעז בת רחל, \u0003למאי\u0004 \u0005[למה,\u0006 לאיזה עניין\u0005]\u0006 נאמר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003ל\u0004ענין בכורה — \u0003ולית ליה\u0004 \u0005[ו\u0006כי \u0005אין לו]\u0006 \u0003לר' מאיר\u0004 מה שדרשו: \u0003\"אך בכור שור\"\u0004 (במדבר יח, יז) — שאין דין בכורה חל \u0003עד שיהא הוא שור ובכורו שור,\u0004 לומר, שיהא הבכור (ולאו דוקא שור) דומה למין אמו?","\u0003אלא\u0004 תאמר שהוא \u0003ל\u0004ענין ראשית הגז, שצריך לתת לכהן מצמר הכבשים, ולשיטת רבי מאיר, אף אם היתה זו עז בת רחל חייב. על כך יש לתמוה: וכי \u0003לית ליה\u0004 \u0005[אין לו,\u0006 אינו סבור] כמו \u0003הא דתנא דבי\u0004 \u0005[זו ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: כבשים שצמרן קשה\u0004 — \u0003פטורין מראשית הגז, שנאמר: \"ומגז כבשי יתחמם\"\u0004 (איוב לא, כ), ומכאן למדנו שרק צמר שעושים ממנו בגד להתחמם בו הריהו בכלל \"ראשית גז צאנך\" (דברים יח, ד)? והלוא שער עז בת רחל קשה ואינו ראוי לכך!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה לרב אושעיא, \u0003ניחזי אנן\u0004 \u0005[נראה אנחנו,\u0006 ונדון בעצמנו\u0005]\u0006 בפירוש דברי ר' מאיר: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים] —\u0006 \u0003ברחל שילדה מין עז, ואביו\u0004 שנתעברה ממנו רחל זו, הריהו \u0003תייש. ו\u0004ר' מאיר וחכמים, בשאלה האם \u0003חוששין לזרע האב לענין\u0004 איסור שחיטת \u0003אותו ואת בנו\u0004 ביום אחד קמיפלגי \u0005[חלוקים הם],\u0006 ש\u0003ר' מאיר סבר\u0004 \u0005[סבור]\u0006 \u0003חוששין לזרע האב,\u0004 כלומר, מייחסים את בעל החיים לאב (ולא רק לאם), ואסור לשחוט את התייש ובנו ביום אחד, ורבנן סברי \u0005[וחכמים סבורים]:\u0006 \u0003אין חוששין לזרע האב,\u0004 ואין איסור שחיטת אותו ואת בנו נוהג אלא באם ובולד. ומקשים: \u0003אי\u0004","\u0003הכי\u0004 \u0005[אם כך], ליפלגו\u0006 \u0005[שיחלקו]\u0006 \u0003ב\u0004שאלה של \u0003חוששין לזרע האב בעלמא\u0004 \u0005[בכלל],\u0006 \u0003בפלוגתא\u0004 \u0005[במחלוקת,\u0006 כמו שחלקו\u0005]\u0006 \u0003חנניה ורבנן\u0004 \u0005[וחכמים]\u0006 האם יש איסור שחיטה של אב ובנו ביום אחד, או רק של אם ובנה, ולאו דוקא במקרה זה של רחל שילדה מין עז ואביו תייש!","\u0003אלא, לעולם\u0004 צריך אתה לומר כי ר' מאיר וחכמים נחלקו ביחס \u0003ל\u0004דין \u0003בכורה.\u0004 ולדעת הכל אין דין בכורה עד שיהא \"הוא שור ובכורו שור\", \u0003והכא במאי עסקינן\u0004 \u0005[וכאן במה אנחנו עוסקים]\u0006 — \u0003ברחל\u0004 (בכבש) \u0003בת רחל בת עז. מר סבר\u0004 \u0005[חכם זה,\u0006 ר' מאיר, \u0005סבור]:\u0006 \u0003זיל בתר אימיה\u0004 \u0005[לך אחר אמו],\u0006 תבדוק רק את אמו, \u0003והאי לאו\u0004 \u0005[וזה לא]\u0006 \u0003נדמה\u0004 למין אחר \u0003הוא,\u0004 וחייב בבכורה.","\u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003זיל בתר אימיה דאימיה\u0004 \u0005[לך אחר אם אמו],\u0006 \u0003והאי\u0004 \u0005[וזה,\u0006 הולד\u0005]\u0006 \u0003נדמה הוא,\u0004 שהוא מזרע רחלים, ודומה לעז.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 נחלקו ר' מאיר וחכמים \u0003ברחל בת עז בת רחל, מר סבר\u0004 \u0005[חכם\u0006 זה, ר' מאיר, \u0005סבור]:\u0006 אין זה נדמה, שהרי בכור זה הוא שה מזרע רחלים, ו\u0003חזרה שייות למקומן,\u0004 \u0003ומר סבר\u0004 \u0005[וחכם זה\u0006 חכמים, \u0005סבור]:\u0006 \u0003לא\u0004 אומרים \u0003חזרה שייות למקומן,\u0004 אלא כל ולד שאינו כמין אמו פטור מן הבכורה.","\u0003רב אשי אמר:\u0004 מחלוקת ר' מאיר וחכמים היא כגון שיש בו בבכור מקצת סימנין של אמו, שהוא דומה לה במקצת, דעת ר' מאיר הריהי כדעת סתם משנתנו, שאם יש בו מקצת סימנים של אמו חייב בבכורה (שסתם משנה ר' מאיר היא). \u0003ומאן\u0004 \u0005[ומי\u0006 הם\u0005]\u0006 \u0003חכמים\u0004 החולקים עליו — \u0003ר' שמעון\u0004 הוא, \u0003דאמר\u0004 \u0005[שאומר]:\u0006 אינו בכור \u0003עד שיהא ראשו ורובו דומה לאמו.\u0004","\u0003אמר ר' יוחנן:\u0004 אף שלענין בכורה, סבור ר' מאיר כי רחל שילדה מין עז חייב בבכורה, מכל מקום \u0003מודה ר' מאיר בשעיר של\u0004 מוסף \u0003ראש חדש דבעינן\u0004 \u0005[שצריכים אנו]\u0006 שיהיה שעיר \u0003בן שעירה,\u0004 כדי להיות ראוי להקרבה. מאי טעמא \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \"ושעיר עזים \u0003אחד\u0004 לחטאת\" (במדבר כח, טו), ובאה המלה \"אחד\" להדגיש ולומר: שעיר \u0003המיוחד ובא מששת ימי בראשית,\u0004 שלא נשתנה.","ושואלים: \u0003והא מהכא נפקא\u0004 \u0005[ו\u0006דין \u0005זה מכאן\u0006 הוא \u0005יוצא,\u0006 נלמד]? והרי \u0003מהתם נפקא\u0004 \u0005[משם\u0006 הוא \u0005יוצא]\u0006 — שנאמר בענין קרבנות בכלל: \"שור או כשב או עז\" (ויקרא כב, כז), וניתן היה לכתוב רק שור וללמוד ממנו את השאר. אלא נאמר \u0003\"שור או כשב\"\u0004 — \u0003פרט לכלאים,\u0004 שהבא מהכלאה אינו כשר, \u0003\"או עז\"\u0004 — \u0003פרט לנדמה.\u0004 ואין צורך איפוא למיעוט מיוחד בשעיר ראש חודש!","ומשיבים: \u0003צריכא\u0004 \u0005[צריך\u0006 הדבר להיאמר\u0005],\u0006 \u0003דאי מהתם הוה אמינא\u0004 \u0005[שאם\u0006 הייתי לומד רק \u0005משם,\u0006 \"שור או כבש או עז\", הייתי אומר]: \u0003הני מילי\u0004 \u0003היכא דלא נחת לדרי\u0004 \u0005[דברים אלה,\u0006 שנדמה פסול להקרבה, אמורים במקום שאינו יורד לדורות], שאין כמוהו בדורות שלפניו, \u0003אבל היכא דנחת\u0004 \u0005[במקום שיורד\u0006 לדורות\u0005],\u0006 כגון רחל בת עז בת רחל — אימא \u0005[אמור]\u0006 ש\u0003לא\u0004 יהא פסול, שהרי חזרה שיות למקומה. לכך הוצרך לדייק מ\"אחד\" שצריך שיהא שעיר מששת ימי בראשית. \u0003ואי מהכא הוה אמינא\u0004 \u0005[ואם\u0006 הייתי לומד רק \u0005מכאן,\u0006 מ\"שעיר אחד\", הייתי אומר]: \u0003הני מילי\u0004 \u0005[דברים אלו],\u0006 שנדמה פסול, אמורים \u0003לגבי קרבן חובה,\u0004 כגון שעיר ראש חודש, \u0003אבל\u0004 לקרבן \u0003נדבה לא\u0004 ייפסל, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 הדבר להידרש מ\"או עז\", העוסק בקרבנות בכלל.","ושבים לדינו של נדמה. אמר ר' אחא בר יעקב: הכל מודים, גם ר' מאיר המחייב בבכורה, ש\u0003אין לוקין על צמרו\u0004 של כבש בן עז \u0003משום כלאים,\u0004 אם לבש אותו יחד עם פשתן, \u0003שנאמר: \"לא תלבש שעטנז\u0004 צמר ופשתים יחדיו\" (דברים כב, יא), ויש ללמוד מזה על זה: \u0003מה פשתן\u0004 הריהו דבר \u0003שלא נשתנה,\u0004 שאין פשתן משתנה ממה שהוא, \u0003אף צמר\u0004 האמור בפסוק זה הוא צמר \u0003שלא נשתנה,\u0004 וצמר של זה נשתנה משל אמו, שאין לה צמר אלא שיער.","וכן \u0003אמר רב פפא: הכל מודים שצמרו\u0004 של כבש בן עז \u0003פסול לתכלת,\u0004 כלומר, לציצית, \u0003שנאמר: \"לא תלבש שעטנז\u0004 צמר ופשתים יחדיו\", ומיד אחר כך נאמר: \u0003\"גדלים תעשה לך\u0004 על ארבע כנפות כסותך\" (דברים כב, יב), ומשם למדנו כי אף ציצית יכולה שתהיה עשויה צמר או פשתים, ויש ללמוד מפשתן לצמר: \u0003מה פשתן שלא נשתנה\u0004 — \u0003אף צמר שלא נשתנה.\u0004","ובדומה לכך, אמר רב נחמן בר יצחק: הכל מודים שאין בגד העשוי מ\u0003צמרו\u0004 של כבש בן עז מטמא בנגעים, שנאמר: \"והבגד כי יהיה בו צרעת בבגד צמר או בבגד פשתים\" (ויקרא יג, מז), וגם כאן למדים דינו של הצמר מן הפשתן: \u0003מה פשתים שלא נשתנה\u0004 — \u0003אף צמר שלא נשתנה.\u0004","ובעקבות דרשות אלו \u0003אמר רב אשי, אף אנו נאמר: הדלה\u0004 (הגביה, סיכך) הגפן על גבי תאינה — \u0003יינו\u0004 של גפן זו פסול לנסכים על המזבח. \u0003מאי טעמא\u0004 \u0005[מה הטעם\u0006\u0005]?\u0006 נאמר: \"להקריב אשה לה'... \u0003זבח ונסכים\"\u0004 (ויקרא כג, לז), הרי הקישם הכתוב זה לזה, ללמדנו: \u0003מה זבח\u0004 — \u0003שלא נשתנה,\u0004 כפי שלמדנו לעיל, שנדמה פסול לקרבן, \u0003אף נסכים\u0004 — \u0003שלא נשתנו.\u0004 וגפן זו שהדלה על גבי תאנה נשתנתה מגפן רגילה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבינא:\u0004 לדבריך, שהדלייה גורמת לשינוי, אם \u0003הדלה פשתן על גבי היגא\u0004 (מין שיח קוצני) — \u0003הכי נמי דלישתני\u0004 \u0005[כך גם כן\u0006 תאמר שישתנה\u0005]?\u0006 האם נדון עליו כעל פשתן שנשתנה? \u0003אם כן לא מצית אמרת\u0004 \u0005[אין אתה יכול לומר]\u0006 מה שאמרו חכמים בדרשותיהם לעיל: \u0003\"מה פשתן שלא נשתנה\", דהא\u0004 \u0005[שהרי]\u0006 \u0003פשתן נמי משתני\u0004 \u0005[גם כן משתנה]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: אין להשוות הדלייה להדלייה, \u0003זה,\u0004 גפן שהדלה על גבי תאנה — \u0003נשתנה ריחו, וזה,\u0004 פשתן שהדלה על גבי היגא, \u0003לא נשתנה ריחו.\u0004","\u0003רחל שלא ביכרה\u0004 עדיין, \u0003וילדה שני זכרים, ויצאו שני ראשיהן כאחת\u0004 — \u0003ר' יוסי הגלילי אומר: שניהן\u0004 ניתנים \u0003לכהן,\u0004 ששניהם נחשבים לבכור, שנאמר: \"וכל פטר שגר בהמה אשר יהיה לך הזכרים לה' \"(שמות יג, יב), בלשון רבים. \u0003וחכמים אומרים: אי אפשר לצמצם,\u0004 לדייק ששניהם אכן יצאו ממש בבת אחת. ורק אחד מהם בכור, \u0003אלא\u0004 שאין אנו יודעים איזה מהם, ולכן \u0003אחד\u0004 נשאר \u0003לו,\u0004 לבעלים, \u0003ואחד לכהן.\u0004 וכיצד מחלקים?","\u0003ר' טרפון אומר: הכהן בורר\u0004 (בוחר) לו את היפה. ר' עקיבא אומר: הבעלים והכהן \u0003משמנין\u0004 (עושים שומא) \u0003ביניהן,\u0004 והכהן נוטל את הכחוש (כפי שיתבאר בגמרא). \u0003והשני,\u0004 הנשאר ביד הבעלים, הואיל והוא ספק בכור — אסור לשוחטו כשהוא תמים, שמא הוא שוחט בכור מחוץ למקדש. ולכן \u0003ירעה עד שיסתאב,\u0004 כלומר, עד שיפול בו מום, ואז מותר לו לשוחטו ולאוכלו."],["\u0003ו\u0004כשיישחט \u0003חייב במתנות,\u0004 צריך לתת לכהן זרוע לחיים וקיבה, ככל בהמת חולין. \u0003ור' יוסי פוטר\u0004 אותו ממתנות. \u0003מת אחד מהן,\u0004 מן השניים שנולדו יחד, ואין לפנינו אלא אחד שהוא ספק בכור, מה דינו? ר' טרפון אומר: יחלוקו הבעלים והכהן. \u0003ר' עקיבא אומר:\u0004 כיון שיש ספק אם הוא הבכור — יישאר ביד הבעלים, שכן \u0003המוציא\u0004 ממון \u0003מ\u0004חזקת \u0003חבירו עליו\u0004 מוטלת \u0003הראיה\u0004 ששלו הוא. וכל זה אם נולדו שני זכרים, ואחד מהם בוודאי בכור, אלא שיש ספק איזה מבין השנים. אבל אם נולדו \u0003זכר ונקבה\u0004 ואז ייתכן שאין כאן כלל בכור — \u0003אין כאן לכהן כלום\u0004 לדעת הכל.","\u0003אמרי דבי\u0004 \u0005[אמרו בבית\u0006 מדרשו\u0005]\u0006 של ר' ינאי: לר' יוסי הגלילי שמעינן ליה \u0003דאמר\u0004 \u0005[שמענו אותו ש\u0006הוא אומר] במשנתנו כי \u0003אפשר לצמצם,\u0004 כלומר, ייתכן ששני דברים מתרחשים בדיוק יחד, בדבר שקורה \u0003בידי שמים,\u0004 כלומר, מאליו, וכגון יציאת שני ראשים כאחד. \u0003וכל שכן\u0004 שהוא סבור שאפשר לצמצם בדבר שנעשה \u0003בידי אדם,\u0004 שמכוון לעשות בדיוק ובמכוון. ואולם \u0003רבנן\u0004 \u0005[חכמים],\u0006 שמענו אותם במשנתנו שהם אומרים: \u0003בידי שמים אי אפשר לצמצם,\u0004 שאין להניח שדבר הנעשה מאליו נעשה בדיוק מוחלט. לענין צמצום \u0003בידי אדם,\u0004 שמכוון לעשות דבר בדיוק, \u0003מאי\u0004 \u0005[מה]\u0006 דעתם?","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו במשנה: \u0003חוט של סיקרא\u0004 (צבע אדום) היה \u0003חוגרו\u0004 למזבח \u0003באמצע\u0004 גובהו, כדי \u0003להבדיל בין\u0004 מקום דמים העליונים, שצריך ליתנם בחציו העליון של המזבח, \u0003ובין\u0004 מקום \u0003דמים התחתונים,\u0004 שצריך לזורקם בחציו התחתון. \u0003ואי אמרת\u0004 \u0005[ואם אתה אומר]\u0006 שלדעת חכמים \u0003אי אפשר לצמצם\u0004 גם \u0003בידי אדם,\u0004 הרי ייתכן שלא היה חוט הסיקרא בדיוק באמצע, ונמצא כשהוא נותן את הדם בסמוך לו, \u0003זימנין דקא יהיב\u0004 \u0005[פעמים שהוא נותן]\u0006 דמים \u0003עליונים למטה\u0004 מאמצע המזבח, ותחתונים למעלה משם! ומשיבים: מדובר היה \u0003דמרווח בה פורתא\u0004 \u0005[שמרווח,\u0006 מרחיב אותו מעט] את חוט הסיקרא, וכך כשהוא נותן למעלה ולמטה ממנו בוודאי עושה כדין.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה \u0003ממדת כלים\u0004 של מקדש, וכן \u0003ממדת מזבח,\u0004 שנתנה להם התורה מידות מדוייקות. ומכאן שהיא מניחה שניתן לעשותם כך. ודוחים: משם אין ראיה, שכן \u0003שאני התם דרחמנא אמר\u0004 \u0005[שונה שם, שהתורה אמרה]\u0006 \u0003עביד\u0004 \u0005[עשה]\u0006 כלים ומזבח, \u0003ובכל היכי דמצית למיעבד ניחא ליה\u0004 \u0005[ובכל אופן שאתה יכול לעשות, נוח לו\u0006 לה'\u0005],\u0006 וכפי שנאמר על ידי דוד המלך: \u0003\"הכל בכתב מיד ה' עלי השכיל\u0004 כל מלאכות התבנית\" (דברי הימים א כח, יט).","\u0003אמר רב קטינא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו בברייתא: תנור חרס טמא שנחלק לשנים — החלק הגדול, שהוא רובו של התנור, נשאר טמא. \u0003חלקו\u0004 את התנור לשנים, ומדד את שני החלקים \u0003והן שוין\u0004 — \u0003שניהן טמאים\u0004 מספק, \u0003לפי שאי אפשר לצמצם,\u0004 ובוודאי אחד מהם גדול מהאחר, ונשתייר בו רובו של התנור, אבל איננו יכולים לדעת איזה מהם. ומכאן שאנו מניחים שאי אפשר לצמצם! \u0003אמר רב כהנא:\u0004 אין מכאן ראיה, כי שאני \u0005[שונה]\u0006 \u0003כלי חרס,\u0004 שלא ניתן לכוון את הדבר, וגם לא למדוד אותו במדוייק, \u0003הואיל ויש בו גומות,\u0004 שיש בקצות השברים שקעים ובליטות.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה מדין הרוג שנמצא מוטל בדרך ולא נודע מי הרגו, שהתורה ציותה למדוד ממנו אל הערים הסמוכות, והעיר הקרובה ביותר צריכה להביא עגלה ערופה. וכך שנינו במשנה: \u0003נמצא מכוון בין שתי עיירות,\u0004 קרוב לשתיהן במידה שווה — \u0003שתיהן מביאות שתי עגלות,\u0004 כל עיר עגלה אחת, אלו \u0003דברי ר' אליעזר. מאי טעמא\u0004 \u0005[מה הטעם]?\u0006","\u0003לאו משום דקסבר\u0004 \u0005[האם לא משום שהוא סבור]\u0006 ש\u0003בידי אדם אפשר לצמצם,\u0004 וכדעת חכמים במשנתנו, ושתי הערים באמת קרובות בשווה אל החלל. \u0003ו\u0004מה שנאמר \"העיר ה\u0003קרובה\u0004 אל החלל\" (דברים כא, ג) בלשון יחיד אינו בדוקא, אלא כוונתו — \u0003ואפילו קרובות?\u0004","ודוחים: \u0003לא, ר' אליעזר\u0004"],["\u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כ\u0004דעת \u0003רבי יוסי הגלילי,\u0004 ש\u0003אמר: אפשר לצמצם בידי שמים, וכל שכן בידי אדם,\u0004 ואין להוכיח מכאן מהי דעת חכמים במשנתנו.","ומציעים: \u0003נימא כתנאי\u0004 \u0005[\u0006האם \u0005נאמר\u0006 שהשאלה אם אפשר לצמצם בידי אדם, שנויה \u0005כ\u0006מחלוקת \u0005תנאים],\u0006 שכן שנינו בברייתא: \u0003נמצא\u0004 ההרוג \u0003מכוון בין שתי עיירות\u0004 — \u0003לא היו עורפין\u0004 עגלה. \u0003ר' אליעזר אומר: שתיהן מביאות שתי עגלות,\u0004 כל עיר — עגלה אחת. \u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא ב\u0006דבר \u0005זה הם חלוקים],\u0006 \u0003דתנא קמא סבר\u0004 \u0005[שהתנא הראשון סבור]:\u0006 \u0003אי אפשר לצמצם\u0004 ולדייק במדידה, ומספק איזו עיר קרובה יותר — אין אף אחת מהן מביאה עגלה, ור' אליעזר סבר \u0005[סבור]\u0006 כי אפשר לצמצם? ותוהים: \u0003ותיסברא\u0004 \u0005[ו\u0006כי \u0005יכול אתה לסבור כן]?\u0006 \u0003אי קסבר\u0004 \u0003תנא\u0004","\u0003קמא\u0004 \u0005[אם סבור התנא הראשון]\u0006 כי אי אפשר לצמצם, אמאי \u0005[מדוע]\u0006 \u0003לא היו עורפים\u0004 כלל? יביאו בני שתי העיירות \u0003עגלה אחת בשותפות, ויתנו\u0004 ביניהם: אם עירכם הקרובה — הריהי שלכם ונערפת עבורכם, ואם עירנו הקרובה — הריהי שלנו ונערפת עבורנו!","\u0003אלא,\u0004 ביחס \u0003להני תנאי\u0004 \u0005[ל\u0006מחלוקת של תנאים אלה] יש לומר כי \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003אפשר לצמצם,\u0004 וכדעת ר' יוסי הגלילי. \u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004שאלה האם מה שנאמר \"העיר ה\u0003קרובה\" (\u0004דברים כא, ג) בא ללמד: קרובה \u0003ולא קרובות, קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 \u0003דתנא קמא סבר\u0004 \u0005[שהתנא הראשון סבור]:\u0006 דוקא כאשר עיר אחת \u0003קרובה\u0004 לחלל יש להביא עגלה, \u0003ולא\u0004 אם שתים \u0003קרובות\u0004 באותה מידה, \u0003ור' אליעזר סבר\u0004 \u0005[סבור]:\u0006 \u0003\"קרובה\"\u0004 — \u0003ואפילו קרובות.\u0004 ונמצא שאין פתרון לשאלה האם בידי אדם אפשר לצמצם, לדעת חכמים שבמשנתנו.","ושואלים: \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה]\u0006 על שאלה זו? כיצד פתרו אותה? אמר רב חייא בר אבין אמר רב עמרם, תנא \u0005[שנה\u0006 החכם\u0005]\u0006 ברייתא נוספת בענין עגלה ערופה: \u0003נמצא\u0004 ההרוג \u0003מכוון בין שתי עיירות, ר' אליעזר אומר: שתיהן מביאות שתי עגלות, וחכמים אומרים: יביאו עגלה אחת בשותפות ויתנו:\u0004 אם אתם הקרובים — הריהי שלכם, ואם אנו קרובים — הריהו שלנו.","ונברר: \u0003מאי קסברי רבנן\u0004 \u0005[מה סבורים חכמים\u0006 אלה\u0005]?\u0006 \u0003אי קסברי רבנן\u0004 \u0005[אם סבורים חכמים]\u0006 ש\u0003אפשר לצמצם, ו\u0004מה שנאמר \"העיר ה\u0003קרובה\"\u0004 כוונתו — \u0003ואפילו קרובות,\u0004 אם כן \u0003לייתי תרתי\u0004 \u0005[שיביאו שתיים,\u0006 שתי עגלות\u0005]!\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 לדעתם \u0003\"קרובה\"\u0004 דוקא, \u0003ולא קרובות\u0004 — \u0003אפילו חדא לא לייתי\u0004 \u0005[אחת לא יביאו]!\u0006 \u0003אלא לאו שמע מינה קסברי רבנן\u0004 \u0005[האם לא תלמד מכאן שסבורים חכמים]:\u0006 \u0003אי אפשר לצמצם, ואפילו בידי אדם,\u0004 ולא ייתכן ששתיהן קרובות באותה מידה, ולכן מביאים עגלה אחת בשותפות ומתנים עליה. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","שנינו במשנה: רחל שילדה שני זכרים, ויש ספק איזה מהם יצא ראשון, \u0003ר' טרפון אומר:\u0004 הכהן \u0003בורר לו את היפה.\u0004 ומבררים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רבי טרפון?\u0004 ועונים: קא סבר \u0005[סבור הוא]:\u0006 \u0003ההוא דבריא נפק ברישא\u0004 \u0005[אותו\u0006 ולד \u0005ש\u0006הוא \u0005בריא\u0006 וחזק יותר ודאי \u0005יצא בתחילה],\u0006 והוא הבכור.","ועוד שנינו: \u0003ר' עקיבא אומר משמנין\u0004 ביניהן. ובפירוש הדברים, אמר ר' חייא בר אבא אמר ר' יוחנן: הכהן נוטל את ה\u0003כחושה\u0004 שביניהם. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חייא בר אבא לר' יוחנן: והא אנן\u0004 \u0005[והרי אנו]\u0006 \u0003\"משמנין ביניהן\" תנן\u0004 \u0005[שנינו],\u0006 ומשמעות הדבר — שמחלקים ביניהם את שוויים של שני הולדות! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003עד דאכלת כפנייתא\u0004 \u0005[עד שאתה אכלת תמרים]\u0006 \u0003בבבל, תרגימנא מסיפא\u0004 \u0005[\u0006אנו כבר תרגמנו, הסברנו, את הענין הזה \u0005מסוף\u0006 המשנה],","\u0003דקתני סיפא\u0004 \u0005[ששנינו בסוף]:\u0006 \u0003מת אחד מהן\u0004 מהשנים שיצאו כאחד — \u0003ר' טרפון אומר: יחלוקו, ר' עקיבא אומר:\u0004 הכהן, שהוא המוציא מחבירו — \u0003עליו\u0004 מוטלת \u0003הראיה\u0004 שזה שנותר בחיים הוא הבכור. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 ש\u0003\"משמנין ביניהן\"\u0004 שאמר רבי עקיבא בתחילה, כוונתו \u0003דכי הדדי פליגי\u0004 \u0005[שחולקים זה עם זה]\u0006 — \u0003הכי נמי לפלגי גבי הדדי\u0004 \u0005[כך גם כן,\u0006 כשמת אחד מהם, שיחלקו זה עם זה]! \u0003אלא מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"משמנין\u0004 ביניהן\" — \u0003שומן,\u0004 מה שהאחד שמן מחבירו, \u0003יהא ביניהן,\u0004 כלומר, ידונו עליו, \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 בעל הבית \u0003לכהן: אייתי\u0004 \u0005[הבא]\u0006 \u0003ראיה\u0004 שהשמן \u0003בכור הוא, ושקיל\u0004 \u0005[וקח\u0006 אותו\u0005].\u0006 והואיל ואין לו ראיה — יטול את הכחוש.","עוד שנינו במשנה: \u0003והשני,\u0004 שנשאר ביד הבעלים, ירעה עד שיסתאב (שיפול בו מום), ויישחט כדי לאוכלו. וחייב במתנות, שצריך הבעלים לתת לכהן זרוע לחיים וקיבה, כדין השוחט בהמת חולין. \u0003ור' יוסי פוטר.\u0004 ושואלים: מאי טעמא \u0005[מה הטעם]\u0006 של \u0003ר' מאיר,\u0004 המחייב במתנות? \u0003אמר ר' יוחנן: הואיל וכהן בא עליו\u0004 בטענה משני צדדין, דאמר ליה \u0005[שאומר לו]:\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003בכור הוא\u0004 — \u0003כוליה דידי\u0004 \u0005[כולו שלי]\u0006 \u0003הוא, אי\u0004 \u0005[אם]\u0006 \u0003לא בכור הוא\u0004 — \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי מתנות מיניה\u0004 \u0005[ממנו].\u0006","ושואלים: \u0003ור' יוסי מאי טעמא\u0004 \u0005[מה טעם]\u0006 הוא פוטרו מן המתנות? \u0003אמר רבא:\u0004 במקרה זה \u0003עשו\u0004 חכמים את \u0003שאינו זוכה כזוכה,\u0004 וזכה הכהן מתחילה בבכור, \u0003ואף על גב דלא מטא לידיה\u0004 \u0005[ואף על פי שלא הגיע לידו]\u0006 של הכהן, נחשב הדבר \u0003כמאן דמטא לידיה\u0004 \u0005[כמי שהגיע לידו],\u0006 \u0003ו\u0004לאחר מכן \u0003זבניה\u0004 \u0005[מכר אותו]\u0006 \u0003לישראל במומיה\u0004 \u0005[במומו]\u0006 תחת זה שקיבל מידו. ונמצא שיש ביד הבעלים בכור שקנה מיד הכהן, שהוא פטור מן המתנות.","\u0003אמר ר' אלעזר: הכל מודים בספק בכור\u0004 המצוי ביד ישראל, במקרה \u0003שאין חליפין\u0004 שלו מצויים \u0003ביד כהן,\u0004 שלא קיבל הכהן ולד אחר תמורתו — \u0003שחייב במתנות.\u0004","ושואלים: \u0003הכל מודים מאן\u0004 \u0005[מיהו],\u0006 \u0003ר' יוסי? פשיטא\u0004 \u0005[פשוט]\u0006 שכך הוא! הרי \u0003עד כאן לא קא פטר\u0004 \u0005[לא\u0006 שמענו ש\u0005פוטר]\u0006 \u0003ר' יוסי התם\u0004 \u0005[שם]\u0006 במשנתנו את הספק מן המתנות \u0003אלא\u0004 במקרה ש\u0003חליפין\u0004 שלו \u0003ביד כהן,\u0004 משום שאז ניתן לומר: \u0003עשו שאינו זוכה כזוכה, אבל\u0004 אם \u0003אין חליפין ביד כהן\u0004 — \u0003לא!\u0004","ומשיבים: עדיין צריך הדבר להיאמר, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003טעמא\u0004 \u0005[הטעם]\u0006 של \u0003רבי יוסי\u0004 אינו משום שעשו את הכהן כאילו זכה מתחילה בולד שביד הבעלים, אלא משום \u0003דקסבר\u0004 \u0005[שהוא סבור]\u0006 \u0003דאי מחייבת ליה\u0004 \u0005[שאם אתה מחייב אותו]\u0006 \u0003במתנות,\u0004 ככל בהמת חולין — \u0003אתי ליה\u0004 \u0005[יבואו בו]\u0006 \u0003לידי גיזה ועבודה,\u0004 ולא ינהגו בו דין ספק בכור, שאסור בגיזה ובעבודה. ונימוק זה שייך בכל ספק בכור, \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003אין חליפין\u0004 שלו \u0003ביד כהן.\u0004 לכן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 ר' אלעזר שרק במקום שקיבל הכהן את חליפיו, פטור הספק שביד ישראל ממתנות.","ושואלים: \u0003ומי מצית אמרת הכי\u0004 \u0005[והאם יכול היית לומר,\u0006 לפרש \u0005כך],\u0006 שזהו טעמו של ר' יוסי? \u0003והתני סיפא\u0004 \u0005[והרי\u0006 הוא \u0005שונה בסוף,\u0006 במשנה להלן\u0005],\u0006 \u0003שהיה ר' יוסי אומר:\u0004"],["\u0003כל שחליפיו ביד כהן פטור מן המתנות, ור' מאיר מחייב.\u0004 ונדייק: דווקא משום ש\u0003חליפין ביד כהן\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 פטור מן המתנות, אבל אם \u0003אין חליפין ביד כהן\u0004 — \u0003לא!\u0004","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר],\u0006 יכול היית לומר כי \u0003ר' יוסי\u0004 אינו אומר כן משום שזו דעתו, אלא \u0003לדבריו\u0004 של \u0003ר' מאיר קאמר ליה\u0004 \u0005[הוא אומר לו],\u0006 וכך הוא אומר: \u0003לדידי\u0004 \u0005[לשיטתי]\u0006 \u0003אפילו אין חליפין ביד כהן\u0004 פטור מן המתנות, וטעם הדבר, משום \u0003דאי מחייבת ליה\u0004 \u0005[שאם אתה מחייב אותו]\u0006 \u0003במתנות אתי ליה\u0004 \u0005[יבואו בו]\u0006 \u0003לידי גיזה ועבודה.\u0004 אבל גם \u0003לדידך\u0004 \u0005[לשיטתך]\u0006 שאתה מחייב במתנות, ואינך חושש לכך — \u0003אודי לי מיהא היכא\u0004 \u0005[הודה לי על כל פנים במקום]\u0006 ש\u0003חליפין ביד כהן\u0004 שפטור מן המתנות, מטעם ש\u0003עשו שאינו זוכה כזוכה! ואמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' מאיר: לא,\u0004 אין אני מסכים לכך, אלא בכל מקרה חייב במתנות. ומשום שניתן היה לפרש כך את הדבר, אמר ר' אלעזר שטעמו של ר' יוסי הוא רק משום שחליפיו ביד כהן, ובמקום שלא שייך טעם זה — חייב במתנות.","\u0003ו\u0004עוד בענין זה \u0003אמר רב פפא: הכל מודים בספק מעשר\u0004 בהמה \u0003שפטור מן המתנות,\u0004 כדין מעשר ודאי. ושואלים: \u0003הכל מודים מאן\u0004 \u0005[מיהו],\u0006 \u0003ר' מאיר? פשיטא\u0004 \u0005[פשוט]\u0006 שכך הוא, ולא הוצרך כלל להיאמר הדבר, שהרי \u0003עד כאן לא\u0004 שמענו כי \u0003קמחייב\u0004 \u0005[מחייב]\u0006 \u0003ר' מאיר התם\u0004 \u0005[שם,\u0006 במשנה שלנו\u0005]\u0006 במתנות, \u0003אלא בספק בכור,\u0004 \u0003הואיל ובא עליו\u0004 ה\u0003כהן משני צדדין,\u0004 שאם בכור — הוא כולו של כהן, ואם חולין — מתנותיו שלו. \u0003אבל ספק מעשר,\u0004 שאם מעשר הוא — אין הכהן זכאי בו, אלא הוא של הבעלים — \u0003לא,\u0004 אין הכהן יכול להוציא מידו את המתנות מספק!","ומשיבים: מכל מקום הוצרך רב פפא לומר כן, \u0003מהו דתימא\u0004 \u0005[שתאמר,\u0006 יכול היית לומר\u0005]:\u0006 \u0003טעמא\u0004 \u0005[הטעם]\u0006 של \u0003ר' מאיר,\u0004 שמחייב ספק בכור במתנות, אינו משום שהכהן זכאי להן על פי דין, אלא כדי ש\u0003לא תשתכח תורת מתנות\u0004 מן החולין, ואם כן, \u0003אפילו\u0004 ב\u0003ספק מעשר נמי\u0004 \u0005[גם כן]\u0006 הריהו מחייב, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 רב פפא שלא.","ומקשים: \u0003ומי מצית אמרת הכי\u0004 \u0005[והאם יכול היית לומר כך]\u0006 שזהו טעמו של ר' מאיר, כדי שלא תשכח תורת מתנות, ולא משום שיש לכהן טענה משני צדדים? \u0003והקתני סיפא\u0004 \u0005[והרי שנינו בסוף,\u0006 במשנה להלן], \u0003שהיה ר' יוסי אומר: כל\u0004 ספק בכור \u0003שחליפיו ביד כהן פטור מן המתנות.\u0004 ואין הכהן יכול לטעון שאם בכור הוא כולו שלו, משום שנחשב כאילו כבר זכה בו הכהן, ומכרו לו. \u0003ור' מאיר מחייב.\u0004 ומשמע, שר' מאיר מחייב משום שאינו מקבל את טענתו של ר' יוסי, שעשו את הכהן כזוכה בבכור, ולדעתו יש לכהן טענה משני צדדים!","ודוחים: \u0003מהו דתימא\u0004 \u0005[שתאמר,\u0006 יכול היית לומר\u0005]:\u0006 \u0003ר' מאיר\u0004 — \u0003אפילו\u0004 ב\u0003ספק מעשר מחייב\u0004 במתנות, למרות שאין הכהן בא עליו משני צדדים, וטעמו — כדי שלא תישכח תורת מתנות. והא דמיפלגי \u0005[וזה שהם חלוקים\u0006 במשנה\u0005]\u0006 \u0003ב\u0004ספק בכור ש\u0003חליפין\u0004 שלו ביד הכהן, הרי זה כדי \u0003להודיעך כחו\u0004 של \u0003רבי יוסי, דפטר אפילו היכא\u0004 \u0005[ש\u0006הוא \u0005פוטר אפילו במקום]\u0006 ש\u0003כהן בא עליו משני צדדין,\u0004 ואין ללמוד מכאן על דעת ר' מאיר, לכך \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 רב פפא שר' מאיר פוטר ספק מעשר מן המתנות.","שנינו במשנה: \u0003מת אחד מהן,\u0004 משני ולדות שספק איזה מהם הוא הבכור, \u0003ר' טרפון אומר: יחלוקו\u0004 ביניהם את החי. ושואלים: \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003יחלוקו?\u0004 והרי לשיטת ר' טרפון בתחילת המשנה, הכהן נוטל את היפה והשמן שביניהם. ולפיכך, \u0003ניחזי\u0004 \u0005[נראה],\u0006 \u0003אי\u0004 \u0005[אם] ה\u0006\u0003שמן\u0004 שביניהם \u0003מית\u0004 \u0005[מת]\u0006 — הרי של ה\u0003כהן הוא,\u0004 \u0003והאי דאיכא\u0004 \u0005[וזה שישנו,\u0006 החי\u0005]\u0006 הוא של \u0003בעל הבית; ואי\u0004 \u0005[ואם]\u0006 \u0003כחוש מית\u0004 \u0005[מת]\u0006 — זה של \u0003בעל הבית מית\u0004 \u0005[מת],\u0006 \u0003והאי דאיכא\u0004 \u0005[וזה שישנו]\u0006 של \u0003כהן הוא! אמר ר' אמי: חזר בו ר' טרפון\u0004 מדבריו בתחילת המשנה, ולדעתו בכל מקרה יחלקו הבעלים והכהן בוולדות.","ועוד שנינו, \u0003ר' עקיבא אומר:\u0004 אם מת אחד מהם — הכהן שהוא \u0003המוציא מחבירו\u0004 — \u0003עליו\u0004 מוטלת חובת \u0003הראיה\u0004 שהחי הוא הבכור, ולכן הוא נשאר ביד הבעלים. \u0003אמר ר' חייא: משל\u0004 להסביר את טעמו של \u0003ר' טרפון\u0004 האומר כי יחלוקו, \u0003למה הדבר דומה? לשנים שהפקידו\u0004 כל אחד מהם כבש אצל אותו \u0003רועה,\u0004 ומת אחד מהם, ואין ידוע של מי היה, שהדין הוא \u0003שמניח\u0004 ה\u0003רועה ביניהם\u0004 את החי, \u0003ומסתלק.\u0004 ובמקרה מעין זה מדובר כאן, שהחי אינו ברשותו של אף אחד מהם, ולכן סובר ר' טרפון שיחלוקו.","\u0003ומשל\u0004 להסביר את דבריו של \u0003רבי עקיבא, למה הדבר דומה? לאחד שהפקיד\u0004 כבש \u0003אצל בעל הבית,\u0004 ונתערב בכבש של בעל הבית, ומת אחד מן הכבשים, וכל אחד מהם אומר ששל האחר מת. \u0003ש\u0004הואיל והחי מצוי ברשותו של בעל הבית — המפקיד, שהוא \u0003המוציא מחבירו\u0004 — \u0003עליו הראיה.\u0004 ובמקרה מעין זה מדובר כאן, שהולד החי נמצא ברשותו של בעל הבית, ולכן על הכהן להביא ראיה שהחי הוא הבכור.","ותמהים: \u0003אלא\u0004 הואיל וכל אחד מהם עוסק במציאות שונה, אם כן \u0003במאי פליגי\u0004 \u0005[במה הם חלוקים]?\u0006 וכי \u0003ר' עקיבא פליג\u0004 \u0005[חולק]\u0006 \u0003בשנים שהפקידו אצל רועה,\u0004 ואינו מודה \u0003שמניח רועה ומסתלק? ו\u0004כי \u0003ר' טרפון פליג\u0004 \u0005[חולק]\u0006 \u0003באחד שהפקיד אצל בעל הבית,\u0004 ואינו סבור שבמקרה כזה המוציא מחבירו עליו הראיה? \u0003אמר רבא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב פפא: הכל מודים בשנים שהפקידו אצל רועה\u0004 — שמניח רועה ביניהם ומסתלק, ובאחד שהפקיד אצל בעל הבית — \u0003שהמוציא מחבירו עליו הראיה.\u0004","\u0003לא נחלקו\u0004 במשנתנו \u0003אלא\u0004 במקרה שאותו ספק בכור נמצא \u0003בחצר בעל הבית, ורועה\u0004 בהמות בעל הבית הוא \u0003כהן\u0004 שבעל הבית רגיל לתת לו את הבכורות, ונחלקו לאיזה מקרה יש לדמות אותו. \u0003ר' טרפון סבר\u0004 \u0005[סבור]:\u0006 בעל הבית \u0003אקנויי קא מקני ליה\u0004 \u0005[מקנה הוא לו\u0006 לרועה הכהן] מקום \u0003בחצירו,\u0004 כדי שיזכה אגב מקום זה בבכורות שייוולדו בעדרו, \u0003ו\u0004הוא משום ש\u0003ניחא ליה דליתעביד מצוה\u0004 \u0005[נוח לו שתיעשה מצוה]\u0006 באופן זה. \u0003ו\u0004הואיל ויש לשניהם רשות בחצר, ואינה שייכת לאחד מהם באופן בלעדי, \u0003הוה ליה\u0004 \u0005[הריהו]\u0006 \u0003כשנים שהפקידו אצל רועה, שמניח רועה ביניהן\u0004 את הכבש החי \u0003ומסתלק,\u0004 ולפיכך הם חולקים אותו ביניהם.","\u0003ור' עקיבא סבר\u0004 \u0005[סבור]:\u0006 \u0003כיון דאית ליה פסידא\u0004 \u0005[ש\u0006במקרה זה \u0005יש לו\u0006 לבעל הבית \u0005הפסד\u0006 בכך\u0005]\u0006 — \u0003לא מקני ליה מידעם\u0004 \u0005[איננו מקנה לו\u0006 לרועה \u0005כלום]\u0006 בחצירו, \u0003ו\u0004לפיכך, \u0003הוה ליה\u0004 \u0005[הרי זה]\u0006 נדון \u0003כאחד שהפקיד\u0004 כבש \u0003אצל בעל הבית,\u0004 ומת אחד מן הכבשים — \u0003שהמוציא מחבירו עליו הראיה.\u0004","\u0003שתי רחיליו\u0004 של אדם שעדיין \u0003לא ביכרו וילדו שני זכרים\u0004 ונתערבו — \u0003שניהם\u0004 יינתנו \u0003לכהן,\u0004 מפני שכל אחד הוא בכור לאמו. ילדו \u0003זכר ונקבה\u0004 — \u0003הזכר לכהן,\u0004 שהרי הוא ודאי בכור. ילדו \u0003שני זכרים ונקבה\u0004 — \u0003אחד\u0004 הזכרים \u0003לו ואחד לכהן,\u0004 שהרי אחד הזכרים הוא ודאי בכור. וכיצד יחלקו ביניהם את הזכרים? \u0003ר' טרפון אומר: הכהן בורר לו את היפה, ר' עקיבא אומר: משמנין ביניהן. והשני,\u0004 שביד הבעלים, שספק בכור הוא — \u0003ירעה עד שיסתאב,\u0004 עד שיפול בו מום, ואז יהיה מותר לשוחטו.","\u0003ו\u0004כשיישחט \u0003חייב במתנות,\u0004 לתת זרוע לחיים וקיבה לכהן, כדין בהמת חולין. \u0003ר' יוסי פוטר\u0004 מהמתנות. \u0003מת אחד מהן,\u0004 מה יעשו בחי? \u0003ר' טרפון אומר: יחלוקו\u0004 בו. \u0003ר' עקיבא אומר:\u0004 הבעלים הוא המחזיק ברשותו את החי, והכהן \u0003המוציא מחבירו — עליו\u0004 מוטלת חובת \u0003הראיה.\u0004 ילדו שתי הרחלים \u0003שתי נקבות וזכר או שני זכרים ושתי נקבות\u0004 — \u0003אין כאן לכהן כלום,\u0004 מספק שמא שתי הרחלים ילדו נקבות בתחילה.","היו לאדם שתי רחלים, \u0003אחת\u0004 מהן כבר \u0003ביכרה, ואחת\u0004 עדיין \u0003לא ביכרה, וילדה\u0004 (ילדו) \u0003שני זכרים,\u0004 ויש כאן בכור ודאי, אלא שאין אנו יודעים מהו — זכר \u0003אחד\u0004 נשאר לו לבעלים \u0003ואחד\u0004 ניתן \u0003לכהן.\u0004 וכיצד חולקים? \u0003ר' טרפון אומר: הכהן בורר\u0004 ונוטל \u0003את היפה\u0004 שביניהן, \u0003ר' עקיבא אומר: משמנין ביניהן, והשני ירעה עד שיסתאב\u0004","\u0003וחייב במתנות\u0004 כדין בהמת חולין. \u0003ר' יוסי פוטר\u0004 מהמתנות. וטעמו, \u0003שר' יוסי אומר: כל\u0004 ספק בכור הנמצא ביד הבעלים, \u0003שחליפיו\u0004 נמצאים \u0003ביד כהן\u0004 — \u0003פטור מן המתנות. ור' מאיר מחייב\u0004 במתנות. \u0003מת אחד מהן,\u0004 מה יעשו בחי? \u0003ר' טרפון אומר: יחלוקו. ר' עקיבא אומר: המוציא מחבירו עליו הראיה.\u0004 ילדו \u0003זכר ונקבה\u0004 — \u0003אין כאן לכהן כלום,\u0004 מספק, שמא זו שכבר ביכרה ילדה את הזכר, וזו שלא ביכרה ילדה את הנקבה, ואין כאן כלל בכור.","במשנה הקודמת ובמשנה זו הובאה שלש פעמים מחלוקת ר' טרפון ור' עקיבא בענין שני ולדות שאחד מהם בכור, ונתערבו, שלדעת ר' טרפון, הבריא שביניהם הוא זה שיצא ראשון, ולכן הכהן נוטלו, ולדעת ר' עקיבא הכהן נוטל את הכחוש, משום שהמוציא מחבירו עליו הראיה. ומסבירים: \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו כל המחלוקות הללו, למרות שהם נראות זהות, \u0003דאי אשמועינן קמייתא\u0004 \u0005[שאם\u0006 היה \u0005משמיע לנו את הראשונה],\u0006 ברחל שילדה שני זכרים, היינו אומרים: \u0003בההיא קאמר\u0004 \u0005[אומר]\u0006 \u0003ר' עקיבא\u0004 שאין הכהן נוטל את היפה, משום \u0003דתרי מחדא\u0004 \u0005[ששניים,\u0006 שני זכרים נולדו מרחל אחת], והעובדה שאחד מהם יפה יותר אינה מוכיחה שהוא יצא תחילה.","\u0003אבל\u0004 שתי \u0003רחיליו שלא ביכרו,\u0004 וילדו שני זכרים ונקבה, דתרי מחדא וחד מחדא \u0005[ששניים\u0006 נולדו \u0005מאחת ואחד מאחת]\u0006 — \u0003אימא מודי ליה\u0004 \u0005[אמור שמודה לו]\u0006 \u0003לר' טרפון\u0004 שהכהן נוטל את היפה, משום \u0003דהך דילידא חד שביח טפי\u0004 \u0005[שזו שילדה אחד\u0006 בוודאי ילדה ולד משובח יותר] מזו שילדה שניים.","\u0003ואי אשמועינן הא\u0004 \u0005[ואם היה משמיע לנו\u0006 גם את \u0005זו],\u0006 בשתי רחליו שלא ביכרו, עדיין הייתי אומר: \u0003בהא קאמר\u0004 \u0005[בזו אומר]\u0006 \u0003ר' עקיבא\u0004 שאין טיבו של הולד מהוה ראיה, משום \u0003דתרוייהו\u0004 \u0005[ששתיהן]\u0006 \u0003לא ביכרו, אבל אחת ביכרה ואחת שלא ביכרה וילדו שני זכרים\u0004 — \u0003אימא מודי ליה\u0004 \u0005[אמור שמודה לו]\u0006 \u0003לר' טרפון\u0004 שהכהן נוטל את היפה,"],["\u0003דהך דלא ביכרה שביח טפי\u0004 \u0005[\u0006שהולד \u0005של זו שלא ביכרה משובח יותר],\u0006 על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 הדבר להיאמר בכל המקרים.","\u0003יוצא דופן\u0004 שלא נולד בלידה רגילה, דרך פתח הרחם, אלא שחתכו את דופן רחם אימו והוציאוהו, \u0003והבא אחריו\u0004 שנולד בלידה רגילה, \u0003ר' טרפון אומר:\u0004 בכל אחד מהם יש ספק שמא הוא בכור, ולפיכך \u0003שניהם ירעו עד שיסתאבו,\u0004 כלומר, עד שיפול בהם מום, ואולם אינם ניתנים לכהן, שאינו יכול להוציא ממון מבעליו במקרה של ספק. \u0003ו\u0004לכן \u0003יאכלו במומן\u0004 (כשיפול בהם מום) \u0003לבעלים. ר' עקיבא אומר: שניהן אינן בכור, הראשון\u0004 — \u0003מפני שאינו \"פטר רחם\",\u0004 שאינו הולד שפטר (פתח) את הרחם תחילה, \u0003והשני\u0004 — \u0003מפני שקדמו אחר,\u0004 שאינו הראשון שנולד לאמו.","על מחלוקת ר' טרפון ור' עקיבא במשנתנו, מבררים: \u0003במאי קמיפלגי\u0004 \u0005[במה הם חלוקים]?\u0006 \u0003ר' טרפון מספקא ליה\u0004 \u0005[מסופק לו]\u0006 לגבי \u0003בכור לדבר אחד,\u0004 שנולד ראשון אבל לא דרך פתח הרחם, או שפתח תחילה את הרחם למרות שאינו הראשון ללידה, \u0003אי הוי\u0004 \u0005[אם הוא\u0006 נחשב\u0005]\u0006 \u0003בכור אי לא הוי\u0004 \u0005[אם איננו]\u0006 \u0003בכור. ור' עקיבא פשיטא ליה\u0004 \u0005[פשוט לו]\u0006 ש\u0003בכור לדבר אחד לא הוי\u0004 \u0005[איננו]\u0006 \u0003בכור.\u0004","ובענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בביאור המידות שהתורה נדרשת בהן: המידה \u0003מכלל הצריך לפרט ומפרט הצריך לכלל, כיצד?\u0004 נאמר: \u0003\"קדש לי כל בכור\"\u0004 (שמות יג, ב), \u0003יכול\u0004 לשון \"כל\" אפילו נקבה במשמע? ד תלמוד לומר: \"כל הבכור אשר יולד בבקרך ובצאנך ה\u0003זכר\"\u0004 (דברים טו, יט), ויש לשאול:","\u0003אי\u0004 (אם) \u0003\"זכר\", יכול\u0004 כל זכר שנולד ראשון הריהו בכור, \u0003אפילו יצתה\u0004 (יצאה) \u0003נקבה לפניו? תלמוד לומר: \"פטר רחם\"\u0004 (שמות יג, ב), כלומר, דווקא זכר שיצא ראשון דרך פתח הרחם. ויש לשאול: \u0003אי\u0004 (אם) \u0003פטר רחם, יכול\u0004 כל זכר שיצא ראשון דרך פתח הרחם, \u0003אפילו יצא אחר יוצא דופן? תלמוד לומר: \"בכור\".\u0004 ודנים בברייתא זו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב שרביא לאביי: רישא\u0004 \u0005[בתחילה]\u0006 ששנינו: יכול אפילו יצאה נקבה לפניו? תלמוד לומר \"פטר רחם\", \u0003לא קנסיב לה תלמודא\u0004 \u0005[לוקח,\u0006 משתמש \u0005הלימוד,\u0006 הברייתא\u0005]\u0006 במילה \u0003\"בכור\"\u0004 (תלמוד לומר \"בכור\") ללמדנו שאין הוא נחשב בכור, \u0003אלמא\u0004 \u0005[מכאן]\u0006 שהתנא מניח ש\u0003בכור לדבר אחד\u0004 כגון שהוא ראשון לזכרים, ולא לוולדות, הוי \u0005[הריהו]\u0006 קרוי \u0003\"בכור\".\u0004 ואילו \u0003סיפא\u0004 \u0005[בסוף],\u0006 כשהוא שואל: יכול אפילו יצא אחר יוצא דופן? \u0003קנסיב לה תלמודא\u0004 \u0005[לוקח\u0006 \u0005הלימוד]\u0006 את המלה \u0003\"בכור\",\u0004 ללמדנו שאין די במה שהוא \"פטר רחם\" אלא אם נולד ראשון. \u0003אלמא\u0004 \u0005[מכאן]\u0006 שהוא מניח ש\u0003בכור לדבר אחד לא הוי\u0004 \u0005[נחשב]\u0006 \u0003בכור.\u0004 ואם כן יש לכאורה סתירה בין שני חלקי הברייתא!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003לעולם בכור לדבר אחד לא הוי\u0004 \u0005[אינו קרוי]\u0006 \u0003בכור, ורישא הכי קאמר\u0004 \u0005[ובהתחלה כך הוא אומר]:\u0006 \u0003אי\u0004 (אם) \u0003זכר, יכול\u0004 כל זכר ו\u0003אפילו יוצא דופן? תלמוד לומר: \"פטר רחם\".\u0004 ואין הברייתא עוסקת בנולד אחר נקבה.","\u0003רבינא אמר: לעולם בכור לדבר אחד הוי\u0004 \u0005[הריהו]\u0006 \u0003בכור, וסיפא\u0004 \u0005[ובסוף]\u0006 שהוא למד מ\"בכור\" שהנולד אחר יוצא דופן אינו בכור — אינו למד ממשמעות המלה \"בכור\", אלא מייתור הכתובים, \u0003הכי קאמר\u0004 \u0005[\u0006וכך הוא אומר]: \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך\u0006 לומר\u0005]\u0006 שזה ש\u0003יצא אחר יוצא דופן\u0004 הריהו קדוש בבכורה, אם כן \u0003\"בכור\" דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003למה לי?\u0004"],["\u0003אי למעוטי היכא דיצתה\u0004 \u0005[אם למעט במקום שיצאה]\u0006 \u0003נקבה לפניו\u0004 — \u0003מ\"פטר רחם\" נפקא\u0004 \u0005[יוצא\u0006 הדבר\u0005]!\u0006 \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003\"בכור\"\u0004 — \u0003למעוטי היכא\u0004 \u0005[למעט במקום]\u0006 ש\u0003יוצא אחר יוצא דופן.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדפתי לרבינא: אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 כפי שאמרת, ש\u0003בכור לדבר אחד הוי\u0004 \u0005[הריהו]\u0006 \u0003בכור, תינח\u0004 \u0005[נניח,\u0006 מובן הדבר\u0005]\u0006 אם היה התנא למד \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003יוצא\u0004 תחילה \u0003זכר יוצא דופן, ו\u0004אחריו יצא \u0003זכר\u0004 \u0003דרך רחם\u0004 — \u0003דלא\u0004 \u0005[שאין\u0006 הוא\u0005]\u0006 \u0003קדוש\u0004 בבכורה, \u0003דאימעוט ליה\u0004 \u0005[שנתמעט לו]\u0006 מקרה זה מ\"בכור\", משום ש\u0003בכור לרחמים\u0004 (לרחם) \u0003איכא\u0004 \u0005[יש\u0006 כאן\u0005],\u0006 אבל \u0003בכור לזכרים\u0004 \u0003ליכא\u0004 \u0005[אין\u0006 כאן\u0005],\u0006 שנולד זכר לפניו.","\u0003אלא היכא\u0004 \u0005[במקום]\u0006 ש\u0003יצתה נקבה דרך דופן ו\u0004אחריה יצא \u0003זכר דרך רחם\u0004 — \u0003ליקדש\u0004 \u0005[שיקדש]\u0006 זכר זה בבכורה, \u0003דהא איכא\u0004 \u0005[שהרי יש\u0006 כאן\u0005]\u0006 \u0003בכור לזכרים ובכור לרחם! אלא מחוורתא\u0004 \u0005[מחוור,\u0006 ברור הדבר\u0005]\u0006 \u0003כ\u0004דברי \u0003אביי,\u0004 שבכור לדבר אחד אינו קרוי \"בכור\".","\u0003הלוקח\u0004 (הקונה) \u0003בהמה מן הגוי, ואינו יודע אם ביכרה,\u0004 כלומר, אם כבר ילדה ונפטרה מן הבכורה, או \u0003אם לא ביכרה,\u0004 ומשבאה לרשותו ילדה זכר. ר' ישמעאל אומר: אם היתה \u0003עז\u0004 זו \u0003בת שנתה\u0004 (בתוך שנתה הראשונה) כשילדה אצלו — הולד \u0003ודאי לכהן,\u0004 שוודאי לא ילדה קודם לכן. \u0003מכאן ואילך,\u0004 אם ילדה בגיל מבוגר יותר — הרי זה \u0003ספק.\u0004 אם קנה \u0003רחל\u0004 וילדה אצלו אפילו \u0003בת שתים\u0004 (בשנתה השניה) — הולד \u0003ודאי לכהן, מכאן ואילך\u0004 — \u0003ספק. פרה וחמור\u0004 עד \u0003בנות שלש\u0004 — \u0003ודאי לכהן, מכאן ואילך\u0004 — \u0003ספק.\u0004 \u0003אמר לו ר' עקיבא: אילו בוולד בלבד הבהמה נפטרת\u0004 מן הבכורה, הייתי אומר \u0003כדבריך,\u0004 שאין עז יולדת ולד גמור וחוזרת ויולדת עד סוף שנתה הראשונה. אלא אמרו חכמים: סימן הוולד בבהמה דקה — \u0003טינוף,\u0004 שיוצא מרחמה כעין לכלוך מן הרחם, ובזה היא נפטרת מן הבכורה, \u0003ובגסה\u0004 — כשיצאה \u0003שיליא\u0004 שהעובר מצוי בתוכה, \u0003ובאשה\u0004 — \u0003שפיר\u0004 (עובר) או \u0003שיליא.\u0004 וסימנים אלו יכולים להופיע לאחר שהרתה זמן קצר והפילה.","","","אלא \u0003זה הכלל: כל שידוע ש\u0004כבר \u0003ביכרה\u0004 קודם לכן — \u0003אין כאן לכהן כלום, וכל\u0004 שידוע \u0003ש\u0004עדיין \u0003לא ביכרה\u0004 — \u0003הרי זה לכהן, ואם ספק\u0004 הוא — \u0003יאכל במומו לבעלים.\u0004","שנינו במשנה כי לדעת ר' ישמעאל, הקונה עז וילדה אצלו בתוך שנתה הראשונה — בוודאי לא ילדה קודם לכן, והוא ודאי בכור. מכאן ואילך — הרי זה ספק בכור. ושואלים: \u0003מיכן ואילך\u0004 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003ספק\u0004 הוא? \u0003הלך\u0004 (לך) \u0003אחר רוב בהמות, ורוב בהמות מתעברות ויולדות\u0004 כבר \u0003בתוך שנתן\u0004 הראשונה \u0003נינהו\u0004 \u0005[הן],\u0006 \u0003והא ודאי מילד אוליד\u0004 \u0005[וזו,\u0006 איפוא, ודאי ילדה] ברשות הגוי, ופטורה! \u0003לימא\u0004 \u0005[האם לומר]\u0006 כי \u0003ר' ישמעאל כ\u0004שיטת \u0003ר' מאיר סבירא ליה\u0004 \u0005[סבור הוא],\u0006 \u0003דחייש למיעוטא\u0004 \u0005[שחושש למיעוט],\u0006 ואינו הולך אחר הרוב? ודוחים: \u0003אפילו תימא רבנן\u0004 \u0005[תאמר\u0006 שהוא כשיטת חכמים] שאין חוששים למיעוט, \u0003כי אזלי בתר רובא\u0004 \u0005[כאשר הולכים\u0006 חכמים \u0005אחר הרוב]\u0006 הרי זה \u0003ברובא דאיתיה קמן\u0004 \u0005[ברוב שישנו לפנינו],\u0006 \u0003כגון\u0004 שמצא חתיכת בשר במקום בו יש \u0003תשע חנויות\u0004 שמוכרות בשר כשר ועוד חנות אחת של טריפה, שמותר לאכול את הבשר, \u0003ו\u0004כן ב\u0003סנהדרין\u0004 שמכריעים את הדין לפי דעת רוב הדיינים המצויים לפנינו, \u0003אבל רובא דליתיה קמן\u0004 \u0005[רוב שאיננו לפנינו],\u0006 אלא שאנו יודעים על מציאותו באופן כללי, כגון שרוב בהמות יולדות בתוך שנתן — \u0003לא אזלי רבנן בתר רובא\u0004 \u0005[אין הולכים חכמים אחר הרוב].\u0006 ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 בענין \u0003קטן וקטנה, דרובא דליתיה קמן\u0004 \u0005[ש\u0006הוא \u0005רוב שאינו לפנינו],\u0006 \u0003וקאזלי רבנן בתר רובא\u0004 \u0005[והולכים החכמים אחר הרוב]!\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003קטן וקטנה\u0004 לפני בגרותם \u0003לא חולצין ולא מייבמין,\u0004 שאם מת אחיו של הקטן בלא זרע — אינו מייבם את אלמנתו (אפילו היתה גדולה) ואינה חולצת נעלו כאשר אינו מייבם. וכן אם היתה האלמנה קטנה — אינה מתייבמת ואינה חולצת (אפילו לגדול), אלו \u0003דברי ר' מאיר. אמרו לו\u0004 חכמים: \u0003יפה אמרת שאין חולצין\u0004, משום ש\u0003\"איש\" כתוב בפרשה\u0004 (\"ואם לא יחפוץ האיש לקחת את יבמתו\". דברים כה, ז) ולא קטן, \u0003ומקשינן\u0004 \u0005[ומקישים,\u0006 משווים \u0005אנו]\u0006 \u0003אשה\u0004 שנזכרה בפסוק זה \u0003לאיש,\u0004 ולכן אין חולצים לקטנה.","","","אבל \u0003מה טעם אין מייבמין? אמר להם:\u0004 ב\u0003קטן\u0004 — יש לחשוש \u0003שמא\u0004 כשיגדל \u0003ימצא סריס,\u0004 וכן \u0003קטנה\u0004 — \u0003שמא תמצא איילונית,\u0004 שאינה מסוגלת להוליד, ואלו אין בהם מצות יבום, מפני שאין מצוה זו קיימת אלא במי שיכול להוליד, \u0003ונמצאו פוגעין בערוה,\u0004 שהרי אשת אחיו אסורה על האדם, שלא במקום ייבום.","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 המתירים לייבם, מה הם אומרים? \u0003זיל בתר רובא\u0004 \u0005[לך אחר רוב]\u0006 ה\u0003קטנים, ורוב קטנים לאו\u0004 \u0005[לא]\u0006 \u0003סריסים נינהו\u0004 \u0005[הם],\u0006 וכן \u0003זיל בתר\u0004 \u0005[לך אחר]\u0006 רוב \u0003קטנות, ורוב קטנות לאו\u0004 \u0005[לא]\u0006 \u0003איילונית נינהו\u0004 \u0005[הן].\u0006 הרי שחכמים הולכים אחר הרוב, גם כשאינו מצוי לפנינו!","\u0003אלא אמר רבא:\u0004"],["\u0003מחוורתא\u0004 \u0005[מחוור\u0006 הדבר\u0005]\u0006 ש\u0003ר' ישמעאל כר' מאיר סבירא ליה\u0004 \u0005[סבור הוא],\u0006 \u0003דחייש למיעוטא\u0004 \u0005[שחושש למיעוט].\u0006 ולכן הקונה עז מן הגוי לאחר שנתה הראשונה, וילדה — הרי זה ספק בכור, שמא היא מן המיעוט שאינן יולדות בתוך שנתן.","\u0003רבינא אמר:\u0004 יש להסביר את דברי ר' ישמעאל אפילו תימא \u0005[תאמר]\u0006 שהוא סבור כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 ההולכים אחר הרוב ואינם חוששים למיעוט. שכן, \u0003כי אזלי רבנן בתר רובא\u0004 \u0005[כאשר הולכים חכמים אחר הרוב]\u0006 הרי זה \u0003ברובא דלא תלי\u0004 \u0005[ברוב שלא תלוי]\u0006 \u0003במעשה,\u0004 אלא שכך הוא טבעם של דברים, \u0003אבל רובא דתלי\u0004 \u0005[רוב שתלוי]\u0006 \u0003במעשה\u0004 — \u0003לא,\u0004 וכאן שהדבר תלוי בשאלה האם הבהמה נרבעה על ידי זכר — אין הולכים אחר הרוב.","הדיון שבמשנתנו הובא באופן מפורט יותר בברייתא. וכך \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 הלוקח מן הגוי \u0003עז,\u0004 וילדה זכר כשהיא \u0003בת שנתה\u0004 הראשונה — הולד \u0003ודאי לכהן,\u0004 מפני שודאי לא ילדה קודם לכן. אם ילדה \u0003מיכן ולהלן,\u0004 לאחר שמלאה לה שנה — \u0003ספק.\u0004 וכן קנה \u0003רחל\u0004 וילדה זכר \u0003בת שתים\u0004 (בשנתה השניה) — \u0003ודאי לכהן,\u0004 ילדה \u0003מיכן ולהלן\u0004 — \u0003ספק.\u0004 קנה \u0003פרה\u0004 וילדה זכר \u0003בת שלש\u0004 (בשנתה השלישית) — \u0003ודאי לכהן,\u0004 ילדה \u0003מיכן ולהלן\u0004 — \u0003ספק. חמורה\u0004 — דינה \u0003כפרה. ר' יוסי בר' יהודה אומר: חמורה בת ארבע שנים. עד כאן דברי ר' ישמעאל.\u0004","ו\u0003כשנאמרו דברים\u0004 אלו \u0003לפני ר' יהושע, אמר להן, צאו אמרו לו לר' ישמעאל: טעית! אילו בוולד בלבד הבהמה נפטרת\u0004 — \u0003היה כדבריך,\u0004 שאין עז יולדת ולד גמור וחוזרת ויולדת בשנתה הראשונה. \u0003אלא\u0004 שאמרו חכמים: \u0003סימן הוולד בבהמה דקה\u0004 — \u0003טינוף,\u0004 מעין לכלוך שיצא מרחמה, \u0003ובגסה\u0004 — \u0003שליא, ובאשה\u0004 — \u0003שפיר ושליא.\u0004","והוסיף ר' יהושע: זה מה שלימדוני חכמים, \u0003ו\u0004אולם \u0003אני אין אני אומר כן, אלא\u0004 לדעתי: \u0003עז שטינפה בת ששה\u0004 חדשים — \u0003יולדת\u0004 עוד פעם \u0003בתוך שנתה, רחל שטינפה בת שנתה\u0004 — \u0003יולדת בתוך שתים. אמר ר' עקיבא: אני לא באתי לידי מדה זו,\u0004 כלומר, איני יכול לדון באופן זה, \u0003אלא: כל שידוע ש\u0004כבר \u0003ביכרה\u0004 קודם לכן — \u0003אין כאן לכהן כלום, וכל שלא ביכרה\u0004 — \u0003הרי זו לכהן,\u0004 ואם היה זה \u0003ספק\u0004 — \u0003יאכל במומו לבעלים.\u0004 ודנים בפרטי הברייתא.","ותחילה שואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה חלוקים]\u0006 \u0003ר' ישמעאל ור' יהושע? לימא\u0004 \u0005[האם לומר]\u0006 כי מדובר במקרה שיצא ממנה טינוף, ו\u0003ב\u0004שאלה אם \u0003טינוף פוטר\u0004 מן הבכורה \u0003קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 \u0003ר' ישמעאל סבר\u0004 \u0005[סבור]\u0006 כי \u0003טינוף אינו פוטר,\u0004 שאינו סימן לולד, והנולד לאחר טינוף הריהו בכור גמור, \u0003ור' יהושע סבר\u0004 \u0005[סבור]\u0006 כי \u0003טינוף פוטר?\u0004","ומשיבים: אינו כן, אלא \u0003אי דחזינן\u0004 \u0005[אם רואים אנו]\u0006 שהיה \u0003טינוף\u0004 לפני לידת ולד זה — \u0003דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 ש\u0003טינוף פוטר. והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004שאלה אם \u0003חוששין ל\u0004כך שהיה \u0003טינוף\u0004 לפני לידת ולד זה \u0003קא מיפלגי\u0004 \u0005[חלוקים הם],\u0006 \u0003ר' ישמעאל סבר\u0004 \u0005[סבור]:\u0006 \u0003אין חוששין לטינוף,\u0004 ולכן ולד זה שנולד עכשיו הריהו בכור ודאי, ויינתן לכהן. \u0003ור' יהושע סבר \u0004\u0005[סבור]:\u0006 \u0003חוששין לטינוף,\u0004 ומספק יישאר הולד ביד הבעלים.","ושואלים: \u0003ו\u0004כי ר' ישמעאל \u0003לא חייש\u0004 \u0005[אינו חושש]\u0006 למיעוט? \u0003והאמר\u0004\u0005[והרי אמר]\u0006 \u0003רבא\u0004 לעיל, בדין עז שילדה לאחר שנתה הראשונה: מחוורתא \u0005[מחוור\u0006 הדבר\u0005]\u0006 ש\u0003ר' ישמעאל,\u0004 הסבור שהולד שילדה הוא ספק בכור, \u0003כר' מאיר סבירא ליה\u0004 \u0005[סבור הוא],\u0006 \u0003דחייש\u0004 \u0005[שחושש]\u0006 \u0003למיעוט,\u0004 שהרי רוב בהמות יולדות בשנתן הראשונה! ומשיבים: \u0003כי חייש\u0004 \u0005[כאשר\u0006 הוא \u0005חושש]\u0006 למיעוט — הרי זה \u0003לחומרא\u0004 \u0005[להחמיר],\u0006 ולחייב בבכורה מספק. אבל כאשר הליכה אחר המיעוט (וכגון מיעוט בהמות שמטנפות) מביאה \u0003לקולא\u0004 \u0005[להקל]\u0006 ולפטור מן הבכורה — \u0003לא חייש\u0004 \u0005[אינו חושש]\u0006 למיעוט.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 ר' ישמעאל \u0003בין לקולא בין לחומרא חייש\u0004 \u0005[בין להקל בין להחמיר חושש]\u0006 למיעוט, \u0003והכא\u0004 \u0005[וכאן]\u0006 שאינו חושש לטינוף, \u0003ב\u0004שאלה אם עז \u0003מטנפת וחוזרת ויולדת בתוך שנתה\u0004 הראשונה \u0003קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 ש\u0003ר' ישמעאל סבר\u0004 \u0005[סבור]:\u0006 אם עז \u0003מטנפת\u0004 — \u0003אינה חוזרת ויולדת בתוך שנתה, והא מדאוליד\u0004 \u0005[וזו מכיון שהולידה]\u0006 בתוך שנתה — \u0003ודאי לא טניף\u0004 \u0005[טינפה\u0006 קודם\u0005].\u0006 \u0003ור' יהושע סבר\u0004 \u0005[סבור]:\u0006 אם \u0003מטנפת\u0004 — \u0003חוזרת ויולדת בתוך שנתה,\u0004 וולד זה ספק בכור, שמא כבר טינפה וחזרה וילדה בתוך שנתה.","שנינו בברייתא, כי לאחר שהביא ר' יהושע מה שלמד מרבותיו, הוסיף ואמר: \u0003ואני איני אומר כן, אלא עז שטינפה בת ששה\u0004 — \u0003יולדת תוך שנתה, רחל שטינפה בת שנתה\u0004 — \u0003יולדת בתוך שתים.\u0004 ושואלים: \u0003מאי איכא\u0004 \u0003בין גמריה לסבריה\u0004 \u0005[מה\u0006 הבדל \u0005יש בין מה שקיבל\u0006 ר' יהושע \u0005במסורת לסברתו],\u0006 שהוא אומר \"אני איני אומר כן\"? והרי שניהם מסכימים שעז שטינפה יכולה ללדת בתוך שנתה הראשונה!","ומשיבים: חלוקים הם בעז \u0003שטינפה בסוף ששה,\u0004 לאחר שמלאו לה ששה חדשים, כשהתחיל החודש השביעי, וילדה בתוך שנתה, האם כבר נפטרה מתחילה מן הבכורה. \u0003ואיכא בינייהו\u0004 \u0005[ויש\u0006 ביניהם \u0005מחלוקת]\u0006 לגבי מה שאמר \u0003זעירי,\u0004 ש\u0003אמר זעירי: אין טינוף\u0004 נחשב כסימן ולד לפטור מן הבכורה, אם היא חוזרת ומתעברת \u0003פחות משלשים יום\u0004 לאחר הטינוף.","\u0003לגמריה\u0004 \u0005[ל\u0006פי \u0005המסורת שבידו]\u0006 — \u0003אית ליה\u0004 \u0005[יש לו,\u0006 הריהו סבור\u0005]\u0006 כדברי \u0003זעירי.\u0004 והואיל ובהמה דקה יולדת לאחר חמישה חודשי עיבור שלמים, נמצא שאם ילדה בתוך שנתה, משמע שנתעברה לפני תום החודש השביעי. והטינוף שאירע בתחילת אותו חודש (\"בסוף ששה\") היה פחות משלושים יום קודם שנתעברה, ואין זה טינוף הפוטר מן הבכורה. ואילו \u0003לסבריה\u0004 \u0005[ל\u0006פי \u0005סברתו]\u0006 של ר' יהושע עצמו — \u0003לית ליה\u0004 \u0005[אינו מקבל\u0006 את דברי\u0005]\u0006 \u0003זעירי,\u0004 אלא לדעתו יש טינוף בפחות משלושים יום. ולכן גם אם טינפה בתחילת החודש השביעי — יש אפשרות שתתעבר קודם שייגמר חודש זה, ותלד בתוך שנתה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 באופן אחר: \u0003דכולי עלמא אית להו\u0004 \u0005[הכל יש להם,\u0006 מקבלים את דברי\u0005]\u0006 \u0003זעירי,\u0004 ואם טינפה בתחילת החודש השביעי — אינה מתעברת קודם שיתחיל החודש השמיני, ולא נותרו לה חמישה חודשי עיבור מלאים עד סוף שנתה. והכא \u0005[וכאן]\u0006 \u0003ב\u0004שאלה האם בהמה \u0003יולדת למקוטעין\u0004 כלומר, שלא בחמישה חדשים מלאים, \u0003קמיפלגי\u0004 \u0005[חלוקים הם],\u0006"],["\u0003לגמריה\u0004 \u0005[\u0006\u0005ל\u0006פי \u0005מסורתו]\u0006 — \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 שבהמה \u0003יולדת למקוטעין,\u0004 ואם ילדה בתוך שנתה — סימן שנתעברה פחות משלושים יום לאחר שטינפה, ואין זה טינוף הפוטר מן הבכורה. \u0003לסבריה\u0004 \u0005[ל\u0006פי \u0005סברתו]\u0006 — \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 ש\u0003יולדת למקוטעין,\u0004 ויתכן שנתעברה שלושים יום לאחר שטינפה, אלא שעיבורה נמשך פחות מחמישה חודשים מלאים.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 לדעת הכל אין טינוף פחות משלושים יום, וגם \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 שהיא \u0003יולדת\u0004 למקוטעין. \u0003והכא\u0004 \u0005[וכאן]\u0006 מדובר באופן שנראה טינוף ביום הראשון של החודש השביעי, ו\u0003ב\u0004שאלה האם \u0003מקצת היום\u0004 נחשב \u0003ככולו קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 \u0003לסבריה\u0004 \u0005[ל\u0006פי \u0005סברתו]\u0006 — \u0003אמרינן\u0004 \u0005[אומרים אנו]:\u0006 \u0003מקצת היום ככולו,\u0004 וביום השלושים לטינוף יכולה להתעבר, ויתכן כי נשלמו חמישה חדשי העיבור בתוך שנתה. \u0003לגמריה\u0004 \u0005[ל\u0006פי \u0005מסורתו]\u0006 — \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003מקצת היום ככולו.\u0004 ולכן יכולה להתעבר רק למחרת, ולא נותרו חמישה חדשים מלאים עד לסוף השנה.","שנינו בברייתא ש\u0003אמר ר' עקיבא: אני לא באתי לידי מדה זו. אלא כל שידוע\u0004 שכבר ביכרה קודם לכן — אין כאן לכהן כלום, וכל שלא ביכרה — הרי זה לכהן. ואם ספק — ייאכל במומו לבעלים. ושואלים: \u0003מאי איכא\u0004 \u0005[מה הבדל בהלכה\u0006 \u0005יש]\u0006 \u0003בין ר' עקיבא לר' יהושע?\u0004","\u0003אמר ר' חנינא מסורא:\u0004 מדובר כאן בעז שהגיעה לידי ישראל כשהיא נותנת חלב, ובשאלה האם \u0003חלב פוטר\u0004 מן הבכורה \u0003איכא בינייהו\u0004 \u0005[יש\u0006 מחלוקת \u0005ביניהם],\u0006 האם דבר זה שהעז מניקה מוכיח שכבר ילדה, והולד שילדה עכשיו אינו בכור; \u0003ר' עקיבא סבר\u0004 \u0005[סבור]: חלב פוטר,\u0006 שהרי \u0003הלך אחר רוב בהמות, ורוב בהמות אין חולבות\u0004 (נותנות חלב) \u0003אלא אם כן יולדות\u0004 קודם. \u0003ור' יהושע סבר\u0004 \u0005[סבור]: הא איכא מיעוטא\u0006 \u0005[הרי יש מיעוט]\u0006 בהמות ש\u0003חולבות אף על פי שאין יולדות,\u0004 ויש לחשוש לכך, והריהו ספק בכור.","ושואלים: \u0003ומי חייש\u0004 \u0005[והאם חושש]\u0006 \u0003ר' יהושע למיעוט? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 מי שנפטר בעלה בלא בנים, ולא היו לו אחים ליבם אותה, והיא רוצה להינשא. אם \u0003היתה לה\u0004 לאישה זו \u0003חמותה\u0004 שיצאה למדינת הים — \u0003אינה חוששת\u0004 שמא ילדה חמותה אח לבעלה, והיא צריכה להמתין לו ליבום. אבל אם \u0003יצאה\u0004 חמותה \u0003מליאה,\u0004 כלומר, מעוברת — \u0003חוששת\u0004 האלמנה שמא ילדה חמותה בן. \u0003ר' יהושע אומר: אינה חוששת.\u0004","\u0003ואמרינן\u0004 \u0005[ואמרנו]:\u0006 \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהושע\u0004 שאינה חוששת? \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003רוב\u0004 הנשים ה\u0003מעוברות יולדות, ומיעוט\u0004 מהן \u0003מפילות, וכל היולדות\u0004 — מחצה מן הנולדים הם \u0003זכרים ומחצה נקבות.\u0004 אם כן, כשאנו באים לדון האם יש לחשוש שחמותה ילדה אח לבעלה, \u0003סמוך מיעוטא\u0004 \u0005[צרף את המיעוט]\u0006 של נשים מעוברות ש\u0003מפילות, למחצה\u0004 של \u0003נקבות\u0004 שנולדות, \u0003והוו להו זכרים מיעוטא\u0004 \u0005[ונמצאו הזכרים\u0006 הנולדים \u0005מיעוט],\u0006 \u0003ולמיעוטא לא חיישינן\u0004 \u0005[ולמיעוט אין אנו חוששים]!\u0006","\u0003אלא\u0004 צריכים לומר: \u0003איפוך\u0004 \u0005[הפוך]\u0006 את הסברות, ואמור שר' יהושע הוא זה שטוען שהחלב פוטר מן הבכורה, משום שאינו חושש למיעוט חולבות שלא ילדו, ור' עקיבא חושש למיעוט שחולבות אף שלא ילדו, והרי זה בכור מספק. ומוסיפים, \u0003והתניא\u0004 \u0005[וכן שנויה\u0006 ברייתא\u0005]\u0006 מפורשת כהסבר זה: \u0003חלב פוטר,\u0004 אלו \u0003דברי ר' יהושע, ר' עקיבא אומר: חלב אינו פוטר.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003גדייה שילדה שלש בנות\u0004 בבת אחת, \u0003וכל בנותיה ילדו\u0004 גם הן \u0003שלש שלש\u0004 — \u0003כולן,\u0004 הבנות ובנותיהן, \u0003נכנסות ל\u0004אותו \u0003דיר\u0004 כדי \u0003להתעשר,\u0004 להפריש אחת מהן למעשר בהמה. כלומר, ייתכן שייוולדו עשר הגדיות באותה שנה, שהרי אין מעשרים מבהמות שנולדו בשנה אחת על בהמות שנולדו בשנה אחרת. \u0003אמר ר' שמעון: אני ראיתי\u0004 גדיה כזו \u0003שעישרה\u0004 את בנותיה ובנות בנותיה בתוך שנתה, כלומר, שנולדו כולן בשנה אחת. ושואלים על סגנון הברייתא: אם התנא רוצה להביא דוגמה לעשר גדיות שנולדו בשנה אחת, \u0003למה לי למיתני\u0004 \u0005[לשנות]\u0006 שכל בנותיה של הגדיה ילדו \u0003שלש שלש?\u0004 די אם \u0003תוליד חד מינייהו תלת\u0004 \u0005[אחת מהן שלוש],\u0006 \u0003ואינך תרתי תרתי\u0004 \u0005[ו\u0006השתים \u0005האחרות\u0006 ילדו \u0005שתים שתים],\u0006 ובסך הכל עשר גדיות, שלוש בנות ושבע בנותיהן!","ומשיבים: \u0003איידי דאיכא חדא דלא סגיא\u0004 \u0005[מתוך שיש אחת שאי אפשר]\u0006 \u0003בלא\u0004 שתלד \u0003שלש, תנא כולהו\u0004 \u0005[שנה\u0006 לגבי \u0005כולן]\u0006 ש\u0003ילדו שלש שלש.\u0004 ושואלים: \u0003ולמה לי למיתני\u0004 \u0005[לשנות]\u0006 \u0003שלש כלל? לילדו כולהו תרתי\u0004 \u0005[שילדו כולן שתים],\u0006 \u0003ותיהדר איהי ותוליד בהדיהן\u0004 \u0005[ותחזור היא,\u0006 האם, \u0005ותוליד גם היא עוד גדייה אחת יחד איתן],\u0006 ונמצאו בסך הכל עשר! ומכאן משמע שלדעתו לא ייתכן שעז תלד פעמיים במשך שנה."],["ויש לשאול: \u0003לימא קסבר\u0004 \u0005[\u0006האם \u0005נאמר,\u0006 נלמד מכאן, ש\u0005הוא סבור]\u0006 גם שעז ש\u0003מטנפת אינה חוזרת ויולדת בתוך שנתה?\u0004 ודוחים: אין מכאן ראיה, שכן גם \u0003אם תימצי\u0004 \u0005[תוכל]\u0006 \u0003לומר\u0004 שעז ש\u0003מטנפת חוזרת ויולדת בתוך שנתה,\u0004 מכל מקום זו ה\u0003יולדת\u0004 ולד גמור — \u0003ודאי אינה חוזרת ויולדת בתוך שנתה.\u0004","שנינו בברייתא, \u0003אמר ר' שמעון: אני ראיתי גדייה\u0004 שעישרה בתוך שנתה. ושואלים: \u0003מאי איכא\u0004 \u0005[מה\u0006 הבדל \u0005יש]\u0006 \u0003בין תנא קמא לר' שמעון?\u0004 במה נחלקו? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל במקרה שהבנות טינפו בתחילת החודש השביעי ללידתן, כשהוא החודש השביעי לשנת מעשר בהמה שלהן. ונחלקו במה שאמר \u0003זעירי,\u0004 שאין טינוף פחות משלושים יום, כלומר, שאין בהמה מתעברת בתוך שלושים יום לטינופה.","\u0003תנא קמא אית ליה\u0004 \u0005[התנא הראשון יש לו],\u0006 סבור כדברי \u0003זעירי,\u0004 ולפיכך לדעתו אינן יכולות להתעבר אלא בתחילת החודש השמיני. ומאחר ועז יולדת רק לאחר חמישה חודשים שלמים — נמצא שאין הבנות יולדות את בנותיהן בתוך השנה, ואינן מתעשרות עמהן. ור' שמעון לית ליה \u0005[אין לו]\u0006 את דברי \u0003זעירי,\u0004 אינו סבור כן, ולפיכך לדעתו גם אם טינפו הבנות בתחילת החודש השביעי — יש אפשרות שיתעברו עד תום אותו חודש, וילדו בתוך השנה. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003דכולי עלמא אית להו\u0004 \u0005[הכל יש להם],\u0006 סבורים כדברי \u0003זעירי, והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004שאלה האם עז \u0003יולדת למקוטעין,\u0004 כלומר, בפחות מחמישה חודשים מלאים, \u0003קא מיפלגי\u0004 \u0005[חלוקים הם].\u0006 \u0003ל\u0004דעת \u0003תנא קמא\u0004 \u0005[התנא הראשון]\u0006 \u0003אינה יולדת למקוטעין,\u0004 ולכן אינן יכולות ללדת לפני סוף השנה, שהרי התעברו בתחילת החודש השמיני. ואילו \u0003ל\u0004דעת \u0003ר' שמעון\u0004 — \u0003יולדת\u0004 למקוטעין, וייתכן שתלדנה קודם שתיגמר השנה, אף על פי שהתעברו בתחילת החודש השמיני.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 מקבלים את דברי זעירי, שאין טינוף פחות משלושים יום, ולדעת הכל בהמה \u0003אינה יולדת למקוטעין, והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004שאלה האם \u0003מקצת היום ככולו קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 \u0003ל\u0004דעת \u0003תנא קמא\u0004 \u0005[התנא הראשון]\u0006 — \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003מקצת היום ככולו,\u0004 \u0003לר' שמעון\u0004 — \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003מקצת היום ככולו,\u0004 וייתכן כי ביום השלושים לטינוף כבר החל העיבור, ונתעברה בסוף החודש השביעי, וילדה ביום האחרון של שנתה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003דכולי עלמא אמרינן\u0004 \u0005[לדעת הכל אומרים אנו]\u0006 \u0003מקצת היום ככולו,\u0004 וגם לדעת התנא הראשון ייתכן שבהמה שטינפה בתחילת החודש השביעי תלד ביום האחרון של השנה. והכא \u0005[וכאן]\u0006 \u0003ב\u0004שאלה האם \u0003מחוסר זמן\u0004 (בהמה שלא מלאו לה שבעה ימים, ואינה ראויה להקרבה) נכנס לדיר יחד עם שאר הצאן כדי \u0003להתעשר קמיפלגי\u0004 \u0005[חלוקים הם],\u0006 לדעת התנא הראשון אינו נכנס לדיר להתעשר (וכדברי המשנה להלן נז,א), ולכן אין הבנות יכולות להתעשר עם ולדותיהן, שנולדו ביום האחרון של השנה. ולדעת ר' שמעון מחוסר זמן נכנס לדיר להתעשר, וניתן לעשרן יחד."],["\u0003והתניא\u0004 \u0005[ו\u0006אכן \u0005כן שנויה\u0006 ברייתא\u0005]\u0006 שכך סבור ר' שמעון: \u0003ר' שמעון בן יהודה אומר משום\u0004 (משמו של ) \u0003ר' שמעון: מחוסר זמן נכנס לדיר להתעשר. והרי הן\u0004 לענין זה \u0003כבכור, מה בכור קדוש לפני זמנו,\u0004 משעה שנולד לפני היום השמיני, \u0003וקרב לאחר זמנו\u0004 כלומר, מן היום השמיני והלאה — \u0003אף\u0004 במעשר, \u0003מחוסר זמן קדוש לפני זמנו, וקרב לאחר זמנו.\u0004","ושואלים: \u0003ואדיליף\u0004 \u0005[ועד ש\u0006ר' שמעון \u0005לומד]\u0006 דין מעשר \u0003מבכור, ניליף\u0004 \u0005[שילמד]\u0006 \u0003מקדשים,\u0004 שאין מקדישים מחוסר זמן! ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 ש\u0003מבכור הוה ליה למילף\u0004 \u0005[היה לו ללמוד],\u0006 \u0003שכן\u0004 יש בבכור ובמעשר צדדי דמיון שאין בקדשים: \u0003גואל, מום, תמורת, אכילה.\u0004 גואל — שלא ניתן לפדות בכור ומעשר גם כשנופל בהם מום, שלא כשאר קדשים, שנפדים במומם. מום — שקדושה חלה עליהם גם אם הם בעלי מום, שלא כשאר קדשים שהקדישם בעלי מום. תמורת — שאם המיר בכור ומעשר בבהמת חולין — אין התמורה קריבה, שלא כתמורת קדשים, שקריבה. אכילה — שבכור ומעשר בעלי מום נאכלים בלא פדייה, מה שאין כן שאר קדשים.","ומקשים: \u0003אדרבה\u0004 \u0005[גדולה מזו,\u0006 להיפך\u0005],\u0006 \u0003מקדשים הוה ליה למילף\u0004 \u0005[היה לו ללמוד]\u0006 למעשר, \u0003שכן\u0004 יש במעשר צדדי דמיון לקדשים שאין בבכור: זכר, קדוש, במתנות, פשוט. זכר — שמעשר ושאר קדשים באים זכר ונקבה, ובכור אינו אלא זכר. קדוש — שצריך להקדישם, אבל בכור קדוש מאליו. במתנות — שמעשר ושאר קדשים אינם מתנה לכהן כמו הבכור. פשוט — שמעשר ושאר קדשים באים מן הפשוטים, ולא מן הבכורות! \u0003אלא ר' שמעון\u0004 מגזירה שווה של לשון \u0003העברה העברה גמיר\u0004 \u0005[למד],\u0006 שבבכור נאמר: \"והעברת\" (שמות יג, יב), ובמעשר נאמר: \"כל אשר יעבור\" (ויקרא כז, לב).","במשנתנו הוזכר שטינוף הוא סימן לולד בבהמה דקה, ופוטר מן הבכורה. ושואלים: \u0003היכי דמי\u0004 \u0005[מה הוא בדיוק]\u0006 \u0003טינוף,\u0004 מתי הוא נחשב כסימן לולד? \u0003אמר רבא: כדאמרי רעותא\u0004 \u0005[כשאומרים הרועים]\u0006 \u0003דצלתא אצר חיותא\u0004 \u0005[שהטינוף\u0006 הוא ולד ש\u0005עצרה הבהמה\u0006 ברחמה\u0005].\u0006 \u0003ושמואל אמר: בעבועי דדמא\u0004 \u0005[\u0006כעין \u0005אבעבועות של דם].\u0006 ובענין זה מוסיפים: \u0003וצריך להראותו לחכם,\u0004 את הטינוף, שיאמר אם הוא סימן ולד. ושואלים: \u0003חכם מנא ידע\u0004 \u0005[מנין הוא יודע]?\u0006 וכי הוא מומחה לבהמות? \u0003אמר רב פפא:\u0004 הכוונה היא ל\u0003רועה חכם,\u0004 מומחה.","ועוד בענין זה, \u0003אמר רב חסדא: הרי אמרו יצירת הוולד באשה ארבעים יום,\u0004 שלאחר ארבעים ימי הריון, נחשב העובר לולד. ולפי זה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב חסדא:\u0004 יצירת הולד \u0003בבהמה בכמה\u0004 זמן היא? אמר ליה \u0005[לו]\u0006 \u0003רב פפא לאביי: לאו היינו\u0004 \u0005[האם אין זה]\u0006 מה שאמר \u0003זעירי,\u0004 ש\u0003אמר זעירי: אין טינוף\u0004 סימן לולד כשהוא \u0003פחות משלשים יום?\u0004 ודוחים: אין הכוונה שטינוף הוא ולד שנוצר לאחר שלושים ימי הריון, אלא \u0003ההוא לקבל איתמר\u0004 \u0005[נאמר],\u0006 שעד שלושים יום לאחר טינוף אינה מקבלת זכר ומתעברת. ואם נתעברה בתוך שלושים יום — אין הטינוף סימן ולד, והבא אחריו הוא בכור.","במשנה עסקנו בדינו של הלוקח בהמה מן הגוי ואינו יודע אם ביכרה. ושואלים: \u0003מצינו\u0004 (מצאנו) דין זה ב\u0003לוקח מגוי, לוקח מישראל מאי\u0004 \u0005[מה\u0006 דינו\u0005]?\u0006 \u0003אמר רב:\u0004 הנולד אצל הקונה הריהו \u0003בכור ודאי, דאם איתא דבכרה אישתבוחי הוה מישתבח ליה\u0004 \u0005[שאם אכן ביכרה, היה המוכר משתבח לו\u0006 בדבר זה\u0005].\u0006","\u0003ושמואל אמר: בכור ספק,\u0004 שמא \u0003סבר\u0004 \u0005[סבור]\u0006 המוכר: קונה זה, מאחר שאינו שואל אם כבר ביכרה, סימן ש\u0003לשחיטה קא בעי ליה\u0004 \u0005[צריך אותה],\u0006 ולא לולדות, ואינו טורח לספר לו על כך. \u0003ור' יוחנן אמר:\u0004 הולד שייולד הריהו \u0003חולין ודאין, מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 שכן \u0003אם איתא\u0004 \u0005[אכן]\u0006 המציאות היא ש\u0003לא בכרה, כיון דאיכא איסורא\u0004 \u0005[שיש איסור\u0006 בדבר\u0005],\u0006 שהרי חייב ליתן את הבכור לכהן, והוא אסור עליו בהנאה, בוודאי \u0003אודועי הוה מודע ליה\u0004 \u0005[היה מודיע לו]\u0006 על כך, כדי שלא ייכשל באיסור.","ומעירים, \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן\u0004 ש\u0003אמר\u0004 שאם לא הודיעו — הולד שתלד הריהו \u0003חולין.\u0004 שנינו במשנה שהמוכר לחבירו בהמה בימים מסויימים שאנשים רגילים לקנות בהם בהמה לשחיטה, צריך להודיעו אם מכר באותו יום את אמה או את בנה, כדי שלא יעבור הקונה על איסור שחיטת אותו ואת בנו ביום אחד. ועל כך שנו בברייתא: \u0003אם לא הודיעו\u0004 המוכר שמכר את האם — \u0003הולך\u0004 הקונה \u0003ושוחט, ואינו נמנע.\u0004 הרי שיכול הקונה לסמוך על שתיקת המוכר. ושואלים: \u0003לימא תיהוי תיובתא\u0004 \u0005[\u0006האם \u0005נאמר שתהא\u0006 זו \u0005קושיה]\u0006 על \u0003רב ושמואל\u0004 החולקים על ר' יוחנן? ודוחים: \u0003התם במוכר תליא מילתא\u0004 \u0005[שם,\u0006 לענין אותו ואת בנו, \u0005במוכר תלוי הדבר],\u0006 שהטילו עליו חכמים חובה להודיע, ואנו סומכים על כך שהוא מקיים את חובתו. \u0003הכא בלוקח תליא מילתא\u0004 \u0005[כאן,\u0006 בדין בכורה, \u0005בקונה תלוי הדבר],\u0006 שמוטל עליו לתת את בכורו לכהן, ולא במוכר, ואין ראיה ממה שלא הודיעו.","\u0003ר' אליעזר בן יעקב אומר: בהמה גסה ש\u0004עדיין לא ביכרה, ו\u0003שפעה חררת דם,\u0004 הפילה חתיכת דם — \u0003הרי\u0004 חררה זו תקבר, שמא יש שם ולד זכר שנתקלקלה צורתו, ונתקדש בבכורה כשיצא ממעי אמו, והוא אסור בהנאה כדין בכור. \u0003ופטורה\u0004 מאז \u0003מן הבכורה,\u0004 שהרי הנולד אחר כך אינו \"פטר רחם\".","על מה ששנינו במשנתנו שבהמה גסה ששפעה חררת דם — אותה חררה תיקבר, \u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא\u0004 בברייתא: חררת דם \u0003אינה מטמאה לא במגע ולא במשא,\u0004 שהנוגע בה או הנושא אותה אינו נטמא, כדין נוגע או נושא נבלת בהמה. ושואלים: \u0003ומאחר\u0004 ש\u0003אינה מטמאה לא במגע ולא במשא,\u0004 נמצא שאין חוששים שהיה שם ולד, ולפי זה \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003תקבר?\u0004"],["ומשיבים: \u0003כדי לפרסמה\u0004 את האם \u0003שנפטרה מן הבכורה,\u0004 שקוברים את ולדה הראשון.","ומקשים: \u0003למימרא דולד מעליא הוא\u0004 \u0005[\u0006מכאן יש \u0005לומר שולד מעולה,\u0006 גמור, \u0005הוא\u0006 נחשב\u0005],\u0006 שהרי הוא פוטרה מן הבכורה, \u0003ו\u0004אם כן \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003אין\u0004 הוא \u0003מטמא לא במגע ולא במשא? אמר ר' יוחנן: משום ביטול ברוב נגעו בה,\u0004 שהנפל שהיה שם ונימוק — בטל ברוב הדם שבחררה.","ומעירים: \u0003ואזדא\u0004 \u0005[והולך]\u0006 \u0003ר' יוחנן לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר ר' יוחנן: ר' אליעזר בן יעקב ור' שמעון אמרו דבר אחד,\u0004 הלכו בשיטה אחת. ומסבירים: \u0003ר' אליעזר בן יעקב\u0004 — \u0003הא דאמרן\u0004 \u0005[זו שאמרנו]\u0006 כלומר, במשנתנו, שנפל שנימוק בטל ברוב, ולכן אינו מטמא.","\u0003ר' שמעון מאי היא\u0004 \u0005[מה הוא\u0006 עניינו\u0005]?\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 אשה שהפילה שליא, ואין רואים ולד, אם \u0003השליא\u0004 מצויה \u0003בבית\u0004 — \u0003הבית טמא\u0004 בטומאת מת, ומה שנמצא בו באותה שעה נטמא. \u0003לא\u0004 משום \u0003שהשליא\u0004 היא עצמה \u0003ולד, אלא\u0004 משום \u0003שאין שליא בלא ולד,\u0004 אבל אין מבחינים בו. \u0003ר' שמעון אומר:\u0004 הבית טהור, מפני שה\u0003ולד נימוק עד שלא יצא,\u0004 וכשיוצא הריהו כבר בטל ברוב בדם הלידה.","\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במשנה במסכת אהלות: עובר שמת במעי אמו — מטמא את הבית משעה שהיא כורעת ללדת ונפתח רחמה, למרות שלא יצא. ומכל מקום \u0003אין לנפלים פתיחת הקבר\u0004 (הרחם), כלומר, אינם מטמאים באופן זה, \u0003עד שיעגילו ראש,\u0004 שראשם יהיה עגול וגדול \u0003כפיקה\u0004 (פקעת). ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003כפיקה? אמר רב הונא: כפיקה של\u0004 חוט \u0003צמר\u0004 שמכינים לאריגה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003חייא בר רב לרב הונא: רבי, פריש\u0004 \u0005[פרש]\u0006 באיזה פקעת אתה מדבר, \u0003של\u0004 חוט ה\u0003שתי, או של\u0004 חוט ה\u0003ערב,\u0004 שהוא עבה יותר, והפיקה שלו גדולה יותר?","\u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003פיקה של שתי,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר: של ערב. ר' אליעזר בר' צדוק אומר:\u0004 פתיחת הקבר היא \u0003משיראו טפיפיות\u0004 שבפתח רחמה. ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"טפיפיות\"? אמר רב יהודה אמר שמואל משום\u0004 (משמו של) \u0003ר' אליעזר בר' צדוק, כך היו מפרשין בירושלים: כפרידה שכורעת להטיל מימיה, ונראית\u0004 בפתח הרחם קמטי בשר כעין \u0003פיקה מתוך פיקה,\u0004 עיגול בתוך עיגול.","ובאותו ענין \u0003אמר רב הונא: שמעתי\u0004 שהוזכר שיעור של \u0003שתי פיקות\u0004 להלכה, \u0003אחת של שתי ואחת של ערב,\u0004 \u0003ואין לי לפרש\u0004 לאיזה ענין נאמרו הדברים. \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן: שלש פיקות שמעתי, אחת\u0004 — \u0003של שתי, ואחת\u0004 — \u0003של ערב, ואחת\u0004 — \u0003של פיקה גדולה של סקאין\u0004 (עושי שקים) שהיא גדולה יותר, \u0003ואין לי לפרש. כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003פירשה משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוחנן: של אשה,\u0004 ששנינו שאין לנפלים פתיחת קבר עד שיעגילו ראש כפיקה — \u0003כ\u0004פיקה של שתי. של בהמה — שעגול ראשו \u0003כ\u0004פיקה \u0003של ערב.\u0004","\u0003פיקה גדולה של סקאין,\u0004 עניינה \u0003כדתנן\u0004 \u0005[כמו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003גוש\u0004 עפר \u0003הבא מבית הפרס\u0004 (שדה שנחרש בה קבר) או \u0003מארץ העמים\u0004 (מחוצה לארץ), שגזרו חכמים טומאה על הנוגע בו או הנושא אותו, מחשש שהוא נושא או נוגע בעצם מן המת — \u0003שיעורו\u0004 (מידתו) \u0003כפיקה גדולה של סקאין, שהוא\u0004 \u0003כ\u0004שיעור \u0003חותם\u0004 שחותמים בו את פי \u0003המרצופין\u0004 (האמתחות), \u0003ו\u0004שיעור זה \u0003ישנו בצד העליון של מגופת\u0004 (מכסה) \u0003החבית הלחמית\u0004 (של בית לחם), ובגוש בגודל כזה יש חשש לעצם בשיעור שיש בה כדי לטמא.","\u0003אמר ריש לקיש משום ר' יהודה נשיאה: הלוקח ציר\u0004 (רוטב של דגים מלוחים שנכבשו במים) \u0003מעם הארץ,\u0004 שאינו מקפיד על טומאת אוכלים — \u0003משיקו במים,\u0004 מניח את הכלי עם הציר במקוה עד שיגעו מי המקוה בציר, כדרך שמטהרים מים שנטמאו, \u0003וטהור.\u0004","\u0003ממה נפשך\u0004 \u0005[מכל צד שתרצה\u0006 לדון על כך\u0005],\u0006 שכן \u0003אי מיא רובא נינהו\u0004 \u0005[אם המים\u0006 שבציר \u0005הם הרוב]\u0006 — \u0003כיון דעביד להו השקה טהרי להו\u0004 \u0005[כיון שעושה להם השקה\u0006 — \u0005נטהרו להם],\u0006 \u0003ואי רובא ציר נינהו\u0004 \u0005[ואם הרוב ציר\u0006 הדגים עצמו \u0005הוא,\u0006 הנוזל שפרש מגופם\u0005]\u0006 — \u0003ציר לא בר קבולי\u0004 \u0005[ראוי לקבל]\u0006 \u0003טומאה הוא.\u0004 אלא \u0003מאי איכא\u0004 \u0005[מה יש]\u0006 לחשוש — \u0003משום הנך מיעוטא דמיא\u0004 \u0005[אותו מיעוט של מים\u0006 טמאים\u0005]\u0006 שיש בתערובת — \u0003הנך בטלו להו ברובא\u0004 \u0005[אלה\u0006 כבר \u0005בטלו להם ברוב],\u0006 שהוא ציר הדגים, ולכן הציר כולו טהור.","\u0003אמר ר' ירמיה: לא שנו\u0004 פתרון זה של השקה \u0003אלא\u0004 כשמשתמש בציר \u0003לטבול בהן פיתו, אבל ל\u0004תת אותו במים שב\u0003קדירה\u0004 — \u0003לא,\u0004 משום שאם המים הם המיעוט, ובטלו ברוב הציר — לא הועילה להם כלל ההשקה לטהרם, וכששופכים את הציר כולו למים שבקדירה — \u0003מצא מין את מינו וניעור,\u0004 פגשו המים הטמאים שבציר את המים שבקדירה, והפכו המים לרוב, ומכיון שהמים שבציר מטמאים את שאר המים שבקדירה — נטמא התבשיל כולו. מסופר: \u0003יתיב\u0004 \u0005[יושב\u0006 היה\u0005]\u0006 \u0003רב דימי, וקאמר להא שמעתא\u0004 \u0005[ואומר היה את השמועה הזו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: וכי טומאה שבטלה חזרה וניעורה? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ואת לא תסברא\u0004 \u0005[ואתה לא תסבור\u0006 כן\u0005]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003סאה\u0004 (מדת נפח) של \u0003תרומה טמאה,\u0004 האסורה באכילה, \u0003שנפלה\u0004"],["\u0003למאה\u0004 סאים תבואה של \u0003חולין טהורין, ר' אליעזר אומר: תירום,\u0004 יוציא משם סאה אחת, איזו שתהיה, \u0003ותרקב,\u0004 כדין טומאה טמאה שאסורה באכילה, ודי בכך, \u0003שאני אומר: היא\u0004 (אותה) \u0003סאה שנפלה היא סאה שעלתה.\u0004","\u0003וחכמים אומרים: תעלה,\u0004 תיבטל אותה סאה במאה סאה חולין, ויש לכל התערובת דין חולין. \u0003ו\u0004מכל מקום מקפידים שלא להרטיב את התערובת במים כדי שלא לגרום טומאה לתערובת. ולכן אין ללוש אותה במים, מפני שהם מכשירים את החולין לקבל טומאה מן התרומה הטמאה, אלא \u0003תיאכל\u0004 כל התערובת \u0003ניקודים\u0004 כשהיא יבשה, \u0003או\u0004 שתיאכל בתור \u0003קליות,\u0004 שיקלו את גרגרי התבואה באש, \u0003או\u0004 ש\u0003תילוש במי פירות,\u0004 שאינם מכשירים לקבלת טומאה. \u0003או\u0004 אם רוצה ללוש במים — \u0003תתחלק לעיסות\u0004 קטנות, \u0003ובלבד\u0004 שיהא זה באופן \u0003שלא יהא במקום אחד\u0004 שיעור תרומה \u0003כביצה,\u0004 שהוא השיעור בו אוכל טמא מטמא אוכלים אחרים.","\u0003ותני עלה\u0004 \u0005[ושנויה\u0006 ברייתא \u0005עליה]\u0006 על משנה זו: \u0003אותן חולין\u0004 שנותרו לאחר שהרים מהם סאה"],["\u0003ל\u0004שיטת \u0003ר' אליעזר מה תהא עליהן\u0004 — \u0003יאכלו נקודין או קליות, או ילושו במי פירות, או תתחלק לעיסות, ובלבד שלא יהא כביצה במקום אחד. ואמר עולא: מה טעם\u0004 אמרו לנהוג כך בתערובת? והלא היא חולין! \u0003גזירה שמא\u0004 אם ננהג בתערובת זו כחולין טהורים לכל דבר, \u0003יביא קב\u0004 אדם \u0003חולין טמאים ממקום אחר, ו\u0004יערב אותם ב\u0003קב ועוד\u0004 משהו (מעט) \u0003ממין זה,\u0004 מתערובת זו, \u0003סבר\u0004 \u0005[כסבור\u0006 הוא\u0005]:\u0006 \u0003איבטלינהו ברובא\u0004 \u0005[אבטלנו ברוב]\u0006 את קב החולין הטמאים. \u0003ו\u0004אולם, \u0003כיון דאיכא האי משהו\u0004 \u0005[שיש משהו זה]\u0006 של תבואה טמאה בתוך התערובת, הרי למרות שנתבטל בתחילה, מכל מקום, כשהוא פוגש את החולין הטמאים — \u0003מצא מין את מינו וניעור,\u0004 ונמצא שאין רוב של חולין טהורים לבטל את הטמאים, ובא אותו אדם לידי מכשול של טומאת אוכלים. ומכאן מוכיח רב דימי כדברי ר' ירמיה, לגבי ציר הנלקח מעם הארץ, שאף שנתבטלו בו המים הטמאים, אם יתן את הציר לקדירה — ימצאו המים הטמאים את המים בקדירה, שהם מינם, ויחזרו לטומאתם הראשונה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: אין להוכיח לענייננו מדברי עולא, שכן גם \u0003אם\u0004 אתה אומר ש\u0003טומאה עוררת טומאה,\u0004 וכי יכול אתה ללמוד מכאן ש\u0003טהרה עוררת טומאה?\u0004 שהרי המים שבקדירה אינם טמאים, ואין כאן טומאה המוצאת טומאה!","ועוד \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 אביי ממה ששנינו: \u0003אפר כשר\u0004 של פרה אדומה, שהוא מטמא את הנושאו ואת הנוגע בו, \u0003שנתערב באפר מקלה,\u0004 סתם אפר — \u0003הולכין אחר הרוב לטמא\u0004 את הנושאו או את הנוגע בו, \u0003ואי רובא\u0004 \u0005[ואם הרוב]\u0006 \u0003אפר מקלה הוא\u0004 — \u0003לא מטמא\u0004 האפר. \u0003ואי אמרת\u0004 \u0005[ואם אתה אומר]\u0006 שגם כאשר המיעוט בטל ברוב — ה\u0003טומאה כמאן דאיתיה דמי\u0004 \u0005[כמו שהיא ישנה\u0006 מצויה, \u0005היא נחשבת],\u0006 \u0003נהי\u0004 \u0005[אם אמנם]\u0006 \u0003במגע לא מטמא\u0004 אפר זה, שהרי כאשר אדם נוגע באפר — ברוב הכשר הוא נוגע, מכל מקום \u0003לטמא\u0004 \u0005[שיטמא]\u0006 \u0003במשא,\u0004 שהרי כשהוא נושא את התערובת — יש בה אפר פרה שמטמא את הנושא!","השיב רב דימי: אין מכאן קושיה, שכן \u0003הא איתמר עלה\u0004 \u0005[הרי\u0006 כבר \u0005נאמר עליה],\u0006 על משנה זו, כפי שהצעת, \u0003אמר ר' יוסי בר' חנינא:\u0004 האפר המעורב \u0003טהור מלטמא במגע, אבל מטמא במשא.\u0004","חזר והקשה אביי, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב חסדא: נבילה בטילה בשחוטה,\u0004 אם נתערב בשר נבילה, שהיא מטמאה במשא ובמגע, ברוב של בשר בהמה שנשחטה כראוי, והיא טהורה — התערובת כולה טהורה, ומדוע? משום שזו תערובת של מין בשאינו מינו, שהולכים בה אחר הרוב. ואין השחוטה נחשבת כמינה של הנבילה, משום \u0003שאי אפשר לנבילה שתיעשה שחוטה.\u0004 ואם טומאה שבטלה ברוב עדיין נחשבת כמצויה, כיצד אמר רב חסדא באופן סתמי שהנבילה בטלה בשחוטה? \u0003נהי\u0004 \u0005[אם אמנם]\u0006 ש\u0003במגע לא מטמא,\u0004 שהנוגע בתערובת נוגע ברוב, מכל מקום \u0003לטמא\u0004 \u0005[שיטמא]\u0006 \u0003במשא,\u0004 שהרי הגביה את כל התערובת!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב דימי לאביי: \u0003אתון\u0004 \u0005[אתם]\u0006 \u0003ב\u0004שם \u0003רב חסדא מתניתו לה\u0004 \u0005[שונים אתם אותה],\u0006 הלכה זו, ולפי דבריו אכן יש קושיה. אבל \u0003אנן\u0004 \u0005[אנו]\u0006 \u0003ב\u0004דברי \u0003ר' חייא מתנינן לה\u0004 \u0005[שונים אותה],\u0006 שכך \u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא\u0004 בברייתא: \u0003נבילה ושחוטה בטילות זו בזו, ואיתמר עלה\u0004 \u0005[ונאמר עליה]\u0006 על ברייתא זו, \u0003אמר ר' יוסי בר' חנינא: טהור מלטמא במגע, אבל מטמא במשא.\u0004","חזר והקשה אביי: \u0003והא דתנן\u0004 \u0005[וזו ששנינו,\u0006 במשנתינו\u0005],\u0006 \u0003ר' אליעזר בן יעקב אומר: בהמה גסה ששפעה חררת\u0004 (חתיכת) \u0003דם\u0004 — \u0003הרי זו תקבר,\u0004 בגלל ולד שודאי מצוי בחררה, \u0003ונפטרה\u0004 הבהמה \u0003מן הבכורה. ותני\u0004 \u0005[ושנה]\u0006 על כך \u0003ר' חייא\u0004 בברייתא: חררה זו \u0003אינה מטמאה לא במגע ולא במשא.\u0004 ואם טומאה שבטלה ברוב עדיין נחשבת כמצויה, \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003דנהי\u0004 \u0005[שאם אמנם]\u0006 \u0003במגע לא\u0004 \u0005[אינו]\u0006 \u0003מטמא,\u0004 שהרי הולד אינו אלא מיעוט בחררה כולה, וכשהוא נוגע בה הריהו נוגע ברוב, מכל מקום תטמא במשא! אישתיק \u0005[שתק]\u0006 רב דימי. ושואלים: מדוע שתק? \u0003דלמא\u0004","\u0003ודאי שאני הכא\u0004 \u0005[שמא ודאי שונה כאן]\u0006 הדין, משום \u0003דהויא לה\u0004 \u0005[שהרי היא]\u0006 \u0003טומאה סרוחה,\u0004 שנבילה שנתקלקלה אינה מטמאת כלל! ואומרים: \u0003הניחא\u0004 \u0005[זה\u0006 אמנם \u0005נוח]\u0006 \u0003ל\u0004דעת \u0003בר פדא,\u0004 \u0003דאמר\u0004 \u0005[שאומר]:\u0006 נבילה מטמאת \u0003טומאה חמורה,\u0004 לטמא אדם הנושא אותה או נוגע בה, \u0003עד לגר,\u0004 כלומר, דכל עוד היא ראויה לאכילה לגר תושב, שמותר באכילת נבילה, ואם אינה ראויה למאכל אדם — שוב אינה מטמאה. \u0003ו\u0004אילו \u0003טומאה קלה,\u0004 כדין אוכל טמא, שמטמא אוכלים ומשקים בלבד, הריהי מטמאה \u0003עד\u0004 שלא תהיה ראויה אפילו \u0003ל\u0004מאכל \u0003כלב.\u0004 אם כן, חררה זו, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא חזיא\u0004 \u0005[אינה ראויה]\u0006 \u0003לגר,\u0004 אף שהיא ראויה לכלב, ולכן אינה מטמאה במשא. \u0003אלא ל\u0004דעת \u0003ר' יוחנן, דאמר\u0004 \u0005[שאומר]:\u0006"],["\u0003אחת זו ואחת זו,\u0004 גם טומאה חמורה וגם טומאה קלה יש בנבילה, \u0003עד\u0004 שאינה ראויה \u0003ל\u0004אכילת \u0003כלב,\u0004 מדוע אין החררה מטמאת במשא? \u0003הא חזיא\u0004 \u0005[הרי\u0006 היא \u0005ראויה]\u0006 \u0003לכלב!\u0004 ואומרים: אכן \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר.","\u0003גופא\u0004 \u0005[\u0006ודנים ל\u0005גופה]\u0006 של אותה מחלוקת שהבאנו, \u0003בר פדא אמר: טומאה חמורה,\u0004 לטמא במשא ובמגע, יש בנבילה \u0003עד\u0004 שלא תהיה ראויה עוד לאכילה \u0003לגר, וטומאה קלה,\u0004 טומאת אוכלים — \u0003עד\u0004 שלא תהיה ראויה \u0003לכלב. ור' יוחנן אמר: אחת זו ואחת זו\u0004 יש בה \u0003עד\u0004 שלא תהא ראויה \u0003לכלב.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003בר פדא?\u0004 ומשיבים, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לא תאכלו כל נבלה, לגר\u0004 אשר בשעריך תתננה ואכלה\" (דברים יד, כא), ומכאן למדנו כי דווקא נבילה \u0003הראויה\u0004 לאכילה \u0003לגר קרויה \"נבילה\"\u0004 כלומר, יש לה דין נבילה, לענין איסור אכילה ולענין טומאה, \u0003ושאינה ראויה לגר אינה קרויה \"נבילה\".\u0004","ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' יוחנן\u0005],\u0006 שאינו למד כן, מה הוא למד מכאן? ומשיבים: לדעתו הוזכרה כאן אכילת הגר כדי \u0003למעוטי היכא דהסריחה מעיקרא\u0004 \u0005[למעט מקום שהסריחה\u0006 הנבילה \u0005מתחילה],\u0006 שמעולם לא היתה ראויה למאכל הגר, שאין דין נבילה חל עליה. אבל אם היתה ראויה מתחילה לגר — אין טומאת נבילה מסתלקת ממנה עד שתיפסל מאכילת כלב. ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 בר פדא], מדוע הוא אינו דורש כך כתוב זה? ומשיבים: לדעתו, נבילה ש\u0003הסריחה מעיקרא\u0004 \u0005[מתחילתה]\u0006 \u0003לא צריכא קרא למעוטי\u0004 \u0005[אינה צריכה כתוב למעט אותה],\u0006 כי \u0003עפרא בעלמא הוא\u0004 \u0005[עפר בלבד היא]\u0006 ואינה נחשבת לכלום.","וביחס למה שהסברנו, כי גם לדעת ר' יוחנן, נבילה שהיתה סרוחה מתחילה — לא חל עליה כלל דין נבילה, מקשים: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005],\u0006 \u0003ר' אליעזר בן יעקב אומר: בהמה גסה ששפעה חררת דם\u0004 — \u0003הרי זו תקבר, ונפטרת מן הבכורה. ותני\u0004 \u0005[ו\u0006על כך \u0005שנה]\u0006 \u0003ר' חייא\u0004 בברייתא: \u0003אינה מטמאה לא במגע ולא במשא. ואמר ר' יוחנן: משום ביטול ברוב נגעו בה,\u0004 שהולד שנימוק נתבטל בדם שבחררה, שהוא הרוב, ולכן אינו מטמא טומאת נבילה.","ויש לשאול: \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע\u0005]\u0006 הוצרך לנמק זאת \u0003משום ביטול ברוב? תיפוק לי\u0004 \u0005[תצא לו]\u0006 הלכה זו משום \u0003דלא איתחזי\u0004 \u0005[ש\u0006הולד שבחררה \u0005לא היה ראוי]\u0006 \u0003כלל\u0004 מתחילתו לאכילת אדם, ואם כן לא חלה עליו טומאה! ומשיבים: \u0003הא נמי איתחזי מעיקרא אגב אימיה\u0004 \u0005[זה גם כן היה ראוי מתחילתו\u0006 לאכילה \u0005אגב אמו,\u0006 קודם שהפילה\u0005],\u0006 ומשום כך לא נסתלקה טומאה ממנו גם לאחר מכן.","ועוד בענין ביטול טומאה ברוב, \u0003תנן התם\u0004 \u0005[שנינו שם],\u0006 במשנה במסכת מכשירין, \u0003ר' אליעזר בן יעקב אומר: ציר\u0004 (של דגים מלוחים שנכבשו במים), שנלקח מעם הארץ החשוד על הטומאה, אלא שידוע לנו שהוא \u0003טהור,\u0004 משום שהמים שבו, שהם בחזקת טמאים, בטלים ברוב הציר, אם אירע \u0003שנפל לתוכו מים כל שהוא\u0004 — \u0003טמא,\u0004 לפי שעכשיו נמצא שיש בו רוב של מים טמאים. \u0003אמר רב נחמן אמר רבה בר אבוה, זאת אומרת: נחשדו עמי הארץ לערב מחצה\u0004 מים \u0003בציר,\u0004 ולכן די במים מועטים שנוספו כדי להפוך את המים לרוב הציר. ושואלים: \u0003ולמה לי\u0004 להסיק מכאן שנחשדו עמי הארץ לערב \u0003מחצה? אפילו\u0004 היו המים \u0003בציר\u0004 \u0005[פחות]\u0006 \u0003ממחצה, נמי\u0004 \u0005[גם כן]\u0006 יהיה הציר טמא. שהרי המים שהם מעט פחות ממחצה, \u0003והני\u0004 \u0005[ואותו]\u0006 \u0003משהו\u0004 מים שנפלו לציר, כשהם מצטרפים — \u0003הוה ליה פלגא\u0004 \u0005[הרי זה מחצה]\u0006 של הציר כולו, \u0003ופלגא לא בטיל\u0004 \u0005[ומחצה לא בטל]\u0006 במחצה!","ומתקנים, \u0003אימא\u0004 \u0005[אמור]:\u0006 אין כוונת רב נחמן לומר שאינם מערבים פחות ממחצה, אלא: \u0003עד מחצה\u0004 כלומר, קרוב למחצה. ומוסיפים, \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 יש לפרש את דברי רב נחמן כפשטם, שאם היו המים, עם המעט שנפל לתוכם, מחצה בציר — לא היה הציר טמא. וטעם הדבר הוא, כי \u0003טומאת עם הארץ,\u0004 שכל היוצא מתחת ידו בחזקת טמא, אינה אלא \u0003דרבנן\u0004 \u0005[מדברי חכמים],\u0006 וכן \u0003טומאת משקין\u0004 שהמים מטמאים — גם היא \u0003דרבנן\u0004 \u0005[מדברי חכמים].\u0006 ולכן יש לומר כי \u0003ברובא\u0004 \u0005[ברוב],\u0006 כאשר המים מצטרפים לרוב — \u0003גזרו רבנן\u0004 \u0005[חכמים]\u0006 טומאה על הציר. אבל, \u0003בפלגא ופלגא\u0004 \u0005[במחצה\u0006 מים \u0005ומחצה\u0006 ציר\u0005]\u0006 \u0003לא גזרו בה רבנן\u0004 \u0005[חכמים]\u0006 טומאה.","\u0003רבן שמעון בן גמליאל אומר: הלוקח\u0004 (הקונה) \u0003בהמה מניקה מן הגוי\u0004 — \u0003אין חוששין שמא\u0004 הולד שינק ממנה \u0003בנה של אחרת היה,\u0004 והיא עצמה עדיין לא ילדה. אלא כל ולד הולך אחר אימו, ובודאי בנה הוא, ולכן כל שתלד מעתה בודאי אינו בכור. \u0003נכנס לתוך עדרו וראה את המבכירות,\u0004 שילדו זה עתה בכור, \u0003מניקות, ו\u0004את \u0003שאינן מבכירות,\u0004 כלומר, אלו שכבר ילדו יותר מולד אחד, \u0003מניקות\u0004 — \u0003אין חוששין שמא בנה של זו\u0004 (המבכירה) \u0003בא לו אצל זו\u0004 (שאינה מבכירה), \u0003או שמא בנה של זו בא לו אצל זו,\u0004 ולכן כל אחד מן הולדות שבעדר הריהו ספק בכור. אלא אנו מניחים שכל ולד הולך אחר אימו, ולכן היונק מן המבכירה הריהו בכור ודאי, והיונק משאינה מבכירה — בודאי אינו בכור.","\u0003אמר רב נחמן משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: הלכתא בכוליה פירקין\u0004 \u0005[הלכה\u0006 היא כמו שנאמר \u0005בכל\u0006 המשניות של \u0005הפרק שלנו], וגם מה שלא נשנה בסתם, אלא בשמו של תנא מסויים,\u0006 \u0003בר מפלוגתא\u0004 \u0005[חוץ מאותם מקומות שיש בהם מחלוקת],\u0006 ששם צריך להכריע באופן שונה בכל מקום. \u0003אמר רב ששת, אמינא: כי ניים ושכיב רב אמר להא שמעתא\u0004 \u0005[אומר אני: כאשר נמנם ושכב רב אמר את השמועה הזו]\u0006 שהובאה בשמו, כלומר, לא דקדק בדבר. שכן \u0003אהייא\u0004 \u0005[על מה]\u0006 הוצרך לומר כלל זה, שהלכה כמשניות שבפרקנו? \u0003אילימא ארישא\u0004 \u0005[אם תאמר על\u0006 המשנה \u0005הראשונה],\u0006 במי שלוקח בהמה מן הגוי ואינו יודע אם ביכרה (לעיל יט, ב) — הרי \u0003מפליגי\u0004 \u0005[חלוקים]\u0006 בה \u0003ר' ישמעאל ור' עקיבא!\u0004","\u0003אלא\u0004 על דברי \u0003ר' אליעזר בן יעקב,\u0004 בענין בהמה גסה ששפעה חררת דם (לעיל כא, ב) — לא הוצרך לכך, שכן כלל בידינו הוא: \u0003משנת ר' אליעזר בן יעקב קב ונקי\u0004 כלומר, מעט, אבל נקי וברור כסולת, והלכה כמותו!","אלא אם על דברי \u0003רבן שמעון בן גמליאל\u0004 במשנתנו הדברים אמורים — הלוא \u0003מפלג פליג\u0004 \u0005[חולק\u0006 התנא\u0005] בברייתא\u0006 על הלכה זו! \u0003אלא\u0004 תאמר שכוונת רב ל\u0003ר' יוסי בן המשולם\u0004 במשנה הבאה (כד,ב) — \u0003הא\u0004 \u0005[הרי]\u0006 כבר \u0003אמר רב\u0004 דבר זה \u0003חדא זימנא\u0004 \u0005[פעם אחת],\u0006 ש\u0003אמר רב: הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כר' יוסי בן המשולם! אלא\u0004 תאמר שכוונתו למשנה בענין \u0003שער\u0004 בכור \u0003בעל מום\u0004 (להלן כה,ב) — הלוא \u0003מיפלג פליגי\u0004 \u0005[חלוקים]\u0006 בה \u0003עקביא בן מהללאל ורבנן\u0004 \u0005[וחכמים]!\u0006","ומשיבים: \u0003לעולם\u0004 כוונתו של רב לדבריו של \u0003רבן שמעון בן גמליאל\u0004 במשנתנו. \u0003והא קא משמע לן\u0004 \u0005[\u0006ודבר \u0005זה משמיע לנו]:\u0006 \u0003דברייתא לא פלוגתא היא\u0004 \u0005[ש\u0006מחלוקת \u0005שבברייתא לא\u0006 נחשבת \u0005למחלוקת],\u0006 ואין להתחשב בה.","ושואלים: \u0003וכיון\u0004 ש\u0003אמר רב: הלכתא בכוליה פירקין בר מפלוגתא\u0004 \u0005[הלכה בכל הפרק שלנו חוץ\u0006 ממקום שיש בו \u0005מחלוקת],\u0006"],["מה שאמר \u0003הלכה כר' יוסי בן המשולם, למה לי?\u0004 הרי דבריו נאמרו במשנה בלא חולק!","ומשיבים: \u0003אי אמר\u0004 \u0005[אילו היה אומר]\u0006 רב רק: \u0003הלכתא דכוליה פירקין\u0004 \u0005[הלכה של כל הפרק שלנו],\u0006 \u0003ולא אמר: הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כר' יוסי בן המשולם, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 מה שאמר שהלכה ככל הפרק — על דברי \u0003ר' יוסי בן המשולם קאי\u0004 \u0005[עומד,\u0006 מתייחס\u0005],\u0006 \u0003ומאי\u0004 \u0005[ומה\u0006 עניינו\u0005]\u0006 של \u0003\"בכוליה פירקין\"\u0004 \u0005[בכל פרקנו],\u0006 והרי אין מדובר אלא במשנה אחת — משום ש\u0003ר' יוסי תרתי\u0004 \u0005[שני\u0006 דברים\u0005]\u0006 \u0003אמר\u0004 במשנה הבאה. \u0003ו\u0004לפי דרך זו, אין רב מתכוון לפסוק כרבן שמעון גמליאל במשנתנו, משום שלדעתו \u0003פלוגתא דברייתא פלוגתא היא\u0004 [המחלוקת שנחלקו עליו \u0005בברייתא מחלוקת היא],\u0006 והלכה כדעת חכמים החולקים עליו.","לכך \u0003אשמעינן\u0004 \u0005[משמיע לנו]\u0006 רב באופן נפרד ש\u0003הלכה כר' יוסי\u0004 בן המשולם, כדי \u0003לאשמועינן\u0004 \u0005[להשמיע לנו]\u0006 שכשהוא אומר שהלכה ככל מה ששנינו בפרקנו — על דברי \u0003רבן שמעון בן גמליאל קאי\u0004 \u0005[הוא עומד,\u0006 מתייחס\u0005],\u0006 לומר שהלכה כמותו, \u0003ופלוגתא דברייתא לאו פלוגתא היא\u0004 \u0005[והמחלוקת ש\u0006נחלקו עליו \u0005בברייתא לא מחלוקת היא].\u0006","בדיון הקודם הוזכרה מחלוקת רבן שמעון בן גמליאל וחכמים שבברייתא. ואומרים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003ברייתא\u0004 זו שרמזנו לה? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003הלוקח\u0004 (הקונה) \u0003בהמה מניקה מן הגוי\u0004 — הולד \u0003הבא אחריו בכור מספק,\u0004 שמא זה שהניקה לא היה ולד שלה, \u0003מפני ש\u0004בהמה \u0003מרחמת\u0004 על ולד ומניקה אותו \u0003אף על פי שאינה יולדת\u0004 (שלא ילדה). \u0003רבן שמעון בן גמליאל אומר: דבר בחזקתו,\u0004 חזקה שבהמה זו שמניקה כבר ילדה, ואם כן הבא אחריו אינו בכור.","\u0003וכן היה רבן שמעון בן גמליאל אומר: הנכנס לתוך עדרו בלילה וראה כעשר\u0004 או \u0003כחמש עשרה\u0004 בהמות, מהן \u0003מבכירות\u0004 שעדיין לא ילדו, \u0003ו\u0004מהן \u0003שאינן מבכירות\u0004 שכבר ילדו ולד קודם לכן, ומצאן שכולן \u0003יולדות, למחר השכים ומצא\u0004 שה\u0003זכרים\u0004 שנולדו \u0003תלויות בשאין מבכירות,\u0004 כלומר, הולכים אחריהן ויונקים מהן, \u0003ונקבות תלויות במבכירות\u0004 — \u0003אינו חושש שמא בנה של זו\u0004 המבכירה, שהוא בכור, \u0003בא לו אצל זו\u0004 שאינה מבכירה, אלא זכר היונק משאינה מבכירה בודאי אינו בכור.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 שאלה ללומדים: \u0003\"דבר בחזקתו\" דקאמר\u0004 \u0005[שאומר]\u0006 \u0003רבן שמעון בן גמליאל,\u0004 מה משמעו? האם הכוונה היא ש\u0003אינה מרחמת\u0004 ומניקה ולד שאינה שלה \u0003אלא אם כן יולדת,\u0004 כלומר, אלא אם כבר ילדה ולד משלה, \u0003הא היכא דאוליד\u0004 \u0005[אבל במקום ש\u0006כבר \u0005ילדה]\u0006 — \u0003חיישינן לרחומי\u0004 \u0005[חוששים אנו שהיא מרחמת]\u0006 על ולד שאינו שלה. \u0003או דלמא\u0004 \u0005[שמא]\u0006 כוונתו באופן מוחלט: \u0003דידה מרחמא, דלא דידה לא מרחמא ליה\u0004 \u0005[\u0006על ולד \u0005שלה — מרחמת,\u0006 על ולד \u0005שאינו שלה — אינה מרחמת עליו]?\u0006","ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא ממנה\u0006 משאלה זו\u0005]?\u0006 מהי ההשלכה ההלכתית שלה? והרי בין לדרך זו ובין לדרך זו בוודאי כבר ילדה, ונפטרה מן הבכורה! ומשיבים: \u0003למלקא עלה\u0004 \u0005[ללקות עליה]\u0006 \u0003משום\u0004 איסור \u0003\"אותו ואת בנו לא\u0004 תשחטו ביום אחד\" (ויקרא כב, כח), אם שחט אותה ואת היונק ממנה באותו יום. \u0003אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 כי באופן מוחלט, \u0003דידה מרחמא, דלא דידה לא מרחמא\u0004 \u0005[\u0006על ולד \u0005שלה מרחמת,\u0006 על שאינו שלה אינה מרחמת] — הרי הוא \u0003לקי\u0004 \u0005[לוקה]\u0006 מפני שהוא בודאי בנה. \u0003ואי אמרת דלא דידה נמי מרחמא\u0004 \u0005[ואם אתה אומר\u0006 שהיולדת, על ולד \u0005שאינו שלה גם כן מרחמת]\u0006 — \u0003לא לקי\u0004 \u0005[אינו לוקה],\u0006 שמא אינו בנה.","אם כן, \u0003מאי\u0004 \u0005[מה\u0006 הפתרון\u0005]?\u0006 ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו במשנתנו, \u0003רבן שמעון בן גמליאל אומר: הלוקח בהמה\u0004 מניקה \u0003מן הגוי\u0004 — \u0003אינו חושש שמא בנה של אחרת היה.\u0004 הרי דעתו מפורשת, שכל בהמה אינה מרחמת על ולד שאינו שלה, גם אם כבר ילדה! ודוחים: מי קתני \u0005[האם הוא שונה]\u0006 \"אינו חושש שמא בנה של אחרת \u0003הוא\"?\u0004 הלוא \"אינו חושש שמא בנה של אחרת \u0003היה\" קתני\u0004 \u0005[הוא שונה],\u0006 ויש לפרש כי \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003אינו חושש שמא\u0004 זה \u0003בנה של אחרת, אלא אם כן היה לה ולד מעיקרא\u0004 \u0005[מתחילה].\u0006 ואם כן אין להוכיח מכאן.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו בהמשך משנתנו: \u0003נכנס בתוך עדרו וראה את המבכירות מניקות, ואת שאינן מבכירות מניקות\u0004 — \u0003אינו חושש שמא בנה של זו בא לו אצל זו, או שמא בנה של זו בא לו אצל זו.\u0004 ואם בהמה שילדה מרחמת על ולד שאינו שלה, אמאי \u0005[מדוע]\u0006 אינו חושש?","\u0003ליחוש דלמא רחומי רחים\u0004 \u0005[נחשוש שמא\u0006 ריחמה על ולד שאינו שלה\u0005],\u0006 והוא היונק ממנה! אלא מכאן שגם בהמה שילדה אינה מרחמת על ולד שאינו שלה. ודוחים: אין מכאן ראיה, משום שגם אם נאמר שבדרך כלל מרחמת על ולד שאינו שלה — \u0003במקום דידה לא שבקא דידה ומרחמא דלא דידה\u0004 \u0005[במקום\u0006 שיש ולד \u0005שלה, אינה מניחה את שלה ומרחמת\u0006 על \u0005שאינו שלה].\u0006","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה שאמר רבן שמעון בן גמליאל בברייתא, שהלוקח בהמה מניקה מן הגוי אינו חושש שמא בנה של אחרת הוא, משום ש\u0003דבר בחזקתו כו'.\u0004 ולאחר מכן הובא דין נוסף בשמו, בלשון \"וכן היה רבן שמעון בן גמליאל אומר\", שמבכירות ושאינן מבכירות שילדו יחד, אינו חושש שמא בנה של זו בא לו אצל זו ולהיפך. \u0003מאי לאו\u0004 \u0003רישא דומיא דסיפא\u0004 \u0005[האם אין\u0006 הכוונה שהדין שאמר \u0005בתחילה דומה\u0006 לדין \u0005שבסוף]?\u0006 \u0003מה סיפא ודאי דידה\u0004 \u0005[מה בסוף,\u0006 הולד שהיא מניקה הוא ודאי שלה], שהרי הוא משתמש בלשון \"אינו חושש\", לפי שאינה מניחה את שלה ומרחמת על שאינו שלה — \u0003אף רישא ודאי דידה\u0004 \u0005[אף בתחילה,\u0006 הריהו \u0005ודאי שלה],\u0006 למרות שייתכן שכבר ילדה. ומכאן שהוא מניח שגם זו שילדה אינה מרחמת על ולד שאינו שלה!","ודוחים: \u0003מידי איריא\u0004 \u0005[כלום שייכים\u0006 הדברים\u0005]?\u0006 יש לומר כי \u0003האי כדאיתא, והאי כדאיתא\u0004 \u0005[זה כמו שהוא, וזה כמו שהוא],\u0006 במקום שולדה נמצא — ודאי שאינה מניקה ולד שאינו שלה, אבל במקום שאין לפנינו אלא ולד אחד שיונק ממנה — הרי זה רק ספק, שמא איננו בנה. ושואלים: \u0003ו\u0004אם אין שני המקרים זהים, \u0003מאי\u0004 \u0005[מהו]\u0006 שנאמר לפני הדין השני \u0003\"וכן\",\u0004 המלמד שדין אחד הוא? ומשיבים: דבר זה נאמר \u0003אפטורה דבכורה\u0004 \u0005[על הפטור של בכורה],\u0006 בו עוסקת ברייתא זו, שהואיל ובהמה זו מניקה — בוודאי כבר ילדה.","\u0003אמר רבה בר בר חנה אמר ר' יוחנן: ראה חזיר שכרוך אחר רחל\u0004 ויונק ממנה — \u0003פטורה\u0004 אותה רחל \u0003מן הבכורה,\u0004 לכשתלד זכר לאחר מכן. \u0003ו\u0004מכל מקום \u0003אסור\u0004 חזיר זה \u0003באכילה,\u0004 שאין אומרים בוודאות שהוא ולדה של רחל זו \u0003\"עד יבא ויורה צדק לכם\"\u0004 (הושע י, יב), כלומר, עד שיבוא אליהו ויאמר לנו מה דינו.","ותמהים: מה שאמר ר' יוחנן ש\u0003פטור מן הבכורה כמאן\u0004 \u0005[כ\u0006דעת \u0005מי\u0006 הוא אומר\u0005]\u0006 — \u0003כרבן שמעון בן גמליאל,\u0004 הסבור במשנתנו, שהיונק מן הבהמה — בחזקת בנה הוא. \u0003ו\u0004אילו מה שהוא אומר שהוא \u0003אסור באכילה,\u0004 הרי זה \u0003כרבנן\u0004 \u0005[כ\u0006דעת \u0005חכמים]\u0006 החולקים עליו, וסבורים שייתכן שהיא מניקה ולד שאינו שלה!","\u0003ותו\u0004 \u0005[ועוד]\u0006 יש לתמוה: \u0003אי כרבנן\u0004 \u0005[אם\u0006 ר' יוחנן פוסק \u0005כ\u0006דעת \u0005חכמים],\u0006 שרק יש לחשוש שמא הוא בנה, אבל ייתכן שאינו בנה — \u0003מאי\u0004 \u0005[מה\u0006 עניינו] של \u0003\"עד יבא ויורה צדק לכם\"\u0004 שמשמעו הוראת דין? הרי רק לברר את המציאות אנו צריכים, לדעת האם ולדה הוא, ואם כן \u0003\"עד שיודע לך דבר\" מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 לומר!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003מספקא ליה\u0004 \u0005[מסופק לו]\u0006 לר' יוחנן \u0003אי\u0004 \u0005[אם]\u0006 \u0003הלכה כרבן שמעון בן גמליאל אי כרבנן\u0004 \u0005[אם כחכמים],\u0006 ולכן הוצרך לאליהו שיכריע במחלוקת זו — על כך יש להקשות: \u0003אי מספקא ליה\u0004 \u0005[אם מסופק לו]\u0006 שמא אין הלכה כרבן שמעון בן גמליאל — \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003פטורה מן הבכורה?\u0004 והרי זה ספק! \u0003ותו\u0004 \u0005[ועוד]\u0006 יש להקשות: \u0003מי מספקא ליה\u0004 \u0005[האם\u0006 באמת \u0005מסופק לו\u0006 כמי ההלכה\u0005]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבה בר בר חנה אמר ר' יוחנן: כל מקום ששנה רבן שמעון בן גמליאל\u0004 הלכה \u0003במשנתינו\u0004 — \u0003הלכה כמותו, חוץ מ\u0004שלושה מקרים: בדין \u0003ערב, ו\u0004בדין \u0003צידן, ו\u0004בדין \u0003ראיה אחרונה!\u0004","ומשיבים: \u0003לעולם\u0004 יש לומר ש\u0003פשיטא ליה\u0004 \u0005[פשוט לו]\u0006 לר' יוחנן ש\u0003הלכה כרבן שמעון בן גמליאל,\u0004 שבהמה מניקה בוודאי כבר ילדה, ופטורה מן הבכורה. \u0003מיהו מספקא ליה\u0004 \u0005[מכל מקום מסופק לו]\u0006 לר' יוחנן \u0003אי\u0004 \u0003סבר\u0004 \u0005[אם סבור] רבן שמעון בן גמליאל\u0006 שבהמה ש\u0003יולדת\u0004 (שילדה) \u0003מרחמת\u0004 על ולד שאינו שלה, וייתכן איפוא שכבר ילדה, וחזיר זה אינו בנה, ואם כן הריהו אסור באכילה מספק. \u0003או\u0004 האם סבור רבן שמעון בן גמליאל שכל בהמה, וגם בהמה שכבר ילדה, \u0003אינה מרחמת\u0004 על ולד שאינו שלה. ולפי זה החזיר היונק ממנה בוודאי בנה הוא, ומותר באכילה. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003עד דאשמעינן\u0004 \u0005[שהוא משמיע לנו]\u0006 דין זה ב\u0003חזיר\u0004 — \u0003לישמעינן\u0004 \u0005[שישמיע לנו]\u0006 דין זה ב\u0003טלה\u0004 הכרוך אחר רחל, \u0003ו\u0004לא לענין איסור אכילה, אלא \u0003למילקי עליה\u0004 \u0005[\u0006לענין \u0005ללקות עליו]\u0006 \u0003משום \"אותו ואת בנו\",\u0004 שאם שחט שניהם ביום אחד — הריהו פטור משום ספק, שמא לדעת רבן שמעון בן גמליאל בהמה שילדה מרחמת על ולד שאינו שלה!","ומשיבים: \u0003חזיר איצטריכא ליה\u0004 \u0005[הוצרך לו]\u0006 להשמיענו, משום \u0003דאי אשמעינן\u0004 \u0005[שאם\u0006 היה \u0005משמיע לנו]\u0006 דין זה ב\u0003טלה, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 גם \u0003אם תמצא\u0004 \u0005[תוכל]\u0006 \u0003לומר דסבר\u0004 \u0005[ש\u0006רבן שמעון בן גמליאל \u0005סבור]\u0006 כי \u0003יולדת מרחמא\u0004 \u0005[מרחמת]\u0006 על ולד שאינו שלה, ויש ספק אם הוא בנה — אין זה אלא ולד שהוא בן \u0003מינה,\u0004 אבל ולד שהוא \u0003לא\u0004 בן \u0003מינה\u0004 — \u0003לא,\u0004 ואם כן, חזיר זה שיונק ממנה בוודאי בנה הוא, שאם לא כן לא היתה מניקה אותו. לכך \u0003אשמעינן\u0004 \u0005[משמיע לנו]\u0006 \u0003חזיר,\u0004 כדי לומר שיולדת \u0003מרחמת\u0004 על ולד שאינו שלה, \u0003ואפילו\u0004 במקרה \u0003דלאו מינה נמי\u0004 \u0005[ש\u0006הולד \u0005אינו מינה גם כן].\u0006 והוא אסור באכילה, מפני \u0003דאיכא למימר דלמא מרחמא\u0004 \u0005[שיש לומר שמא מרחמת]\u0006 עליו למרות שאינו שלה, אלא הוא חזיר ממש.","ומוסיפים: \u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר ר' יוחנן, בעי\u0004 \u0005[שאל]\u0006"],["\u0003אחאי בריבי\u0004 \u0005[הגדול]:\u0006 \u0003ראה חזיר שכרוך אחר רחל, מהו\u0004 דינו? ויש לשאול: \u0003מאי קמיבעיא ליה\u0004 \u0005[מה\u0006 שאלה \u0005נשאלה לו]\u0006 לר' אחאי? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003ל\u0004ענין \u0003בכורה, וקמיבעיא ליה אי הלכתא\u0004 \u0005[ונסתפק לו אם הלכה]\u0006 \u0003כרבן שמעון בן גמליאל\u0004 הפוטר מן הבכורה, משום שלדעתו בודאי כבר ילדה, \u0003אי הלכתא כרבנן\u0004 \u0005[אם הלכה כחכמים],\u0006 הסבורים שבהמה מרחמת ומניקה גם אם אינה יולדת, וספק הוא אם ילדה כבר — \u0003תיבעי ליה\u0004 \u0005[תישאל לו\u0006 השאלה\u0005]\u0006 לגבי \u0003טלה\u0004 שכרוך אחרי רחל!","ואומרים: \u0003כי קמיבעיא ליה\u0004 \u0005[כאשר נשאלה לו\u0006 השאלה\u0005]\u0006 הרי זה בשני דברים, \u0003ל\u0004פוטרה מן ה\u0003בכורה ואליבא דרבנן\u0004 \u0005[ועל פי\u0006 שיטת \u0005חכמים],\u0006 ו\u0003ל\u0004ענין איסור \u0003אכילה\u0004 של חזיר זה \u0003ואליבא\u0004 \u0005[ועל פי\u0006 שיטת\u0005]\u0006 \u0003רבן שמעון בן גמליאל.\u0004","ומפרטים: \u0003ל\u0004פוטרה מן \u0003בכורה ואפילו לרבנן דאמרי מרחמא\u0004 \u0005[ל\u0006דעת \u0005חכמים שאומרים\u0006 שבהמה \u0005מרחמת]\u0006 על ולד שאינו שלה, שכן יש לומר: \u0003כי מרחמא דמינה\u0004 \u0005[כאשר\u0006 היא \u0005מרחמת,\u0006 הרי זה על ולד \u0005שהוא בן\u0006 \u0005מינה],\u0006 אבל ולד ש\u0003לא\u0004 בן מינה — \u0003לא,\u0004 אינה מרחמת, ואם חזיר יונק ממנה הרי זו הוכחה שבנה הוא, ונפטרה מן הבכורה. \u0003או דלמא\u0004 \u0005[שמא]\u0006 לדעת חכמים, גם ולד ש\u0003לא\u0004 בן \u0003מינה נמי מרחמא\u0004 \u0005[גם כן מרחמת],\u0006 ועדיין ספק הוא — שמא לא ביכרה עדיין, ולא נפטרה מן הבכורה.","וכן נשאלה השאלה \u0003ל\u0004ענין איסור \u0003אכילה\u0004 של חזיר זה \u0003ואפילו ל\u0004דעת \u0003רבן שמעון בן גמליאל,\u0004 הסבור שהיונק מן הבהמה הרי זה בחזקת בנה. שכן גם \u0003אם תמצא לומר סבר\u0004 \u0005[\u0006שהוא \u0005סבור]\u0006 כי בהמה \u0003יולדת\u0004 (שילדה כבר) \u0003מרחמא\u0004 \u0005[מרחמת]\u0006 על ולד שאינו שלה — הרי זה על ולד שהוא בן \u0003מינה,\u0004 אבל ולד \u0003דלאו מינה\u0004 \u0005[שאינו\u0006 בן \u0005מינה]\u0006 — \u0003לא,\u0004 ומאחר שחזיר זה יונק מן הרחל — בוודאי בנה הוא, ומותר באכילה. \u0003או דלמא\u0004 \u0005[שמא]\u0006 הוא סבור כי בהמה שילדה, על ולד \u0003דלאו\u0004 \u0005[שאינו]\u0006 בן \u0003מינה נמי מרחמא\u0004 \u0005[גם כן מרחמת],\u0006 וגם במקרה זה יש ספק, והוא אסור באכילה. שאלה זו לא נפתרה, ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד\u0006 השאלה במקומה\u0005].\u0006","\u0003ר' יוסי בן המשולם אומר: השוחט את הבכור,\u0004 והוא צריך לפנות את מקום השחיטה משיער, כדי שיוכל לשחוט כראוי, אלא שנאסר מן התורה לגזוז את הבכור, שנאמר: \"ולא תגוז בכור צאנך\" (דברים טו, יט), כיצד יעשה? עושה מקום בקופיץ (סכין גדולה) \u0003מיכן ומיכן,\u0004 מצידי מקום השחיטה, \u0003ו\u0004אף שבכך הוא \u0003תולש את השער.\u0004 \u0003ובלבד שלא יזיזנו\u0004 את השיער ממקומו, אלא יישאר מעורב עם שאר השיער, כדי שלא ייראה הדבר כגזיזה. \u0003וכן תולש\u0004 אדם \u0003את השער\u0004 של הבכור, כדי שיוכל החכם \u0003לראות מקום מום\u0004 שיש בו, ולהתירו בשחיטה מחוץ למקדש, ואין הדבר אסור משום גזיזת בהמת קדשים.","\u0003אמר רב: הלכה כר' יוסי בן המשולם.\u0004 ובענין זה מסופר, \u0003בעו מיניה\u0004 \u0005[שאלו ממנו]\u0006 \u0003מרב הונא: כנגדו ביום טוב, מהו\u0004 הדין? האם כשרצונו לשחוט בהמה ביום טוב לצורך החג, מותר לו גם כן לפנות את מקום השחיטה משיער, אף שבכך הוא תולש את השיער? וצדדי השאלה: האם \u0003טעמא\u0004 \u0005[הטעם]\u0006 של \u0003ר' יוסי בן המשולם\u0004 שהוא מתיר לעשות כן בבכור, הרי זה \u0003משום דקסבר\u0004 \u0005[שהוא סבור]\u0006 ש\u0003תולש לאו היינו\u0004 \u0005[איננו]\u0006 בכלל \u0003גוזז,\u0004 ולא אסרה התורה דבר זה בקדשים, \u0003ו\u0004מכל מקום ביום טוב אסור הדבר, משום \u0003דהוה ליה\u0004 \u0005[שהרי הוא]\u0006 \u0003עוקר דבר מ\u0004מקום \u0003גידולו,\u0004 כמו קוצר, ודבר זה אסור ביום טוב. \u0003או דלמא\u0004 \u0005[שמא],\u0006","\u0003בעלמא סבר\u0004 \u0005[בכלל סבור] ר' יוסי בן המשולם\u0006 ש\u0003תולש היינו\u0004 \u0005[הריהו]\u0006 \u0003גוזז\u0004 שנאסר בתורה, \u0003והיינו טעמא דשרי\u0004 \u0005[וזה הטעם ש\u0006הוא \u0005מתיר]\u0006 במשנתנו לפנות את השיער בקופיץ — משום \u0003דהוה ליה\u0004 \u0005[שהריהו]\u0006 \u0003דבר שאין מתכוין,\u0004 שאינו מתכוון לתלוש את השיער, אלא רק להזיזו ממקומו. \u0003ו\u0004אם כן, גם ביום טוב מותר הדבר, שהרי אף \u0003ביום טוב, דבר שאין מתכוין\u0004 — \u0003מותר?\u0004","\u0003אמר להו\u0004 \u0005[להם]\u0006 רב הונא: \u0003זילו שיילוה\u0004 \u0005[לכו שאלו]\u0006 שאלה זו \u0003לרב חננאל,\u0004 שהיה תלמידו של רב והיה שונה הלכות משמו, \u0003אי אמר\u0004 \u0005[אם יאמר\u0006 לכם\u0005]\u0006 ש\u0003הלכה כר' יוסי בן המשולם, איפשוט לכו\u0004 \u0005[אפתור לכם]\u0006 את שאלתכם לגבי יום טוב. \u0003אתו שיילוה\u0004 \u0005[הלכו שאלו]\u0006 את רב חננאל, \u0003אמר להו\u0004 \u0005[להם],\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב: הלכה כר' יוסי בן המשולם. אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003רב הונא\u0004 וסיפרו לו, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003כנגדו,\u0004 באותו אופן \u0003ביום טוב מותר\u0004 הדבר. ומוסיפים, \u0003איתמר נמי\u0004 \u0005[\u0006דבר זה \u0005נאמר גם כן]\u0006 במפורש בשם רב, שכך \u0003אמר רב חנניה בר שלמיא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: כנגדו ביום טוב\u0004"],["\u0003מותר.\u0004 ואם כן, טעם הדבר — כמבואר לעיל, משום שאינו מתכוון לתלוש.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רב הכי\u0004 \u0005[כך]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב חייא בר אשי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: מסוכריא דנזייתא\u0004 \u0005[פקק של\u0006 נקב \u0005חבית]\u0006 העשוי מסמרטוטים — \u0003אסור להדוקיה ביומא טבא\u0004 \u0005[להדק אותו ביום טוב],\u0006 משום שהוא סוחט נוזל מתוכם. והרי זה דבר שאינו מתכוון!","ומשיבים: \u0003בההיא\u0004 \u0005[\u0006בהלכה \u0005זו]\u0006 \u0003אפילו ר' שמעון,\u0004 הסבור כי דבר שאין מתכוון מותר, גם הוא \u0003מודה\u0004 שהדבר אסור, וכפי ש\u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003מודה ר' שמעון ב\"פסיק רישיה ולא ימות\"\u0004 \u0005[חתוך ראשו ולא ימות],\u0006 כלומר, כאשר התוצאה היא הכרחית — אין זה משנה אם הוא מתכוון לה או לא. אבל כשעושה מקום בקופיץ — ייתכן שלא ייתלש שיער, ולפיכך מותר הדבר, משום שאינו מתכוון.","ומקשים: והאם סבור רב כר' שמעון, שדבר שאינו מתכוון מותר? \u0003והא\u0004 \u0005[והרי]\u0006 כשדנו בפסיקת ההלכה בענין זה, אמר רב חייא בר אשי אמר רב: הלכה כר' יהודה, שדבר שאין מתכוון אסור, \u0003ורב חנן בר אמי אמר שמואל: הלכה כר' שמעון,\u0004 שדבר שאין מתכוון מותר. \u0003ורב חייא בר אבין מתני\u0004 \u0005[\u0006היה \u0005שונה]\u0006 את דברי רב ושמואל \u0003בלא גברי\u0004 \u0005[אנשים]\u0006 שאמרו את הדבר בשמם, \u0003רב אמר: הלכה כר' יהודה, ושמואל אמר: הלכה כר' שמעון!\u0004","\u0003אלא, לעולם סבר\u0004 \u0005[סבור]\u0006 \u0003רב: דבר שאין מתכוין\u0004 — \u0003אסור, ו\u0004טעם הדבר שהוא פוסק כר' יוסי בן המשולם במשנתנו, הרי זה משום ש\u0003תולש לאו היינו\u0004 \u0005[אינו\u0006 נחשב\u0005]\u0006 \u0003גוזז. וביום טוב,\u0004 שיש בו איסור עקירת דבר מגידולו — \u0003היינו טעמא דשרי\u0004 \u0005[זהו הטעם שמתיר],\u0006 משום \u0003דהוה ליה\u0004 \u0005[שהריהו]\u0006 \u0003עוקר דבר מגידולו כלאחר יד,\u0004 שלא כדרכו, שהרי אין תולשים צמר אלא גוזזים, ואין זה בכלל המלאכה שנאסרה מן התורה.","ושואלים: \u0003ותולש לאו היינו\u0004 \u0005[\u0006האם \u0005אינו\u0006 נחשב\u0005]\u0006 \u0003גוזז? והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא]: \u0003התולש\u0004 בשבת \u0003את הכנף\u0004 (נוצה) מן העוף, \u0003והקוטמו,\u0004 החותך את ראשה של הנוצה, \u0003והמורטו,\u0004 המורט ממנה את השיער ומשאיר בידו קנה חלק — \u0003חייב שלש חטאות\u0004 (כשעשה זאת בשוגג). \u0003ואמר ריש לקיש\u0004 בבירור הדברים: \u0003תולש\u0004 — \u0003חייב משום\u0004 מלאכת \u0003גוזז, קוטם\u0004 — \u0003חייב משום מחתך, ממרט\u0004 — \u0003חייב משום ממחק\u0004 (מחליק)! ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 תלישת \u0003כנף, דהיינו אורחיה\u0004 \u0005[שזהו דרכו],\u0006 שתולשים את הנוצה מן העוף. אבל צמר אין תולשים, אלא גוזזים.","ומדייקים: \u0003ומ\u0004כיון ש\u0003רב סבר\u0004 \u0005[סבור]\u0006 \u0003כר' יוסי בן המשולם,\u0004 שהוא פוסק הלכה כמותו, יש לומר ש\u0003ר' יוסי בן המשולם סבר לה\u0004 \u0005[סבור]\u0006 \u0003כ\u0004דעת \u0003רב,\u0004 שדבר שאין מתכוון אסור. ומקשים: \u0003ו\u0004האם \u0003סבר\u0004 \u0005[סבור]\u0006 \u0003ר' יוסי בן המשולם\u0004 ש\u0003דבר שאין מתכוין אסור?\u0004","\u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 פרה אדומה, ששתי שערות שחורות לגמרי פוסלות בה, שהיו לה \u0003שתי שערות\u0004 ש\u0003עיקרן\u0004 (חלקן התחתון, הקרוב לעור) \u0003מאדים,\u0004 אדום, \u0003ו\u0004אולם \u0003ראשן משחיר, ר' יוסי בן המשולם אומר: גוזז במספרים\u0004 את ראשן השחור, ואז נמצאת הפרה כולה אדומה, \u0003ואינו חושש\u0004 משום איסור גיזה בקדשים, משום שאינו מתכוון לגזוז את הפרה, אלא להכשירה!","ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003פרה\u0004 אדומה, שהתיר ר' יוסי בן המשולם לגוזזה, משום שפרה בכלל \u0003לאו\u0004 \u0005[אינה]\u0006 \u0003בת גיזה היא,\u0004 שהרי אין לה צמר, ולא חל עליה איסור גזיזת קדשים. ומקשים: וכי אין איסור גיזה בפרה? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 נאמר \u0003\"לא תעבד בבכר שורך ולא תגז בכור צאנך\"\u0004 (דברים טו, יט), \u0003ו\u0004מעירים: \u0003אין לי אלא שור\u0004 שהוא אסור \u0003בעבודה, וצאן\u0004 שאסור \u0003בגיזה, מנין ליתן את האמור של זה בזה, ואת האמור של זה בזה,\u0004 שגם שור וגם צאן אסורים בין בגיזה ובין בעבודה? \u0003תלמוד לומר: \"לא תעבד... ולא תגז\",\u0004 בו' החיבור. הרי שגם בשור (ופרה) יש איסור גיזה!","\u0003אלא\u0004 צריך לומר טעם אחר: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003פרה\u0004 אדומה, שהתיר ר' יוסי בן המשולם לגזוז את שערותיה, מפני שבכלל \u0003קדשי בדק הבית היא,\u0004 שהיא מנכסי המקדש, אבל אינה קריבה על המזבח. ולא נאסרה גיזה ועבודה אלא בקדשי מזבח, כעין בכור, שנאמר בו איסור זה. ומקשים, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אלעזר: קדשי בדק הבית אסורין בגיזה ועבודה!\u0004 ומשיבים: איסור זה הוא רק \u0003מדרבנן\u0004 \u0005[מדברי חכמים]\u0006 ולא מן התורה. ומקשים: \u0003והאיכא איסורא דרבנן\u0004 \u0005[והרי\u0006 על כל פנים \u0005יש\u0006 בכך \u0005איסור מדברי סופרים],\u0006 וכיצד אומר ר' יוסי שגוזז ואינו חושש! ומתרצים: \u0003אלא שאני\u0004 \u0005[שונה]\u0006 \u0003פרה\u0004 אדומה, דלא שכיחא \u0005[שאינה מצויה],\u0006 ולכן התיר בה ר' יוסי בן המשולם את הדבר.","ושואלים: מדוע להיזקק להיתר זה? \u0003וליחלה\u0004 \u0005[ושיחלל אותה]\u0006 כנגד מעות בשוויה, \u0003ולפקה\u0004 \u0005[ויוציא אותה]\u0006 \u0003לחולין, וליגזה\u0004 \u0005[ו\u0006אז \u0005יגזוז אותה],\u0006 \u0003והדר ליקדשה\u0004 \u0005[ו\u0006לאחר מכן \u0005יחזור ויקדישנה]!\u0006 ומשיבים: \u0003דמיה\u0004 של פרה אדומה \u0003יקרין,\u0004 ואין מעות מזומנים לפדותה בהם. ומקשים: \u0003וליעבד לה\u0004 \u0005[ושיעשה לה]\u0006 \u0003כ\u0004מו שאמר \u0003שמואל,\u0004 ש\u0003אמר שמואל: הקדש\u0004 שהוא \u0003שוה\u0004 אפילו \u0003מנה\u0004 (מאה דינר) \u0003שחיללו על שוה פרוטה\u0004 — \u0003מחולל,\u0004 יצא לחולין! ומשיבים: \u0003אימור\u0004 \u0005[אמור]\u0006 ש\u0003אמר שמואל\u0004 דבר זה במקרה \u0003שחיללו,\u0004 בדיעבד, אבל \u0003לכתחלה מי\u0004 \u0005[האם]\u0006 \u0003אמר\u0004 שמותר? עד כאן הסברנו, כיצד מתיר ר' יוסי בן המשולם לגזוז שיער שחור של פרה אדומה, לפי ההנחה שהוא סבור כרב, שדבר שאין מתכוון אסור.","ומוסיפים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 הסבר שונה: \u0003רב\u0004 אמנם \u0003סבר לה\u0004 \u0005[סבור]\u0006 \u0003כר' יוסי בן המשולם,\u0004 שתולש אינו נחשב גוזז, \u0003ו\u0004אולם \u0003ר' יוסי בן המשולם לא סבר לה\u0004 \u0005[אינו סבור]\u0006 \u0003כרב,\u0004 אלא לדעתו דבר שאינו מתכוון מותר, ולכן הוא מתיר לגזוז פרה אדומה — מפני שאינו מתכוון לגזיזה.","שנינו במשנה: \u0003ותולש את השער ובלבד שלא יזיזנו ממקומו. אמר רב אשי אמר ריש לקיש: לא שנו אלא\u0004 שתולש \u0003ביד, אבל בכלי\u0004 — \u0003אסור.\u0004 ומקשים, \u0003והקתני\u0004 \u0005[והרי\u0006 הוא שונה] במשנה: \u0003עושה מקום בקופיץ מיכן ומיכן,\u0004 ותולש את השיער. משמע שאפשר לעשות זאת בקופיץ, שהוא כלי! ומשיבים, \u0003תני\u0004 \u0005[שנה]:\u0006 \u0003\"לקופיץ\",\u0004 שאינו עושה מקום בקופיץ, אלא עושה מקום בידו כדי שיוכל לשחוט בקופיץ.","שנינו במשנה: \u0003וכן תולש את השער לראות מום. איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 שאלה ללומדים: האם הכוונה היא שמותר לעשות זאת \u0003לכתחלה\u0004 כדי לראות את מקום המום, כפי שהותר הדבר לצורך שחיטה, \u0003או\u0004 רק ב\u0003דיעבד,\u0004 שאם עשה כן — לא יזיזנו ממקומו? \u0003אמר ר' ירמיה, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו בברייתא: \u0003צמר המסובך באוזן,\u0004 המכסה את אוזן הבכור, ויש באוזן מום שצריך להראותו לחכם, \u0003ר' יוסי בן המשולם אומר: תולשו\u0004 את הצמר, \u0003ומראה\u0004 לחכם \u0003את מומו. שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003לכתחלה\u0004 אמר, שמותר לתולשו. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006","\u0003אמר רב מרי: אף אנן נמי תנינא\u0004 \u0005[אף אנו גם כן שנינו]\u0006 דבר זה במשנתנו: \u0003וכן התולש את השער לראות מקום מום. מאי\u0004 \u0005[מהו]\u0006 לשון \u0003\"וכן\"?\u0004 לאיזו מן ההלכות שנאמרו בתחילה היא מתייחסת? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 לענין \u0003שלא יזיזו את\u0004 השיער שנתלש מ\u0003מקומו\u0004 — לשם מה הוצרך לומר דבר זה? \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003ומה\u0004 במקרה ש\u0003שוחט\u0004 את הבכור, ש\u0003שחיטתו מוכחת\u0004 (מוכיחה) \u0003עליו\u0004 שלא היתה כוונתו לגיזה, אמר ר' יוסי בן המשולם ש\u0003לא יזיזנו,\u0004 כדי שלא ייראה הדבר כגיזה בקדשים, האם כאשר תולש את הצמר רק כדי \u0003לראות מקום\u0004 ה\u0003מום,\u0004 ואין מעשה המוכיח שאינו גוזז, \u0003מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר שלא יזיזנו?","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 לענין ה\u0003תולש\u0004 מתייחסת ההשוואה? \u0003שמע מינה\u0004 \u0005[למד מכאן],\u0006 איפוא, שמה שנאמר \"וכן התולש\" \u0003לכתחלה\u0004 נאמר. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003שער\u0004 של \u0003בכור בעל מום שנשר\u0004 מאליו \u0003והניחו בחלון, ואחר כך שחטו,\u0004 והרי צמרו מותר לאחר מיתה, מה דינו של הצמר שנשר בחייו? \u0003עקביא בן מהללאל מתיר\u0004 את השימוש בו,"],["\u0003וחכמים אוסרין,\u0004 אלו \u0003דברי ר' יהודה. אמר לו ר' יוסי: לא ב\u0004מקרה של \u0003זה\u0004 שנשחט \u0003התיר עקביא בן מהללאל, אלא\u0004 ב\u0003שער בעל מום שנשר והניחו בחלון, ואחר כך מת\u0004 הבכור — \u0003בזה עקביא בן מהללאל מתיר\u0004 את השיער שנשר בחייו, \u0003וחכמים אוסרין.\u0004 וכל זה הוא בצמר שנשר מן הבכור, שחכמים אוסרים אותו גם לאחר מותו.","אבל \u0003צמר המדולדל בבכור,\u0004 שאמנם אינו מחובר לגופו, אבל לא נשר ממנו, \u0003את ש\u0004הוא \u0003נראה\u0004 כחלק אחד \u0003עם הגיזה\u0004 — \u0003מותר, ואת שאינו נראה עם הגיזה\u0004 — \u0003אסור.\u0004","שנינו במשנה שר' יוסי אומר כי לא בזה שנשחט התיר עקביא את השיער שנשר בחייו, אלא בזה שמת. ותמהים: \u0003מכלל\u0004 דברי ר' יוסי אתה למד שאם נשחט הבכור, \u0003דאסר\u0004 \u0005[ש\u0006עקביא \u0005אוסר]\u0006 את השיער שנשר בחייו? \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 לפי דבריו, \u0003ב\u0004מקרה ש\u0003מת\u0004 — \u0003שרי\u0004 \u0005[מותר]\u0006 השיער, למרות שהשיער שעל גופו אסור, שהרי קדשים שמתו (ולא נשחטו) אסורים בהנאה, וכי במקרה ש\u0003שחטו,\u0004 כשהשיער שעליו מותר, \u0003מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שהצמר שנשר מתחילה גם הוא מותר?!","\u0003אלא\u0004 יש להבין את דברי ר' יוסי ביחס לדעת חכמים, וכך כוונתו: \u0003לא בזה\u0004 שנשחט \u0003התיר עקביא וחכמים אוסרין,\u0004 אלא אם \u0003שחטו\u0004 — \u0003דברי הכל שרי\u0004 \u0005[מותר]\u0006 השיער, וגם לדעת חכמים, אלא \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003ב\u0004מקרה ש\u0003מת,\u0004 שעקביא מתיר גם במקרה זה את השיער שנשר בחייו. ולדעת חכמים דינו של שיער זה כדינו של השיער שעל גופו, שהוא אסור.","\u0003אמר ר' אסי אמר ריש לקיש: מחלוקת\u0004 עקביא בן מהללאל וחכמים, הריהי במקרה \u0003ש\u0004קודם שנשר השיער כבר \u0003התירו מומחה\u0004 שמוסמך להתיר בכורות בשחיטה, \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003גזרינן דלמא אתי לשהוייה\u0004 \u0005[גוזרים אנו\u0006 איסור על השיער שנשר ממנו בחייו, \u0005שמא יבוא להשהותו,\u0006 את הבכור\u0005],\u0006 ולא ישחטנו, כדי ליהנות מן השיער הנושר ממנו, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 עקביא, \u0005סבור]:\u0006 \u0003לא גזרינן\u0004 \u0005[אין אנו גוזרים],\u0006 שאין לחשוש לכך, שכיון שהתירו החכם בשחיטה — הריהו שוחטו מיד. \u0003אבל\u0004 אם \u0003לא התירו מומחה\u0004 — \u0003דברי הכל אסור\u0004 השיער שנשר ממנו, גם לאחר שמת או שנשחט.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב ששת\u0004 ממה ששנינו בברייתא: \u0003בעלי מומין\u0004 פסולים להקרבה, שנתערבו בקדשים כשרים — \u0003אוסרין בכל שהוא,\u0004 שאפילו נתערב אחד באלף — כולם אסורים בהקרבה. \u0003ור' יוסי אומר: יבקר\u0004 (ייבדק) הדבר.","\u0003והוינן בה\u0004 \u0005[והיינו מתקשים בה]:\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"יבקר\"? אלימא\u0004 \u0005[אם תאמר]\u0006 שייבדק העדר ויימצא אותו אחד ש\u0003בעל מום הוא, ולישקליה\u0004 \u0005[ושיטול אותו],\u0006 וכל השאר מותרים בהקרבה — \u0003מכלל\u0004 הדברים אתה למד \u0003דתנא קמא אמר לאו\u0004 \u0005[שהתנא הראשון אומר לא],\u0006 שלא ניתן לסמוך על כך ולהתיר את כל העדר? ומדוע לא? והרי בעל המום לפנינו!","\u0003אמר רב נחמן אמר רבה בר אבוה:\u0004 אין מדובר בתערובת של בהמות, אלא \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003בגיזת בכור בעל מום עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שנשרה ממנו בחייו, ובמקרה \u0003שנתערבו\u0004 (שנתערבה) \u0003בגיזי חולין. ומאן תנא קמא\u0004 \u0005[ומיהו התנא הראשון]\u0006 האוסר גיזה זו? דעת ר' יהודה היא, \u0003דאמר\u0004 \u0005[שאומר]\u0006 במשנתנו, כי גם במקרה ש\u0003נשחטו\u0004 בכורות בעלי מום \u0003אסרי רבנן\u0004 \u0005[אוסרים חכמים]\u0006 את הגיזה שנשרה מחיים. \u0003ו\u0004אילו \u0003ר' יוסי\u0004 הולך \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 \u0003דאמר\u0004 \u0005[ש\u0006הוא \u0005אומר]\u0006 שבמקרה ש\u0003נשחטו שרו רבנן\u0004 \u0005[מתירים חכמים]\u0006 את הגיזה שנשרה מחיים.","וקתני \u0005[ו\u0006הרי \u0005הוא שונה]:\u0006 \u0003\"יבוקר\",\u0004 שיש צורך לבדוק בכור זה, כדי להתיר את הגיזה. ויש לשאול: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"יבוקר\"? לאו\u0004 \u0005[האם לא]\u0006 שיראה מומחה \u0003אי\u0004 \u0005[אם]\u0006 הוא \u0003מום קבוע,\u0004 או \u0003אי\u0004 \u0005[אם]\u0006 \u0003מום עובר הוא?\u0004 ונמצא שאם היה בעל מום קבוע, הגיזה שנשרה מותרת לדעת ר' יוסי, \u0003אף על גב שלא התירו מומחה\u0004 קודם לכן, ושלא כדברי ר' אסי בשם ריש לקיש שלדעת הכל היא אסורה!","\u0003אמר רבא: לא,\u0004 אין מכאן ראיה, ולשיטת ריש לקיש יש לפרש כך: \u0003יבוקר,\u0004 ייבדק בכור זה אם כבר התירו מומחה, \u0003אי\u0004 \u0005[אם]\u0006 \u0003התירו מומחה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 צמרו שנשר מותר, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 התירו מומחה — \u0003לא.\u0004","מסופר, \u0003כי סליק\u0004 \u0005[כאשר עלה]\u0006 \u0003רבין\u0004 מבבל לארץ ישראל, \u0003אמרה לשמעתא קמיה\u0004 \u0005[אמר את השמועה\u0006 הזו \u0005לפני]\u0006 \u0003ר' ירמיה,\u0004 כיצד פירשו ברייתא זו, לא בבעלי מום ממש, שנתערבו בתמימים, אלא בגיזת בכור בעל מום שנתערבה בגיזות אחרות. \u0003אמר\u0004 ר' ירמיה: \u0003בבלאי טפשאי\u0004 \u0005[בבלים טפשים],\u0006 \u0003משום דיתבי בארעא דחשוכא אמרי שמעתא דמחשכן\u0004 \u0005[משום ש\u0006הם \u0005יושבים בארץ חשוכה\u0006 הם \u0005אומרים שמועות חשוכות],\u0006 כלומר, שאינן בהירות וברורות, וכי \u0003לא שמיע להו הא דאמר\u0004 \u0005[לא שמעו את זו שאומר]\u0006 \u0003ר' חייא בר אבא אמר ר' יוחנן: מחלוקת\u0004 ר' יוסי וחכמים, האם בדיקה מועילה לתערובת בהמות בעלות מום ובהמות כשרות, הריהי \u0003בשבדק\u0004 את הבהמות \u0003ולא מצא\u0004 את בעל המום ביניהן, האם מסתמכים על הבדיקה או לא.","\u0003וקמיפלגי בפלוגתא\u0004 \u0005[וחלוקים הם במחלוקת]\u0006 של \u0003ר' מאיר ורבנן\u0004 \u0005[וחכמים]\u0006 בענין שדה שהיה בה קבר ואבד, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005],\u0006 \u0003שהיה ר' מאיר אומר: כל דבר שהיה בחזקת טומאה,\u0004 כגון שדה זו שהיה בה קבר — \u0003לעולם הוא בטומאתו,\u0004 גם אם לא יימצא בו דבר, \u0003עד שיתוודע\u0004 מקום \u0003הטומאה,\u0004 ואז יהא מותר כל שאר השדה.","\u0003וחכמים אומרים: חופר\u0004 בכל השדה \u0003עד שמגיע לסלע או ל\u0004אדמה \u0003בתולה\u0004 (שלא נעבדה), ואם לא מצא כלום — השדה טהורה. וכך לענייננו, דעת ר' יוסי, שאמר: יבוקר — היא כדעת חכמים החולקים על ר' מאיר, וסומכים על הבדיקה, ודעת התנא הראשון כדעת ר' מאיר החולק.","ומעירים: כך פירש ר' חייא בר אבא בשם ר' יוחנן, ואילו \u0003ר' אסי אמר\u0004 בשם \u0003ר' יוחנן\u0004 כך: \u0003מחלוקת\u0004 ר' יוסי וחכמים היא \u0003כשבדק\u0004 את תערובת הבהמות, \u0003ומצא\u0004 בעל מום, ונחלקו האם בכח בדיקה זו להתיר את השאר. \u0003וקמיפלגי בפלוגתא\u0004 \u0005[וחלוקים הם במחלוקת]\u0006 של \u0003רבי ורבן שמעון בן גמליאל,\u0004","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003שדה שאבד בה קבר,\u0004 מי ש\u0003נכנס בתוכה\u0004 — הריהו \u0003טמא.\u0004 נבדקה ו\u0003נמצא בתוכה קבר,\u0004 אם \u0003נכנס לתוכה\u0004 — \u0003טהור, שאני אומר: הוא\u0004 ה\u0003קבר שאבד הוא\u0004 ה\u0003קבר שנמצא,\u0004 אלו הם \u0003דברי רבי. רבן שמעון בן גמליאל אומר:\u0004 אין סומכים על קבר שנמצא שם, שמא יש שם עוד אחד, אלא \u0003תיבדק כל השדה כולה.\u0004 ר' יוסי סבור כרבי, וסומך על הבדיקה כשנמצא בתערובת בעל מום, והתנא הראשון סבור כרבן שמעון, וחושש לבעל מום אחר שהיה שם.","ושואלים: \u0003ור' אסי\u0004 שפירש כך בשם ר' יוחנן, \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 לא אמר כר' חייא בר אבא, שנחלקו במחלוקת ר' מאיר וחכמים, בדין שדה שאבד בה קבר ולא נמצא? ומשיבים, \u0003אמר\u0004 \u0005[יכול הוא לומר]\u0006 \u0003לך: בשלמא\u0004 \u0005[נניח]\u0006 ל\u0003גבי טומאה,\u0004 גם אם לא נמצאה הטומאה, \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003בא עורב ונטלה,\u0004 או \u0003בא עכבר ונטלה,\u0004 ולכן לדעת חכמים יש מקום להסתמך על הבדיקה. \u0003אלא הכא\u0004 \u0005[כאן],\u0006 כשנתערב בעל מום בבהמות כשרות — \u0003בעל מום להיכא אזיל\u0004 \u0005[להיכן הלך]?\u0006 ולכן אם בדק ולא מצא — ודאי לא בדק כראוי, ואין להתיר את התערובת לדעת הכל. ושואלים: \u0003ואידך\u0004 \u0005[והאחר],\u0006 ר' חייא בר אבא, מה הוא משיב לטענה זו? ומשיבים: לדעתו, גם בתערובת בעל מום בתמימים ניתן לומר כן — \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003מום עובר הוה\u0004 \u0005[היה]\u0006 באותו בעל מום \u0003ואיתסי\u0004 \u0005[והתרפא],\u0006 ולכן לא מצאו.","ושואלים: \u0003ור' חייא בר אבא מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כר' אסי,\u0004 שנחלקו במקרה שבדק ומצא, וכמחלוקת רבי ור' אלעזר בר' שמעון? ומשיבים, \u0003אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לך: בשלמא\u0004 \u0005[נניח]\u0006 \u0003שדה, דרכה למיקבר\u0004 \u0005[לקבור] בה,\u0006 ויש לומר: \u0003כי היכי דקבר בה האי\u0004 — \u0003קבר אינש אחרינא\u0004 \u0005[כמו שקבור בה זה — קבור בה גם אדם אחר],\u0006 ולכן סבור ר' אלעזר בר' שמעון כי יש לבדוק את השדה כולה. \u0003אלא קדשים, כיון דבדקו לן וקיימי\u0004 \u0005[שהם בדוקים לנו ועומדים],\u0006 \u0003דרכייהו למיפל בהו מומא\u0004 \u0005[\u0006וכי \u0005דרכם שיפול בהם מום]?\u0006 ושואלים: \u0003ואידך\u0004 \u0005[והאחר],\u0006 ר' אסי, מה הוא סבור? ומשיבים: \u0003אגב דמנגחי אהדדי שכיח בהו מומא\u0004 \u0005[שהם נוגחים זה את זה, מצוי בהם המום].\u0006","ושבים לדברי ר' אסי בשם ריש לקיש, שאף עקביא בן מהללאל לא התיר שער בכור בעל מום שנשר בחייו, אלא אם התירו מומחה בשחיטה קודם לכן. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003התולש צמר מבכור תם, אף על פי שנולד בו\u0004 אחר כך \u0003מום ושחטו\u0004 — בכל זאת הצמר \u0003אסור.\u0004 ויש לדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום שהיה \u0003תם\u0004 בשעה שנשר — הצמר אסור,"]]};
